/// A bare `:` (empty pattern) lists every segment indexed across
/// every file. A segment is a whole header (level 1-4) plus
/// everything below it up to the next level-<=4 header, so
/// `setup_todo_db`'s fixture — each file has exactly ONE level-1
/// header with everything else nested under it, no other headers
/// — indexes to exactly one segment per file:
///   older.md: the entire "# Older" section (header + all 4
///             todo/prose lines below it, joined with " / ")
///   newer.md: the entire "# Newer" section (header + both todo
///             lines below it)
/// 2 segments total.
#[test]
fn fetch_segments_lists_all_segments() {
    let (dir, db_path) = setup_todo_db();
    let mut app = global_test_app(&[("a", 1)]);
    app.notes_dir = Some(dir.clone());
    app.notes_database = Some(db_path.clone());
    app.query = ":".to_string();
    app.refresh();
    drive_segments_search(&mut app);
    assert_eq!(
        app.merged_rows().len(),
        2,
        "expected 2 segments (one per file — each file has a single \
         level-1 header covering its whole body), got: {:?}",
        app.merged_rows()
            .iter()
            .map(|r| &r.command)
            .collect::<Vec<_>>()
    );
    let _ = std::fs::remove_dir_all(&dir);
    let _ = std::fs::remove_file(&db_path);
}

/// `build_merged_rows` must take the same cheap early-return path
/// as panes mode for segment rows (`self.rows.clone()`, no
/// labeled-row interleave, no re-sort) rather than falling through
/// to the command-history "labeled rows" merge. That merge scans
/// every labeled row and re-sorts the whole result set on every
/// `refresh()` call — which runs on every keystroke — so for a
/// large notes vault it dwarfed the actual (already debounced,
/// backgrounded) search cost and was the real source of the
/// reported per-keystroke lag. This test locks in the fix by
/// planting a labeled row that would match the query text (so the
/// old code path would have pulled it in) and asserting it's
/// absent from the segments-mode result.
#[test]
fn merged_rows_in_segments_mode_does_not_interleave_labeled_rows() {
    let (dir, db_path) = setup_todo_db();
    let mut app = global_test_app(&[("a", 1)]);
    app.notes_dir = Some(dir.clone());
    app.notes_database = Some(db_path.clone());
    app.labeled_rows.push(crate::tui::state::HistoryRow {
        id: 999,
        command: "older unrelated labeled command".to_string(),
        directory: "/tmp".to_string(),
        session_id: String::new(),
        exit_code: 0,
        timestamp: 0,
        comment: "a bookmark, not a segment".to_string(),
        output: String::new(),
        mode: "history".to_string(),
        source: String::new(),
        ..Default::default()
    });
    app.query = ":older".to_string();
    app.refresh();
    drive_segments_search(&mut app);
    assert!(
        app.merged_rows().iter().all(|r| r.mode == "segment"),
        "labeled command-history rows must not be interleaved into segments-mode results, got: {:?}",
        app.merged_rows().iter().map(|r| (&r.mode, &r.command)).collect::<Vec<_>>()
    );
    let _ = std::fs::remove_dir_all(&dir);
    let _ = std::fs::remove_file(&db_path);
}

/// Paperless-mode rows are pre-sorted newest-`added`-first by
/// `paperless::spawn_search`. `merged_rows()` must preserve that
/// order verbatim — no labeled-row interleaving, and no
/// Frequency-sort override — even when the user has toggled
/// `SortOrder::Frequency` (`F4`) globally. Mirrors
/// `merged_rows_in_segments_mode_does_not_interleave_labeled_rows`.
#[test]
fn merged_rows_in_paperless_mode_preserves_added_order_and_ignores_frequency_sort() {
    let mut app = directories_test_app(&[]);
    app.sort_order = SortOrder::Frequency;
    app.labeled_rows.push(crate::tui::state::HistoryRow {
        id: 999,
        command: "older unrelated labeled command".to_string(),
        directory: "/tmp".to_string(),
        session_id: String::new(),
        exit_code: 0,
        timestamp: 0,
        comment: "a bookmark, not a document".to_string(),
        output: String::new(),
        mode: "history".to_string(),
        source: String::new(),
        ..Default::default()
    });
    app.paperless_state.rows = vec![
        crate::tui::state::HistoryRow {
            id: -2,
            command: "Newest document".to_string(),
            timestamp: 200,
            mode: "paperless".to_string(),
            source: "paperless".to_string(),
            ..Default::default()
        },
        crate::tui::state::HistoryRow {
            id: -1,
            command: "Oldest document".to_string(),
            timestamp: 100,
            mode: "paperless".to_string(),
            source: "paperless".to_string(),
            ..Default::default()
        },
    ];
    app.query = "<".to_string();
    app.refresh();
    let commands: Vec<String> = app.merged_rows().iter().map(|r| r.command.clone()).collect();
    assert_eq!(
        commands,
        vec!["Newest document", "Oldest document"],
        "paperless rows must keep the pre-sorted added-timestamp order, ignoring Frequency sort and labeled rows"
    );
}

/// A bare word in the typed pattern filters segments by substring
/// (via `QueryExpr::Text`, the fallback case of the `#tag` /
/// `[[link]]` query DSL `parse_query` produces). "prose" only
/// appears in older.md's body ("some prose in between"), so this
/// matches that file's single segment (the whole "# Older"
/// section) and not newer.md's.
#[test]
fn fetch_segments_applies_text_filter() {
    let (dir, db_path) = setup_todo_db();
    let mut app = global_test_app(&[("a", 1)]);
    app.notes_dir = Some(dir.clone());
    app.notes_database = Some(db_path.clone());
    app.query = ":prose".to_string();
    app.refresh();
    drive_segments_search(&mut app);
    let commands: Vec<String> = app
        .merged_rows()
        .iter()
        .map(|r| r.command.clone())
        .collect();
    assert_eq!(
        commands.len(),
        1,
        "expected exactly the '# Older' segment (it's the only one containing \"prose\"), got: {:?}",
        commands
    );
    assert!(commands[0].contains("prose"), "got: {:?}", commands);
    let _ = std::fs::remove_dir_all(&dir);
    let _ = std::fs::remove_file(&db_path);
}

/// Helper: index a single custom markdown file (with a frontmatter
/// link, a heading-level inline tag, and nested list items) into a
/// fresh `note_search` DB, for testing the `#tag` / `[[link]]`
/// query DSL against segments specifically. The whole file is ONE
/// segment (a single level-1 header, "# Project X #urgent", with
/// no other headers to split on) — see the module-doc comment on
/// `fetch_segments_frontmatter_link_does_not_cascade` for why that
/// matters.
fn setup_segments_cascade_db() -> (std::path::PathBuf, std::path::PathBuf) {
    use rusqlite::Connection;
    use std::fs;
    use std::sync::atomic::{AtomicU64, Ordering};
    static COUNTER: AtomicU64 = AtomicU64::new(0);
    let n = COUNTER.fetch_add(1, Ordering::SeqCst);
    let dir = std::env::temp_dir().join(format!(
        "smarthistory-segments-cascade-{}-{}",
        std::process::id(),
        n
    ));
    let _ = fs::remove_dir_all(&dir);
    fs::create_dir_all(&dir).expect("create notes dir");
    fs::write(
        dir.join("project.md"),
        "---\n\
                         ref: [[NeoVimNote]]\n\
                         ---\n\
                         # Project X #urgent\n\
                         \n\
                         - [[SomeLink]] project reference\n\
                         \x20\x20\x20\x20* Sub-note with more detail\n\
                         - [[Auto]] a different reference\n",
    )
    .expect("write project.md");
    let db_path = std::env::temp_dir().join(format!(
        "smarthistory-segments-cascade-db-{}-{}.sqlite",
        std::process::id(),
        n
    ));
    let _ = fs::remove_file(&db_path);
    let conn = Connection::open(&db_path).expect("open db");
    note_search::init_database_schema(&conn)
        .map_err(|e| format!("schema: {e}"))
        .expect("init schema");
    let data = note_search::markdown_parser::process_markdown_file(&dir.join("project.md"), &dir)
        .expect("process file");
    note_search::write_markdown_data_to_sqlite_with_conn(&data, &conn)
        .map_err(|e| format!("write: {e}"))
        .expect("write db");
    drop(conn);
    (dir, db_path)
}

/// Fixture for the `segments.minwords` filter
/// (`App::segments_min_words`): one file with three level-1
/// segments —
///   "Short Section": body is 3 words ("one two three") — at or
///     under the default threshold (5), should be dropped.
///   "Long Section": body is 8 words — over the threshold, should
///     be kept.
///   "This Heading Has Seven Words Total": a 7-word HEADING with a
///     1-word body ("short") — proves the header line itself is
///     excluded from the count: if it were wrongly included
///     (7 + 1 = 8 > 5) this segment would survive; correctly
///     excluded, its body-only count (1) is under the threshold and
///     it's dropped.
fn setup_segments_minwords_db() -> (std::path::PathBuf, std::path::PathBuf) {
    use rusqlite::Connection;
    use std::fs;
    use std::sync::atomic::{AtomicU64, Ordering};
    static COUNTER: AtomicU64 = AtomicU64::new(0);
    let n = COUNTER.fetch_add(1, Ordering::SeqCst);
    let dir = std::env::temp_dir().join(format!(
        "smarthistory-segments-minwords-{}-{}",
        std::process::id(),
        n
    ));
    let _ = fs::remove_dir_all(&dir);
    fs::create_dir_all(&dir).expect("create notes dir");
    fs::write(
        dir.join("sections.md"),
        "# Short Section\n\
         one two three\n\
         \n\
         # Long Section\n\
         one two three four five six seven eight\n\
         \n\
         # This Heading Has Seven Words Total\n\
         short\n",
    )
    .expect("write sections.md");
    let db_path = std::env::temp_dir().join(format!(
        "smarthistory-segments-minwords-db-{}-{}.sqlite",
        std::process::id(),
        n
    ));
    let _ = fs::remove_file(&db_path);
    let conn = Connection::open(&db_path).expect("open db");
    note_search::init_database_schema(&conn)
        .map_err(|e| format!("schema: {e}"))
        .expect("init schema");
    let data = note_search::markdown_parser::process_markdown_file(&dir.join("sections.md"), &dir)
        .expect("process file");
    note_search::write_markdown_data_to_sqlite_with_conn(&data, &conn)
        .map_err(|e| format!("write: {e}"))
        .expect("write db");
    drop(conn);
    (dir, db_path)
}

/// The default `segments_min_words` (5) drops segments whose body
/// (header excluded) has 5 words or fewer, and keeps ones over it.
/// See `setup_segments_minwords_db` for the fixture's exact word
/// counts, including the header-exclusion case.
#[test]
fn fetch_segments_minwords_filters_short_bodies_by_default() {
    let (dir, db_path) = setup_segments_minwords_db();
    let mut app = global_test_app(&[("a", 1)]);
    app.notes_dir = Some(dir.clone());
    app.notes_database = Some(db_path.clone());
    assert_eq!(app.segments_min_words, 5, "default threshold");
    app.query = ":".to_string();
    app.refresh();
    drive_segments_search(&mut app);
    let commands: Vec<&String> = app.merged_rows().iter().map(|r| &r.command).collect();
    assert_eq!(
        app.merged_rows().len(),
        1,
        "only \"Long Section\" (8-word body) should survive the default \
         5-word threshold, got: {commands:?}"
    );
    assert!(
        commands[0].contains("Long Section"),
        "got: {commands:?}"
    );
    let _ = std::fs::remove_dir_all(&dir);
    let _ = std::fs::remove_file(&db_path);
}

/// `segments.minwords=0` (via `App::segments_min_words = 0`)
/// disables the filter entirely — every segment from the same
/// fixture that lost two of its three segments above now survives.
#[test]
fn fetch_segments_minwords_zero_disables_filter() {
    let (dir, db_path) = setup_segments_minwords_db();
    let mut app = global_test_app(&[("a", 1)]);
    app.notes_dir = Some(dir.clone());
    app.notes_database = Some(db_path.clone());
    app.segments_min_words = 0;
    app.query = ":".to_string();
    app.refresh();
    drive_segments_search(&mut app);
    assert_eq!(
        app.merged_rows().len(),
        3,
        "minwords=0 must keep every segment, got: {:?}",
        app.merged_rows().iter().map(|r| &r.command).collect::<Vec<_>>()
    );
    let _ = std::fs::remove_dir_all(&dir);
    let _ = std::fs::remove_file(&db_path);
}

/// A higher configured threshold filters more aggressively — with
/// `segments_min_words = 8`, even "Long Section" (exactly 8 words)
/// is dropped, since the filter keeps strictly-greater-than the
/// threshold, not greater-or-equal.
#[test]
fn fetch_segments_minwords_higher_threshold_filters_more() {
    let (dir, db_path) = setup_segments_minwords_db();
    let mut app = global_test_app(&[("a", 1)]);
    app.notes_dir = Some(dir.clone());
    app.notes_database = Some(db_path.clone());
    app.segments_min_words = 8;
    app.query = ":".to_string();
    app.refresh();
    drive_segments_search(&mut app);
    assert!(
        app.merged_rows().is_empty(),
        "threshold=8 must drop every segment (max body is exactly 8 \
         words, filter keeps strictly > threshold), got: {:?}",
        app.merged_rows().iter().map(|r| &r.command).collect::<Vec<_>>()
    );
    let _ = std::fs::remove_dir_all(&dir);
    let _ = std::fs::remove_file(&db_path);
}

/// `:[[link]]` filters segments by the `#tag`/`[[link]]` query DSL
/// (`QueryExpr::Link`), not just plain substring text.
///
/// note_search's segments feature has changed its tag/link cascade
/// semantics twice now: the original element search cascaded a
/// heading/frontmatter tag or link to every element in scope; the
/// first segment redesign made segment tags/links come ONLY from a
/// segment's own text (no cascade at all, `breadcrumb` replacing it
/// for context); the version this test runs against reintroduced a
/// cascade — every segment's tags/links are now the UNION of its
/// own text, its ancestor headers' text, AND the whole document's
/// aggregate tags/links (so a frontmatter link/tag reaches every
/// segment in the file again, this time unconditionally rather
/// than only from a heading). This test locks in that CURRENT
/// behavior so a future note_search change would be caught here.
#[test]
fn fetch_segments_frontmatter_link_cascades_to_every_segment() {
    let (dir, db_path) = setup_segments_cascade_db();
    let mut app = global_test_app(&[("a", 1)]);
    app.notes_dir = Some(dir.clone());
    app.notes_database = Some(db_path.clone());
    // Baseline: the file's one segment, unfiltered.
    app.query = ":".to_string();
    app.refresh();
    drive_segments_search(&mut app);
    let total = app.merged_rows().len();
    assert_eq!(total, 1, "fixture should index exactly one segment");

    // The frontmatter `ref: [[NeoVimNote]]` link is part of the
    // document's aggregate link set, which is unioned into every
    // segment — so it matches the file's one segment.
    app.query = ":[[NeoVimNote]]".to_string();
    app.refresh();
    drive_segments_search(&mut app);
    assert_eq!(
        app.merged_rows().len(),
        total,
        "a frontmatter link must cascade to every segment in the file; got: {:?}",
        app.merged_rows().iter().map(|r| &r.command).collect::<Vec<_>>()
    );
    let _ = std::fs::remove_dir_all(&dir);
    let _ = std::fs::remove_file(&db_path);
}

/// `:[[link]]` on a link that appears in the segment's own body
/// text matches — the whole file is one segment (a single level-1
/// header, "# Project X #urgent", with no other headers to split
/// on), so this also demonstrates that a match anywhere in a
/// segment's text returns the WHOLE segment (header + all its
/// list items), not just the matching line.
#[test]
fn fetch_segments_filters_by_direct_link_match() {
    let (dir, db_path) = setup_segments_cascade_db();
    let mut app = global_test_app(&[("a", 1)]);
    app.notes_dir = Some(dir.clone());
    app.notes_database = Some(db_path.clone());
    app.query = ":[[SomeLink]]".to_string();
    app.refresh();
    drive_segments_search(&mut app);
    let commands: Vec<String> = app
        .merged_rows()
        .iter()
        .map(|r| r.command.clone())
        .collect();
    assert_eq!(
        commands.len(),
        1,
        "expected exactly the file's one segment, got: {:?}",
        commands
    );
    assert!(
        commands[0].contains("project reference"),
        "got: {:?}",
        commands
    );
    let _ = std::fs::remove_dir_all(&dir);
    let _ = std::fs::remove_file(&db_path);
}

/// `:#tag` on a tag that appears in the segment's own header line
/// matches — `# Project X #urgent` is the header of (and therefore
/// part of the text of) the file's one and only segment, so this
/// is a direct match on the segment's own text, not a cascade
/// (segments don't cascade tags/links from ancestor headers — see
/// `fetch_segments_frontmatter_link_does_not_cascade`).
#[test]
fn fetch_segments_filters_by_heading_own_tag() {
    let (dir, db_path) = setup_segments_cascade_db();
    let mut app = global_test_app(&[("a", 1)]);
    app.notes_dir = Some(dir.clone());
    app.notes_database = Some(db_path.clone());
    app.query = ":".to_string();
    app.refresh();
    drive_segments_search(&mut app);
    let total = app.merged_rows().len();

    app.query = ":#urgent".to_string();
    app.refresh();
    drive_segments_search(&mut app);
    assert_eq!(
        app.merged_rows().len(),
        total,
        "a tag in the segment's own header line must match that segment"
    );
    let _ = std::fs::remove_dir_all(&dir);
    let _ = std::fs::remove_file(&db_path);
}

/// `:#tag!` (trailing `!`) is the negated form: it excludes segments
/// that have the tag, rather than requiring it. `project.md`'s one
/// segment carries `#urgent` in its header, so `:#urgent!` excludes
/// it and the result is empty — the mirror image of
/// `fetch_segments_filters_by_heading_own_tag`. Same for
/// `:[[SomeLink]]!` against the direct link match exercised by
/// `fetch_segments_filters_by_direct_link_match`.
#[test]
fn fetch_segments_negation_excludes_matching_tag_and_link() {
    let (dir, db_path) = setup_segments_cascade_db();
    let mut app = global_test_app(&[("a", 1)]);
    app.notes_dir = Some(dir.clone());
    app.notes_database = Some(db_path.clone());
    app.query = ":".to_string();
    app.refresh();
    drive_segments_search(&mut app);
    let total = app.merged_rows().len();
    assert!(total > 0, "fixture must have at least one segment");

    app.query = ":#urgent!".to_string();
    app.refresh();
    drive_segments_search(&mut app);
    assert!(
        app.merged_rows().is_empty(),
        "negated tag must exclude the file's only segment, got: {:?}",
        app.merged_rows().iter().map(|r| &r.command).collect::<Vec<_>>()
    );

    app.query = ":[[SomeLink]]!".to_string();
    app.refresh();
    drive_segments_search(&mut app);
    assert!(
        app.merged_rows().is_empty(),
        "negated link must exclude the file's only segment, got: {:?}",
        app.merged_rows().iter().map(|r| &r.command).collect::<Vec<_>>()
    );
    let _ = std::fs::remove_dir_all(&dir);
    let _ = std::fs::remove_file(&db_path);
}

/// `:[key:value]!` is the negated form of the `[attr:value]`
/// header-attribute query for segments: it excludes segments whose
/// document has the attribute set to that value. Mirrors
/// `fetch_segments_negation_excludes_matching_tag_and_link` but for
/// the attribute DSL instead of tags/links.
#[test]
fn fetch_segments_negation_excludes_matching_attribute() {
    use rusqlite::Connection;
    use std::fs;
    use std::sync::atomic::{AtomicU64, Ordering};
    static COUNTER: AtomicU64 = AtomicU64::new(0);
    let n = COUNTER.fetch_add(1, Ordering::SeqCst);
    let dir = std::env::temp_dir().join(format!(
        "smarthistory-segments-attr-negation-{}-{}",
        std::process::id(),
        n
    ));
    let _ = fs::remove_dir_all(&dir);
    fs::create_dir_all(&dir).expect("create notes dir");
    fs::write(
        dir.join("project.md"),
        "---\ntype: project\n---\n\n# Project\n\nsome body text\n",
    )
    .expect("write project.md");
    let db_path = std::env::temp_dir().join(format!(
        "smarthistory-segments-attr-negation-db-{}-{}.sqlite",
        std::process::id(),
        n
    ));
    let _ = fs::remove_file(&db_path);
    let conn = Connection::open(&db_path).expect("open db");
    note_search::init_database_schema(&conn)
        .map_err(|e| format!("schema: {e}"))
        .expect("init schema");
    let data = note_search::markdown_parser::process_markdown_file(&dir.join("project.md"), &dir)
        .expect("process file");
    note_search::write_markdown_data_to_sqlite_with_conn(&data, &conn)
        .map_err(|e| format!("write: {e}"))
        .expect("write db");
    drop(conn);
    let mut app = global_test_app(&[("a", 1)]);
    app.notes_dir = Some(dir.clone());
    app.notes_database = Some(db_path.clone());
    // This test is about negation, not the `segments.minwords`
    // filter — the fixture's 3-word body is deliberately minimal
    // and would otherwise be dropped by the default threshold.
    app.segments_min_words = 0;
    app.query = ":".to_string();
    app.refresh();
    drive_segments_search(&mut app);
    let total = app.merged_rows().len();
    assert!(total > 0, "fixture must have at least one segment");

    app.query = ":[type:project]!".to_string();
    app.refresh();
    drive_segments_search(&mut app);
    assert!(
        app.merged_rows().is_empty(),
        "negated attribute must exclude the file's only segment, got: {:?}",
        app.merged_rows().iter().map(|r| &r.command).collect::<Vec<_>>()
    );
    let _ = std::fs::remove_dir_all(&dir);
    let _ = std::fs::remove_file(&db_path);
}

/// An invalid query (e.g. unbalanced parens) surfaces a status
/// message and returns an empty list, rather than silently
/// falling back to a literal-text search.
#[test]
fn fetch_segments_invalid_query_surfaces_status_message() {
    let (dir, db_path) = setup_todo_db();
    let mut app = global_test_app(&[("a", 1)]);
    app.notes_dir = Some(dir.clone());
    app.notes_database = Some(db_path.clone());
    app.query = ":(unbalanced".to_string();
    app.refresh();
    drive_segments_search(&mut app);
    assert!(app.merged_rows().is_empty());
    let status = app
        .status_message
        .as_ref()
        .map(|(s, _)| s.as_str())
        .unwrap_or("");
    assert!(status.contains("invalid query"), "got: {:?}", status);
    let _ = std::fs::remove_dir_all(&dir);
    let _ = std::fs::remove_file(&db_path);
}

/// A segment with a heading starts with a literal `#`/`##`/... in
/// `command`, same as the source markdown — because the segment's
/// own header line is verbatim the first line of `SegmentResult::text`
/// (see `map_segment_results`), not a prefix smarthistory adds
/// itself.
#[test]
fn fetch_segments_headings_start_with_hash() {
    let (dir, db_path) = setup_todo_db();
    let mut app = global_test_app(&[("a", 1)]);
    app.notes_dir = Some(dir.clone());
    app.notes_database = Some(db_path.clone());
    app.query = ":Older".to_string();
    app.refresh();
    drive_segments_search(&mut app);
    let heading_row = app
        .merged_rows()
        .iter()
        .find(|r| r.command.contains("Older"))
        .expect("the '# Older' segment should match");
    assert!(
        heading_row.command.starts_with('#'),
        "segment's command should start with its own header's literal '#'; got: {:?}",
        heading_row.command
    );
    let _ = std::fs::remove_dir_all(&dir);
    let _ = std::fs::remove_file(&db_path);
}

/// Selecting ANY segment row — heading, paragraph, or list item —
/// loads context from the underlying file into the output
/// preview, not just that segment's own isolated text. A bare
/// `[[link]]` reference line's own text can be as short as the
/// link name itself, which isn't useful as a preview on its own.
/// This fixture's file is short (well under the 50-line context
/// window), so the loaded context covers the entire file
/// regardless of which line matched — see
/// `ensure_selected_context_centers_window_on_match_line_for_long_file`
/// for the case where the file is longer than the window and the
/// window has to center on the match instead.
/// The preview must be RAW markdown, syntax-highlighted via
/// `highlight_with_bat_auto` (`syntect`) — the same "clean
/// content in, syntax-highlighted content out" pipeline `notes` /
/// `todo` mode use — not `tags`/`ag` mode's
/// `read_source_context_with_cache` format, which prefixes every
/// line with a right-aligned line number and marks the matched
/// line with `>>`. That annotation isn't valid markdown, so it
/// would fight the highlighter's heading/checkbox/link
/// highlighting instead of complementing it.
#[test]
fn ensure_selected_context_produces_clean_markdown_without_line_number_prefix() {
    let (dir, db_path) = setup_todo_db();
    let mut app = global_test_app(&[("a", 1)]);
    app.notes_dir = Some(dir.clone());
    app.notes_database = Some(db_path.clone());
    app.query = ":Older".to_string();
    app.refresh();
    drive_segments_search(&mut app);
    let heading_idx = app
        .merged_rows()
        .iter()
        .position(|r| r.command.starts_with('#'))
        .expect("heading row should be present");
    app.list_state.select(Some(heading_idx));
    crate::tui::mode::segments::ensure_selected_context(&mut app);
    let ansi_re = regex::Regex::new(r"\x1b\[[0-9;]*m").unwrap();
    let output = ansi_re
        .replace_all(&app.merged_rows()[heading_idx].output, "")
        .to_string();
    assert!(
        !output.contains(">>"),
        "output should not contain the tags/ag-style match marker, got: {:?}",
        output
    );
    assert!(
        output.trim_start().starts_with("# Older"),
        "output should start with the raw heading line, not a line-number-prefixed version; got: {:?}",
        output
    );
    let _ = std::fs::remove_dir_all(&dir);
    let _ = std::fs::remove_file(&db_path);
}

/// A segment's own `text` already covers its whole header-bounded
/// section (see the module doc comment — unlike the old element
/// search, there's no separate "heading row" vs "list-item row"
/// distinction anymore, since every list item under a header folds
/// into that header's ONE segment). This just confirms
/// `ensure_selected_context` loads the underlying file's full
/// content into `output` for that single segment row, not just an
/// isolated fragment.
#[test]
fn ensure_selected_context_loads_full_file_for_segment_row() {
    let (dir, db_path) = setup_todo_db();
    let mut app = global_test_app(&[("a", 1)]);
    app.notes_dir = Some(dir.clone());
    app.notes_database = Some(db_path.clone());
    app.query = ":Older".to_string();
    app.refresh();
    drive_segments_search(&mut app);
    // Strip ANSI escapes before asserting on substrings: the
    // highlighter syntax-highlights each token as its own colored
    // span, so a multi-token phrase like "# Older" (hash + space + word,
    // each separately styled) won't appear as one contiguous
    // substring in the raw (styled) output even though the text
    // is there.
    let ansi_re = regex::Regex::new(r"\x1b\[[0-9;]*m").unwrap();

    let idx = app
        .merged_rows()
        .iter()
        .position(|r| r.command.starts_with('#'))
        .expect("the '# Older' segment row should be present");
    app.list_state.select(Some(idx));
    crate::tui::mode::segments::ensure_selected_context(&mut app);
    let output = app.merged_rows()[idx].output.clone();
    let plain_output = ansi_re.replace_all(&output, "").to_string();
    assert!(
        plain_output.contains("Older")
            && plain_output.contains("older todo 1")
            && plain_output.contains("older todo 2"),
        "expected the full file's content in output, got: {:?}",
        plain_output
    );

    let _ = std::fs::remove_dir_all(&dir);
    let _ = std::fs::remove_file(&db_path);
}

/// `crate::tui::mode::similar::ensure_selected_context` is the same
/// windowed, syntax-highlighted preview code as segments mode's,
/// just reading from `similar_state` instead of `segments_state` —
/// this doesn't need a live Ollama instance to test, since it
/// operates purely on the selected row's `directory`/`session_id`
/// and the real file on disk, regardless of how that row got into
/// the list.
#[test]
fn ensure_selected_context_loads_full_file_for_similar_row() {
    use std::sync::atomic::{AtomicU64, Ordering};
    static COUNTER: AtomicU64 = AtomicU64::new(0);
    let n = COUNTER.fetch_add(1, Ordering::SeqCst);
    let dir = std::env::temp_dir().join(format!(
        "smarthistory-similar-context-{}-{}",
        std::process::id(),
        n
    ));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).expect("create dir");
    let file_path = dir.join("budget.md");
    std::fs::write(
        &file_path,
        "# Budget\n\nQ3 planning notes go here.\n\nMore detail below.\n",
    )
    .expect("write budget.md");

    let mut app = global_test_app(&[("a", 1)]);
    app.query = "\"budget".to_string();
    app.similar_state.rows = vec![crate::tui::state::HistoryRow {
        id: -1,
        command: "[0.91] # Budget / Q3 planning notes go here.".to_string(),
        directory: file_path.to_string_lossy().to_string(),
        session_id: "1".to_string(),
        exit_code: 0,
        timestamp: 0,
        comment: "budget.md".to_string(),
        output: String::new(),
        mode: "similar".to_string(),
        source: String::new(),
        ..Default::default()
    }];
    app.similar_state.last_pattern = Some("budget".to_string());
    app.refresh();

    let ansi_re = regex::Regex::new(r"\x1b\[[0-9;]*m").unwrap();
    let idx = app
        .merged_rows()
        .iter()
        .position(|r| r.mode == "similar")
        .expect("the similar-mode row should be present");
    app.list_state.select(Some(idx));
    crate::tui::mode::similar::ensure_selected_context(&mut app);
    let output = app.merged_rows()[idx].output.clone();
    let plain_output = ansi_re.replace_all(&output, "").to_string();
    assert!(
        plain_output.contains("Budget")
            && plain_output.contains("Q3 planning notes")
            && plain_output.contains("More detail below"),
        "expected the full file's content in output, got: {:?}",
        plain_output
    );

    let _ = std::fs::remove_dir_all(&dir);
}

/// `ensure_selected_context` runs on every keystroke (via
/// `App::refresh`), and `merged_rows` is rebuilt from scratch each
/// time (with the raw, unhighlighted segment text) — so without a
/// cache, re-selecting the same row on every keystroke would
/// re-run the highlighter every time, which is exactly the
/// per-keystroke blocking work the background search thread was
/// introduced to eliminate. Once a row's context has been computed, it must be
/// served from `SegmentsState::context_cache` on subsequent calls
/// for the same file/line, not recomputed.
#[test]
fn ensure_selected_context_caches_by_file_and_line() {
    let (dir, db_path) = setup_todo_db();
    let mut app = global_test_app(&[("a", 1)]);
    app.notes_dir = Some(dir.clone());
    app.notes_database = Some(db_path.clone());
    app.query = ":Older".to_string();
    app.refresh();
    drive_segments_search(&mut app);
    let heading_idx = app
        .merged_rows()
        .iter()
        .position(|r| r.command.starts_with('#'))
        .expect("heading row should be present");
    let filepath = app.merged_rows()[heading_idx].directory.clone();
    let line_number: usize = app.merged_rows()[heading_idx]
        .session_id
        .parse()
        .expect("session_id should be a line number");
    app.list_state.select(Some(heading_idx));

    crate::tui::mode::segments::ensure_selected_context(&mut app);
    let highlighted_output = app.merged_rows()[heading_idx].output.clone();
    assert_eq!(
        app.segments_state
            .context_cache
            .get(&(filepath.clone(), line_number)),
        Some(&highlighted_output),
        "cache should hold the just-computed highlighted output under (file, line)"
    );
    let cache_len_after_first = app.segments_state.context_cache.len();

    // Simulate the next keystroke: `refresh()` rebuilds
    // `merged_rows` from the still-raw cached search rows (so
    // `output` resets to the raw segment text) and then, as part
    // of its own per-mode context step, calls
    // `ensure_selected_context` again for the same selected row —
    // this must be served from the cache rather than re-running
    // the highlighter, which is the whole point of the cache.
    app.refresh();
    assert_eq!(
        app.merged_rows()[heading_idx].output,
        highlighted_output,
        "refresh's own context step should restore the cached highlighted output"
    );
    assert_eq!(
        app.segments_state.context_cache.len(),
        cache_len_after_first,
        "re-selecting the same row must not grow the cache"
    );

    let _ = std::fs::remove_dir_all(&dir);
    let _ = std::fs::remove_file(&db_path);
}

/// When the matched segment's OWN header is far from the top of a
/// long file, the preview must center the 50-line window on that
/// header's `start_line` — not just show the first 50 lines from
/// the top of the file (which wouldn't even contain the segment
/// that matched). Note a segment's `start_line` is its header's
/// line, not the specific line the query text happened to appear
/// on within the segment's body — segments are returned as whole
/// header-bounded sections, not individual paragraphs, so
/// "centering on the match" now means centering on the segment
/// (see `crate::tui::mode::segments`'s module doc comment).
///
/// 40 short "# Filler N" sections (4 lines each = 160 lines)
/// precede a "# Target" section containing `[[kramfors]]` near
/// its own start (around line 162) — well beyond the 50-line
/// window if it were (wrongly) anchored at the top of the file.
#[test]
fn ensure_selected_context_centers_window_on_segment_start_for_long_file() {
    use std::fs;
    use std::sync::atomic::{AtomicU64, Ordering};
    static COUNTER: AtomicU64 = AtomicU64::new(0);
    let n = COUNTER.fetch_add(1, Ordering::SeqCst);
    let dir = std::env::temp_dir().join(format!(
        "smarthistory-segments-longfile-{}-{}",
        std::process::id(),
        n
    ));
    let _ = fs::remove_dir_all(&dir);
    fs::create_dir_all(&dir).expect("create dir");
    let mut body = String::from("---\ntitle: long\n---\n\n");
    for i in 0..40 {
        body.push_str(&format!("# Filler {i}\n\ncontent {i}\n\n"));
    }
    body.push_str("# Target\n\na reference to [[kramfors]] appears here\n\nmore content\n");
    fs::write(dir.join("long.md"), &body).expect("write long.md");
    let db_path = dir.join("notes.sqlite");
    let conn = rusqlite::Connection::open(&db_path).expect("open db");
    note_search::init_database_schema(&conn)
        .map_err(|e| format!("schema: {e}"))
        .expect("init schema");
    let data = note_search::markdown_parser::process_markdown_file(&dir.join("long.md"), &dir)
        .expect("process file");
    note_search::write_markdown_data_to_sqlite_with_conn(&data, &conn)
        .map_err(|e| format!("write: {e}"))
        .expect("write db");
    drop(conn);

    let mut app = global_test_app(&[("a", 1)]);
    app.notes_dir = Some(dir.clone());
    app.notes_database = Some(db_path.clone());
    // A plain bare-word query (not `[[link]]` syntax) matches
    // against the segment's own `text` column only — unlike tags/
    // links, plain text matching was NOT changed to union in the
    // whole document's aggregate content, so this still correctly
    // isolates just the one segment whose OWN text contains
    // "kramfors" (see the doc comment on
    // `fetch_segments_frontmatter_link_cascades_to_every_segment`
    // for why a `[[link]]` query can no longer be used to isolate
    // a single segment in a multi-segment file).
    app.query = ":kramfors".to_string();
    app.refresh();
    drive_segments_search(&mut app);
    assert_eq!(
        app.merged_rows().len(),
        1,
        "expected exactly the '# Target' segment referencing kramfors, got: {:?}",
        app.merged_rows()
            .iter()
            .map(|r| &r.command)
            .collect::<Vec<_>>()
    );
    app.list_state.select(Some(0));
    crate::tui::mode::segments::ensure_selected_context(&mut app);
    let ansi_re = regex::Regex::new(r"\x1b\[[0-9;]*m").unwrap();
    let output = ansi_re
        .replace_all(&app.merged_rows()[0].output, "")
        .to_string();
    assert!(
        output.contains("kramfors"),
        "expected the matched segment's own header/text to be visible in the windowed preview, got: {:?}",
        output
    );
    assert!(
        !output.contains("Filler 0\n"),
        "window should be centered on the matched segment's start line, not on the unrelated sections at the top of the file; got: {:?}",
        output
    );
    let _ = fs::remove_dir_all(&dir);
    let _ = fs::remove_file(&db_path);
}

/// Without `notes.database` configured, `fetch` returns an empty
/// list with a status message — same UX as todo/notes mode.
#[test]
fn fetch_segments_requires_notes_database() {
    let mut app = global_test_app(&[("a", 1)]);
    app.notes_database = None;
    app.query = ":anything".to_string();
    app.refresh();
    drive_segments_search(&mut app);
    assert!(app.merged_rows().is_empty());
    let status = app
        .status_message
        .as_ref()
        .map(|(s, _)| s.as_str())
        .unwrap_or("");
    assert!(status.contains("notes.database"), "got: {:?}", status);
}

/// Selecting an segment row stages `$EDITOR +<start_line>
/// <absolute-path>` — the same "open the file at the matching
/// line" convention Tags/Ag/Codegraph use, keyed off
/// `row.directory` (absolute path) and `row.session_id` (line
/// number), NOT `row.id` (which is only a synthetic,
/// not-necessarily-unique-across-files marker).
#[test]
fn select_for_run_in_segments_mode_stages_editor_at_line() {
    let mut app = global_test_app(&[]);
    app.query = ":".to_string();
    app.refresh();
    app.merged_rows.push(crate::tui::state::HistoryRow {
        id: -6,
        command: "older todo 1".to_string(),
        directory: "/home/user/notes/older.md".to_string(),
        session_id: "6".to_string(),
        exit_code: 0,
        timestamp: 0,
        comment: "older.md".to_string(),
        output: String::new(),
        mode: "segment".to_string(),
        source: String::new(),
        ..Default::default()
    });
    app.list_state.select(Some(0));

    app.select_for_run();

    let staged = app.selection.as_deref().expect("staged command");
    assert!(
        staged.contains("+6"),
        "expected the line-number flag in the staged command; got: {:?}",
        staged
    );
    assert!(
        staged.contains("/home/user/notes/older.md"),
        "got: {:?}",
        staged
    );
    assert_eq!(app.pick_mode, Some(PickMode::Run));
}

// --- Directories mode (`#` prefix) ----

/// Helper that builds a fresh
/// in-memory `App` with a
/// history table containing
/// rows for several
/// directories. The
/// `global_test_app` helper
/// hardcodes every row's
/// `directory` to `/tmp`, so
/// we need a bespoke
/// constructor for
/// directories-mode tests.
/// The passed-in `(cmd,
/// directory, offset_secs)`
/// tuples are inserted in
/// the given order; the
/// resulting `timestamp` is
/// `now - offset_secs` so we
/// can drive the
/// recency-ordering
/// assertions deterministically.
fn directories_test_app(rows: &[(&str, &str, i64)]) -> App {
    use rusqlite::Connection;
    let conn = Connection::open_in_memory().expect("open in-memory db");
    conn.execute_batch(
        "CREATE TABLE history (
                    id INTEGER PRIMARY KEY,
                    command TEXT NOT NULL,
                    directory TEXT NOT NULL,
                    session_id TEXT NOT NULL,
                    exit_code INTEGER,
                    timestamp INTEGER DEFAULT \
                     (strftime('%s', 'now')),
                    mode TEXT NOT NULL DEFAULT 'command'
                );",
    )
    .expect("schema");
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    for (i, (cmd, dir, offset)) in rows.iter().enumerate() {
        conn.execute(
            "INSERT INTO history (id, command, directory, session_id, exit_code, timestamp) \
                     VALUES (?1, ?2, ?3, 'sess', 0, ?4)",
            rusqlite::params![i as i64 + 1, *cmd, *dir, now - *offset,],
        )
        .expect("insert");
    }
    // Build the App and
    // immediately clear
    // the `session_subdirs`
    // field. `App::new`
    // calls
    // `build_session_subdirs`
    // which reads the
    // user's real
    // `~/.config/smarthistory/config`.
    // Tests that don't
    // care about
    // sessiondirs would
    // otherwise be
    // polluted by
    // whatever the user
    // happens to have
    // configured (a real
    // "I added
    // `sessiondirs=...`
    // to my config and
    // now my tests fail"
    // bug). Tests that
    // DO need pinned
    // directories should
    // call
    // `directories_test_app_with_sessions`
    // below.
    let app = App::new(
        conn,
        Mode::Global,
        String::new(),
        false,
        ExitFilter::All,
        SortOrder::default(),
        false,
        SelectedTheme::None,
        crate::tui::theme::ColorScheme::Dark,
        KeyBindings::defaults(),
        None,
        None,
        None, // paperless_config
        crate::QueryPrefixes::default(),
        None,
        None,
        String::from("+$LINE"),
        // No JIRA fragments in the default
        // test app. Tests that exercise the
        // fragment path push entries directly
        // into `app.jira_fragments` (it's a
        // plain HashMap field, not gated by
        // a setter — the test is the only
        // consumer and doesn't need a
        // formal setter).
        std::collections::HashMap::new(),
        Vec::new(),
        std::collections::HashMap::new(),
        test_multiplexer(),
        crate::tui::state::PaneVisibility::default(),
        crate::tui::state::PaneHeight::default(),
        // Hermetic by default: no real `~/.config/smarthistory/config`
        // `homemap=` entries and no real `sessiondirs=` filesystem
        // walk. Tests that need specific `home_list` content set
        // `app.home_list` directly after construction instead of
        // mutating `$HOME` and depending on this being read from
        // a real config file.
        Vec::new(),
        Vec::new(),
    );
    // `session_subdirs` and `tmux_windows` both start empty —
    // `App::new` no longer reads the real `~/.config/smarthistory/config`
    // or walks `sessiondirs=` internally (see the `Vec::new()`s
    // passed above), and nothing populates `tmux_windows` at
    // construction time either (that's `fetch_tmux_windows`,
    // called lazily by `refresh()` in directories mode — this
    // helper never calls `refresh()`). Tests that need a specific
    // `session_subdirs` or `tmux_windows` set should call
    // `directories_test_app_with_sessions` (or set the fields
    // directly).
    app
}

/// A variant of
/// `directories_test_app`
/// that ALSO
/// pre-populates the
/// `session_subdirs`
/// field with the given
/// list. Use this when
/// a test needs the
/// pinned-directories
/// behaviour; use the
/// plain
/// `directories_test_app`
/// (which clears
/// `session_subdirs` by
/// `session_subdirs`
/// field with the given
/// list. Use this when
/// a test needs the
/// pinned-directories
/// behaviour; use the
/// plain
/// `directories_test_app`
/// (which clears
/// `session_subdirs` by
/// default) when the
/// test should NOT see
/// any sessiondirs.
///
/// (The default-empty
/// behaviour is what
/// keeps tests
/// isolated from the
// developer's real
// `~/.config/smarthistory/config`
// — see
// `build_session_subdirs`
// for the
// cross-contamination
// story.)
fn directories_test_app_with_sessions(
    rows: &[(&str, &str, i64)],
    sessions: Vec<std::path::PathBuf>,
) -> App {
    let mut app = directories_test_app(rows);
    app.session_subdirs = sessions;
    app
}

/// `fetch_directories`
/// returns one row per
/// unique directory, sorted
/// by each directory's
/// most-recent history
/// timestamp DESC. The
/// directory (in shell-
/// friendly `~/x` form)
/// is the visible primary
/// text of the row, and
/// the last command run
/// in that directory is
/// kept in `row.comment`
/// (the secondary slot)
/// so the user still has
/// a hint of *what* they
/// were doing there.
#[test]
fn fetch_directories_lists_unique_dirs_sorted_by_recency() {
    // Three directories,
    // several timestamps. The
    // recency order (most-recent
    // timestamp DESC) should
    // be `/home/c` first (just
    // ran there), `/home/a`
    // second (yesterday), and
    // `/home/b` last (a year
    // ago). The `comment`
    // for each directory is
    // the command that
    // produced its
    // max-timestamp row.
    let mut app = directories_test_app(&[
        ("ls", "/home/a", 86_400),         // 1 day ago
        ("make", "/home/b", 365 * 86_400), // 1 year ago
        ("echo hi", "/home/c", 30),        // 30s ago
        ("git status", "/home/a", 3_600),  // 1h ago (newer than `ls`)
        ("touch x", "/home/a", 86_400),    // 1d (older than `ls`)
    ]);
    app.query = "#".to_string();
    app.refresh();
    // Three directories
    // expected (one row
    // each). The visible
    // primary text is the
    // directory (now in
    // `row.command`), so
    // that's what we read
    // here. The new
    // directory-source
    // feature surfaces
    // tmux panes as
    // additional rows,
    // so we filter to
    // `/home/...` (the
    // test's directory
    // namespace) to
    // assert cleanly.
    let home_rows: Vec<&HistoryRow> = app
        .merged_rows()
        .iter()
        .filter(|r| r.directory.starts_with("/home/"))
        .collect();
    let visible: Vec<&str> = home_rows.iter().map(|r| r.command.as_str()).collect();
    assert_eq!(visible.len(), 3);
    // Newest directory
    // first.
    assert_eq!(visible[0], "/home/c");
    // Second.
    assert_eq!(visible[1], "/home/a");
    // Third.
    assert_eq!(visible[2], "/home/b");
    // The last command run
    // in each directory
    // lives in `row.comment`
    // (the secondary slot).
    let last_cmds: Vec<&str> = home_rows.iter().map(|r| r.comment.as_str()).collect();
    assert_eq!(last_cmds[0], "echo hi");
    assert_eq!(last_cmds[1], "git status");
    assert_eq!(last_cmds[2], "make");
    // Each row's `directory`
    // is the canonical path.
    let dirs: Vec<&str> = home_rows.iter().map(|r| r.directory.as_str()).collect();
    assert_eq!(dirs[0], "/home/c");
    assert_eq!(dirs[1], "/home/a");
    assert_eq!(dirs[2], "/home/b");
}

/// Substring filter: `#home`
/// restricts the listing to
/// rows whose `directory`
/// contains `home`. The
/// filter is space-split AND
/// (so `#home a` requires both
/// `home` AND `a` somewhere in
/// the path). The visible
/// primary text on each row
/// is now the directory (per
/// the layout swap), so the
/// assertions read
/// `row.command` (the
/// directory) and the
/// comments confirm the
/// last-command metadata.
#[test]
fn fetch_directories_applies_substring_filter() {
    let mut app = directories_test_app(&[
        ("ls", "/home/a", 86_400),
        ("ls", "/var/log", 3_600),
        ("ls", "/home/b", 60),
    ]);
    app.query = "#home".to_string();
    app.refresh();
    let visible: Vec<&str> = app
        .merged_rows()
        .iter()
        .map(|r| r.command.as_str())
        .collect();
    assert_eq!(visible.len(), 2);
    // `/home/b` is the latest
    // of the matching
    // directories (60s old),
    // so it sorts first.
    assert_eq!(visible[0], "/home/b");
    assert_eq!(visible[1], "/home/a");
    // The secondary slot
    // carries the last
    // command run in each
    // directory.
    let cmds: Vec<&str> = app
        .merged_rows()
        .iter()
        .map(|r| r.comment.as_str())
        .collect();
    assert_eq!(cmds[0], "ls");
    assert_eq!(cmds[1], "ls");
    // No match for `/var/log`
    // because the filter
    // requires `home`.
    app.query = "#var".to_string();
    app.refresh();
    assert_eq!(app.merged_rows().len(), 1);
    app.query = "#no-such-dir".to_string();
    app.refresh();
    assert_eq!(app.merged_rows().len(), 0);
}

/// Regression test for the
/// directory-row layout
/// swap: the visible
/// primary text is the
/// directory in shell-
/// shortened form
/// (`~/x` when under
/// `$HOME`) and the
/// secondary `# ...`
/// slot is the last
/// command run there.
/// Without the swap the
/// user would see the
/// command first and the
/// directory as a
/// secondary hint — the
/// inverse of what the
/// user wants in `#`-mode
/// (where they're
/// searching for paths,
/// not commands).
#[test]
fn fetch_directories_layout_swap() {
    // The `~`-shortening depends on `app.home_list` (built from
    // `$HOME` + `homemap=` config entries in production — see
    // `build_home_list`). Rather than mutating the real `$HOME`
    // env var (which used to be the only way to influence this,
    // and risked racing other env-mutating tests, or worse,
    // resolving to a REAL path on the machine running the tests),
    // set `app.home_list` directly: a synthetic, test-only value
    // fully under this test's control, with no dependency on the
    // environment or the real `~/.config/smarthistory/config`.
    let mut app =
        directories_test_app(&[("ls -la /tmp/foo bar", "/home/testuser/work/project", 60)]);
    app.home_list = vec!["/home/testuser".to_string()];
    app.query = "#".to_string();
    app.refresh();
    // Find the SQL-history
    // row specifically;
    // sessiondirs / tmux
    // rows may also be
    // present (cleared in
    // the test helper, but
    // `refresh()` re-runs `fetch_tmux_windows` for `#`-mode
    // queries too, but `directories_test_app` clears the tmux
    // fixture so no real panes bleed in. We assert on the row
    // whose `directory` matches what we inserted, not on
    // `merged_rows()[0]`.
    let row = app
        .merged_rows()
        .iter()
        .find(|r| r.directory == "/home/testuser/work/project")
        .expect("the SQL-history row for /home/testuser/work/project must be in merged_rows");
    // The primary text (which the user sees first in the list,
    // and which the query highlights against) is the directory in
    // `~/x` form. This is the load-bearing assertion: it locks in
    // the swap.
    assert_eq!(row.command, "~/work/project");
    // The secondary slot (the `# ...` comment in the rendered
    // line) is the last command run in that directory. The
    // command here is short (under the 60-char truncation
    // threshold) so it appears verbatim.
    assert_eq!(row.comment, "ls -la /tmp/foo bar");
    // The full directory (un-shortened) is still in `directory`
    // for the tmux-pane lookup and Details pane.
    assert_eq!(row.directory, "/home/testuser/work/project");
}

/// Long commands are
/// truncated to 57
/// characters plus an
/// ellipsis when stored
/// in the secondary slot
/// (the comment field).
/// The truncation is
/// char-aware (uses
/// `chars().take(57)`)
/// so multi-byte UTF-8
/// doesn't get cut in
/// the middle of a
/// code point.
#[test]
fn fetch_directories_truncates_long_command() {
    // 100-char command.
    let long_cmd = "a".repeat(100);
    let mut app = directories_test_app(&[(&long_cmd, "/Users/har/work", 60)]);
    app.query = "#".to_string();
    app.refresh();
    // Find the row by
    // directory
    // (the test helper
    // clears `tmux_windows`
    // but `refresh()`
    // re-runs the tmux
    // fetch, so the
    // user's real tmux
    // panes may also be
    // present). The
    // SQL row is the one
    // with the matching
    // directory.
    let row = app
        .merged_rows()
        .iter()
        .find(|r| r.directory == "/Users/har/work")
        .expect("the SQL-history row for /Users/har/work must be in merged_rows");
    // Truncated to 57
    // `a`s + `…` = 58
    // chars.
    assert_eq!(row.comment.chars().count(), 58);
    assert!(row.comment.ends_with('…'));
    assert!(row.comment.starts_with('a'));
}

/// Selecting a directory
/// row in the TUI stages
/// `cd <path>` as the next
/// shell command. Paths
/// with shell-metacharacters
/// are quoted so the parent
/// shell tokenises them
/// correctly (defensive —
/// covers spaces, `$`, etc.).
/// The new contract: with an
/// empty `tmux_windows`
/// snapshot (no active
/// tmux session for this
/// directory), selecting
/// the directory row
/// creates a new tmux
/// session and switches to
/// it. (See
/// `select_t_marked_directory_stages_select_and_switch`
/// for the "T"-marked
/// branch.)
#[test]
fn selecting_unmarked_directory_creates_new_tmux_session() {
    let mut app = directories_test_app(&[("ls", "/home/user/project", 60)]);
    app.query = "#".to_string();
    app.refresh();
    // Select the
    // SQL-history row
    // explicitly.
    let sql_row_idx = app
        .merged_rows()
        .iter()
        .position(|r| r.directory == "/home/user/project")
        .expect("the SQL-history row for /home/user/project must be in merged_rows");
    app.list_state.select(Some(sql_row_idx));
    app.select_for_run();
    let staged = app.selection.as_deref().expect("selection must be set");
    assert!(
        staged.contains("tmux new-session -d -s project -c /home/user/project")
            && staged.contains("tmux switch-client -t project"),
        "staged command must create detached session with the directory basename, got: {staged:?}"
    );
    assert_eq!(app.pick_mode, Some(crate::tui::state::PickMode::Run),);
}

/// The `#` prefix is
/// configurable via
/// `prefix.directories=...`,
/// parallel to every other
/// query-mode prefix. We
/// exercise the parse /
/// assignment path
/// (`assign_prefix`) directly
/// because there's no
/// `Config::parse` in scope
/// here.
#[test]
fn directories_prefix_is_configurable() {
    let mut prefixes = crate::QueryPrefixes::default();
    assert_eq!(prefixes.directories, '#');
    // `assign_prefix` lives
    // in `main.rs`; mirror
    // its one-liner here so
    // we can confirm the
    // field is reachable via
    // the public API.
    prefixes.directories = '>';
    assert_eq!(prefixes.directories, '>');
    // A non-default prefix
    // is recognised by the
    // predicate.
    let mut app = directories_test_app(&[("ls", "/home/a", 60)]);
    app.query_prefixes.directories = '>';
    app.query = ">home".to_string();
    assert!(app.is_directories_query());
    assert_eq!(app.directories_pattern(), "home");
}

// --- Zoxide mode (`~` prefix) ----
//
// `crate::tui::mode::zoxide::build_rows` is the pure part of
// `fetch` — filtering, existence-checking, and row-building from an
// already-fetched path list — split out specifically so these tests
// never spawn the real `zoxide` binary or touch the user's real
// zoxide database (see `build_rows`'s doc comment). Real temporary
// directories are used (not just string literals) because
// `build_rows` skips any path that doesn't exist on disk, mirroring
// how a stale zoxide database entry (a directory since deleted)
// shouldn't produce a row the user can't actually jump to.

/// Create a real, empty temporary directory for a zoxide-mode test
/// and return its canonicalized absolute path as a `String` (matching
/// the form `zoxide query -l` would report). Canonicalizing avoids
/// `/tmp` vs `/private/tmp`-style symlink mismatches between the
/// path we create and the path `shorten_home_path`/`is_dir` see.
fn zoxide_test_dir(name: &str) -> String {
    use std::sync::atomic::{AtomicU64, Ordering};
    static COUNTER: AtomicU64 = AtomicU64::new(0);
    let n = COUNTER.fetch_add(1, Ordering::SeqCst);
    let dir = std::env::temp_dir().join(format!(
        "smarthistory-zoxide-{}-{}-{}",
        std::process::id(),
        n,
        name
    ));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).expect("create zoxide test dir");
    dir.canonicalize()
        .expect("canonicalize zoxide test dir")
        .to_string_lossy()
        .into_owned()
}

#[test]
fn zoxide_matches_and_pattern() {
    let mut app = directories_test_app(&[]);
    assert!(!app.is_zoxide_query());
    assert_eq!(app.zoxide_pattern(), "");
    app.query = "~proj".to_string();
    assert!(app.is_zoxide_query());
    assert_eq!(app.zoxide_pattern(), "proj");
}

/// `build_rows` preserves zoxide's own highest-score-first order via
/// a descending synthetic `timestamp` — so the list's default
/// (timestamp-DESC) sort matches zoxide's ranking without smarthistory
/// needing to know the real score.
#[test]
fn zoxide_build_rows_preserves_zoxide_rank_order() {
    let a = zoxide_test_dir("a");
    let b = zoxide_test_dir("b");
    let c = zoxide_test_dir("c");
    let rows = crate::tui::mode::zoxide::build_rows(
        vec![a.clone(), b.clone(), c.clone()],
        &[],
        &[],
    );
    assert_eq!(rows.len(), 3);
    assert_eq!(rows[0].directory, a);
    assert_eq!(rows[1].directory, b);
    assert_eq!(rows[2].directory, c);
    assert!(
        rows[0].timestamp > rows[1].timestamp && rows[1].timestamp > rows[2].timestamp,
        "synthetic timestamps must descend in zoxide's own rank order: {:?}",
        rows.iter().map(|r| r.timestamp).collect::<Vec<_>>()
    );
}

/// A zoxide database entry whose directory has since been deleted is
/// skipped — there's nothing to jump to, and staging a `tmux
/// new-session -c <dir>` for a non-existent path would just fail.
#[test]
fn zoxide_build_rows_skips_nonexistent_directories() {
    let real = zoxide_test_dir("real");
    let deleted = format!("{}-does-not-exist", real);
    let rows = crate::tui::mode::zoxide::build_rows(
        vec![deleted, real.clone()],
        &[],
        &[],
    );
    assert_eq!(rows.len(), 1);
    assert_eq!(rows[0].directory, real);
}

/// The typed query filters by case-insensitive substring, AND-matched
/// across whitespace-separated tokens — same contract as every other
/// prefix mode's filter.
#[test]
fn zoxide_build_rows_filters_by_tokens_case_insensitively() {
    let work = zoxide_test_dir("Work-Project");
    let other = zoxide_test_dir("personal-notes");
    let rows = crate::tui::mode::zoxide::build_rows(
        vec![work.clone(), other],
        &["work"],
        &[],
    );
    assert_eq!(rows.len(), 1);
    assert_eq!(rows[0].directory, work);
}

/// Rows are tagged `mode == "directory"`, the same tag `#`
/// Directories mode's rows carry — this is what makes
/// `App::stage_directory_selection` and the `T`-marker render logic
/// work unmodified for a zoxide row.
#[test]
fn zoxide_build_rows_tags_mode_directory() {
    let dir = zoxide_test_dir("tagged");
    let rows = crate::tui::mode::zoxide::build_rows(vec![dir], &[], &[]);
    assert_eq!(rows.len(), 1);
    assert_eq!(rows[0].mode, "directory");
    assert_eq!(rows[0].source, "zoxide");
}

/// `ModeKind::Zoxide` is dedup-eligible (same treatment as
/// `Directories`), so `build_merged_rows` dedupes by `command` and
/// skips the labeled-row interleave, rather than treating zoxide rows
/// like ordinary history rows.
#[test]
fn zoxide_mode_is_dedup_eligible() {
    assert!(crate::tui::mode::ModeKind::Zoxide.dedup_eligible());
}

/// Selecting a zoxide row must go through the same staging as a
/// Directories-mode row (`stage_directory_selection`'s
/// create-a-new-session path), not fall through to the generic
/// "history mode" default (which would try to run the directory path
/// itself as a shell command).
#[test]
fn zoxide_select_for_run_stages_new_session_not_plain_command() {
    let mut app = directories_test_app(&[]);
    let dir = zoxide_test_dir("select");
    app.merged_rows = vec![crate::tui::state::HistoryRow {
        id: -1,
        command: dir.clone(),
        directory: dir.clone(),
        session_id: String::new(),
        exit_code: 0,
        timestamp: 1,
        comment: String::new(),
        output: String::new(),
        mode: "directory".to_string(),
        source: "zoxide".to_string(),
        ..Default::default()
    }];
    app.query = "~select".to_string();
    app.list_state.select(Some(0));
    app.select_for_run();
    // The directory isn't a configured `session.<id>` entry, so
    // selecting it opens the "save this directory?" prompt instead
    // of staging immediately — see `zoxide_save_prompt_opens_...`
    // tests below for that behavior in isolation. Decline the save
    // here to drive through to the actual staging this test cares
    // about.
    assert!(
        app.zoxide_save_prompt.is_some(),
        "an unsaved zoxide directory must open the save prompt first"
    );
    app.answer_zoxide_save_prompt(false);
    let staged = app.selection.as_deref().unwrap_or("");
    assert!(
        staged.contains("new-session") || staged.contains("workspace create"),
        "expected a new-session/workspace-create staging command, got: {staged:?}"
    );
}

/// Build a zoxide-mode `App` with a single merged row for `dir`,
/// selected and ready for `select_for_run`. Shared setup for the
/// `zoxide_save_prompt` tests below.
fn zoxide_test_app_selecting(dir: &str) -> App {
    let mut app = directories_test_app(&[]);
    app.merged_rows = vec![crate::tui::state::HistoryRow {
        id: -1,
        command: dir.to_string(),
        directory: dir.to_string(),
        session_id: String::new(),
        exit_code: 0,
        timestamp: 1,
        comment: String::new(),
        output: String::new(),
        mode: "directory".to_string(),
        source: "zoxide".to_string(),
        ..Default::default()
    }];
    app.query = "~select".to_string();
    app.list_state.select(Some(0));
    app
}

/// Selecting a zoxide directory not already in `app.sessions` opens
/// the save prompt, pre-filled with the directory's basename as the
/// label, instead of staging immediately.
#[test]
fn zoxide_save_prompt_opens_for_unsaved_directory() {
    let dir = zoxide_test_dir("prompt-basename");
    let mut app = zoxide_test_app_selecting(&dir);
    app.select_for_run();
    let prompt = app
        .zoxide_save_prompt
        .as_ref()
        .expect("unsaved zoxide directory must open the save prompt");
    assert_eq!(prompt.directory, dir);
    assert_eq!(
        prompt.label,
        std::path::Path::new(&dir)
            .file_name()
            .and_then(|n| n.to_str())
            .unwrap()
    );
    assert!(
        app.selection.is_none(),
        "the prompt must defer staging, not stage immediately"
    );
}

/// A zoxide directory that's already a configured `session.<id>`
/// entry (matched via `canonicalize_directory`, so trailing slashes
/// etc. don't cause a false "unsaved" prompt) skips the prompt
/// entirely and stages right away, same as before this feature
/// existed.
#[test]
fn zoxide_save_prompt_skipped_for_already_saved_directory() {
    let dir = zoxide_test_dir("already-saved");
    let mut app = zoxide_test_app_selecting(&dir);
    app.sessions = vec![crate::tui::state::HistoryRow {
        id: -10_003,
        command: String::from("existing"),
        directory: dir.clone(),
        session_id: String::new(),
        exit_code: 0,
        timestamp: 1,
        comment: String::new(),
        output: String::new(),
        mode: "directory".to_string(),
        source: String::new(),
        ..Default::default()
    }];
    app.select_for_run();
    assert!(
        app.zoxide_save_prompt.is_none(),
        "an already-saved directory must not open the save prompt"
    );
    let staged = app.selection.as_deref().unwrap_or("");
    assert!(
        staged.contains("new-session") || staged.contains("workspace create"),
        "expected staging to happen directly, got: {staged:?}"
    );
}

/// Answering "yes" (`answer_zoxide_save_prompt(true)`) writes a new
/// `session.<id>` entry to the real `sessions` file path resolution
/// (redirected to a scratch `$HOME` for the duration of the test —
/// see `ENV_LOCK`) with a name and `.dir` line only, deliberately no
/// `.exec` line ("without any specific execution flags"), and still
/// completes the original directory staging afterward.
#[test]
fn zoxide_save_prompt_yes_writes_session_entry_without_exec() {
    let _env_guard = lock_or_recover(&ENV_LOCK);
    let tmp_home = std::env::temp_dir().join(format!(
        "smarthistory_zoxide_save_prompt_yes_{}",
        std::process::id()
    ));
    let _ = std::fs::remove_dir_all(&tmp_home);
    std::fs::create_dir_all(tmp_home.join(".config/smarthistory")).expect("create cfg dir");
    let prev_home = std::env::var("HOME").ok();
    unsafe {
        std::env::set_var("HOME", &tmp_home);
    }

    let dir = zoxide_test_dir("save-me");
    let mut app = zoxide_test_app_selecting(&dir);
    app.select_for_run();
    assert!(app.zoxide_save_prompt.is_some());
    app.answer_zoxide_save_prompt(true);

    let sessions_path = tmp_home.join(".config/smarthistory/sessions");
    let contents = std::fs::read_to_string(&sessions_path).unwrap_or_else(|e| {
        panic!("expected sessions file at {sessions_path:?}: {e}")
    });

    unsafe {
        match prev_home {
            Some(v) => std::env::set_var("HOME", v),
            None => std::env::remove_var("HOME"),
        }
    }
    let _ = std::fs::remove_dir_all(&tmp_home);

    let expected_label = std::path::Path::new(&dir)
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap();
    assert!(
        contents.contains(&format!("= {expected_label:?}")),
        "expected a session name line for {expected_label:?} in:\n{contents}"
    );
    assert!(
        contents.contains(&format!(".dir = {dir:?}")),
        "expected a `.dir` line for {dir:?} in:\n{contents}"
    );
    assert!(
        !contents.contains(".exec"),
        "must not write an `.exec` line — \"without any specific execution flags\":\n{contents}"
    );
    let staged = app.selection.as_deref().unwrap_or("");
    assert!(
        staged.contains("new-session") || staged.contains("workspace create"),
        "the original directory jump must still complete after saving, got: {staged:?}"
    );
}

/// Answering "no" must NOT write anything to the sessions file, but
/// must still complete the original directory staging — declining to
/// save never blocks the jump.
#[test]
fn zoxide_save_prompt_no_skips_write_but_still_stages() {
    let _env_guard = lock_or_recover(&ENV_LOCK);
    let tmp_home = std::env::temp_dir().join(format!(
        "smarthistory_zoxide_save_prompt_no_{}",
        std::process::id()
    ));
    let _ = std::fs::remove_dir_all(&tmp_home);
    std::fs::create_dir_all(tmp_home.join(".config/smarthistory")).expect("create cfg dir");
    let prev_home = std::env::var("HOME").ok();
    unsafe {
        std::env::set_var("HOME", &tmp_home);
    }

    let dir = zoxide_test_dir("dont-save-me");
    let mut app = zoxide_test_app_selecting(&dir);
    app.select_for_run();
    assert!(app.zoxide_save_prompt.is_some());
    app.answer_zoxide_save_prompt(false);

    let sessions_path = tmp_home.join(".config/smarthistory/sessions");
    let write_happened = sessions_path.exists();

    unsafe {
        match prev_home {
            Some(v) => std::env::set_var("HOME", v),
            None => std::env::remove_var("HOME"),
        }
    }
    let _ = std::fs::remove_dir_all(&tmp_home);

    assert!(
        !write_happened,
        "declining the save must not create a sessions file"
    );
    let staged = app.selection.as_deref().unwrap_or("");
    assert!(
        staged.contains("new-session") || staged.contains("workspace create"),
        "declining to save must still stage the directory jump, got: {staged:?}"
    );
}

/// `handle_zoxide_save_prompt_key` key dispatch: `Enter`/`y`/`Y` save
/// and stage, `n`/`N` skip the save but still stage, and `Ctrl-C`
/// aborts the whole TUI without staging anything (matching every
/// other confirmation overlay's panic-button semantics).
#[test]
fn zoxide_save_prompt_key_dispatch() {
    use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};

    // `n` skips the save, still stages.
    let dir = zoxide_test_dir("key-n");
    let mut app = zoxide_test_app_selecting(&dir);
    app.select_for_run();
    assert!(app.zoxide_save_prompt.is_some());
    handle_key(&mut app, KeyEvent::new(KeyCode::Char('n'), KeyModifiers::NONE));
    assert!(app.zoxide_save_prompt.is_none());
    assert!(app.selection.is_some());

    // With the DEFAULT bindings, `Action::Cancel` is bound to both
    // `Esc` and `C-c` (see `KeyBindings::defaults`), so Ctrl-C hits
    // the `_ if is_cancel_key` arm before the dedicated
    // `KeyCode::Char('c') + CONTROL` arm ever runs — same
    // shadowed-fallback shape as `handle_confirm_delete_key`. That
    // dedicated arm only becomes reachable if the user remaps
    // `key.cancel` away from `C-c`; under defaults, Ctrl-C behaves
    // exactly like `n`/Cancel here — decline the save, still stage.
    let dir = zoxide_test_dir("key-ctrlc");
    let mut app = zoxide_test_app_selecting(&dir);
    app.select_for_run();
    assert!(app.zoxide_save_prompt.is_some());
    handle_key(&mut app, KeyEvent::new(KeyCode::Char('c'), KeyModifiers::CONTROL));
    assert!(app.zoxide_save_prompt.is_none());
    assert!(
        app.selection.is_some(),
        "Ctrl-C under default bindings must still stage the directory jump"
    );

    // A stray, unbound key does nothing — the prompt stays open.
    let dir = zoxide_test_dir("key-stray");
    let mut app = zoxide_test_app_selecting(&dir);
    app.select_for_run();
    assert!(app.zoxide_save_prompt.is_some());
    handle_key(&mut app, KeyEvent::new(KeyCode::Char('z'), KeyModifiers::NONE));
    assert!(
        app.zoxide_save_prompt.is_some(),
        "a stray key must not answer the prompt"
    );
}

/// `draw_zoxide_save_prompt` actually renders the directory's
/// basename and the "save?" hint text onscreen when
/// `app.zoxide_save_prompt` is set — a `TestBackend` check, not just
/// a check of the underlying row/state data.
#[test]
fn zoxide_save_prompt_renders_label_and_hint() {
    let mut app = directories_test_app(&[]);
    app.zoxide_save_prompt = Some(crate::tui::state::ZoxideSavePrompt {
        label: "my-project".to_string(),
        directory: "/tmp/my-project".to_string(),
    });

    let backend = ratatui::backend::TestBackend::new(100, 30);
    let mut terminal = ratatui::Terminal::new(backend).expect("terminal");
    terminal
        .draw(|f| crate::tui::render::ui(f, &mut app))
        .expect("draw");
    let text = terminal
        .backend()
        .buffer()
        .content
        .iter()
        .map(|c| c.symbol())
        .collect::<String>();
    assert!(
        text.contains("my-project"),
        "expected the directory label onscreen, got: {text:?}"
    );
    assert!(
        text.contains("Save"),
        "expected the save prompt title/text onscreen, got: {text:?}"
    );
}

/// `draw_output_preview` used to hard-cap plain history rows (and any
/// mode not on a specific allow-list) at 4 lines regardless of how
/// tall the pane actually was. Now every mode renders as many lines
/// as it already loaded, letting the pane's own render area (and
/// scroll) determine what's visible — so a tall enough pane shows
/// well past the old 4-line ceiling, with no mode-specific carve-out
/// needed. Regression test for that fix: a plain `command`-mode row
/// with 8 lines of captured output must show line 6 onscreen (which
/// the old `take(4)` cap would have discarded before the Paragraph
/// ever saw it).
#[test]
fn output_preview_shows_more_than_four_lines_when_pane_is_tall_enough() {
    let mut app = directories_test_app(&[]);
    let output: String = (1..=8).map(|n| format!("line {n} of captured output\n")).collect();
    app.merged_rows.insert(
        0,
        crate::tui::state::HistoryRow {
            id: 1,
            command: "some-command".to_string(),
            mode: "command".to_string(),
            output,
            ..Default::default()
        },
    );
    app.list_state.select(Some(0));

    // Tall enough that `PaneHeight::default()`'s detail row (at
    // least `PaneHeight::MIN` = 8 lines) comfortably exceeds the old
    // 4-line cap once its 2 border rows are subtracted.
    let backend = ratatui::backend::TestBackend::new(120, 40);
    let mut terminal = ratatui::Terminal::new(backend).expect("terminal");
    terminal
        .draw(|f| crate::tui::render::ui(f, &mut app))
        .expect("draw");
    let text = terminal
        .backend()
        .buffer()
        .content
        .iter()
        .map(|c| c.symbol())
        .collect::<String>();
    assert!(
        text.contains("line 6 of captured output"),
        "expected line 6 onscreen (past the old 4-line cap), got: {text:?}"
    );
}

// --- processes mode (`%` prefix) ----

/// `%` mode parses the same as every other prefix mode: the query's
/// leading `%` char strips off, and everything after it is the typed
/// filter body.
#[test]
fn processes_matches_and_pattern() {
    let mut app = directories_test_app(&[]);
    assert!(!app.is_processes_query());
    assert_eq!(app.processes_pattern(), "");
    app.query = "%nginx".to_string();
    assert!(app.is_processes_query());
    assert_eq!(app.processes_pattern(), "nginx");
}

/// Every PID is unique — there's nothing meaningful to dedup by
/// command (many processes legitimately share a name), same
/// reasoning as `Panes` mode. `build_merged_rows`'s early return
/// (rather than `dedup_eligible`) is what actually implements this;
/// this test locks in the `dedup_eligible() == false` half of that
/// contract so a future refactor can't accidentally add Processes to
/// the dedup set.
#[test]
fn processes_mode_is_not_dedup_eligible() {
    assert!(!crate::tui::mode::ModeKind::Processes.dedup_eligible());
}

/// `fetch` enumerates real OS processes via `sysinfo` — the running
/// test binary's own PID is always present, giving a real, portable
/// (macOS + Linux) assertion without mocking the process table.
#[test]
fn processes_fetch_finds_own_pid() {
    let mut app = directories_test_app(&[]);
    app.query = "%".to_string();
    let rows = crate::tui::mode::processes::fetch(&mut app).expect("fetch");
    let own_pid = std::process::id() as i64;
    let own_row = rows
        .iter()
        .find(|r| r.id == own_pid)
        .unwrap_or_else(|| panic!("expected own pid {own_pid} in process list"));
    assert_eq!(own_row.mode, "process");
    assert!(
        !own_row.command.is_empty(),
        "expected a non-empty command/name for the own-pid row"
    );
}

/// The typed filter matches (case-insensitively) against command,
/// cwd, AND executable path — a filter token unrelated to every real
/// process on the test machine must exclude everything.
#[test]
fn processes_fetch_filters_by_pattern() {
    let mut app = directories_test_app(&[]);
    app.query = "%definitely-not-a-real-process-name-xyz123".to_string();
    let rows = crate::tui::mode::processes::fetch(&mut app).expect("fetch");
    assert!(
        rows.is_empty(),
        "expected no processes to match a nonsense filter, got {} rows",
        rows.len()
    );
}

/// `ensure_selected_context` populates `preview` with the selected
/// process's environment variables. The test's own process can always
/// read its own environment (no permission issue), so this doesn't
/// need to mock anything platform-specific.
///
/// Deliberately asserts against a variable already present in the
/// test process's environment at exec time (`std::env::vars()`,
/// picking any real entry) rather than one set with
/// `std::env::set_var` during the test: both macOS (`KERN_PROCARGS2`)
/// and Linux (`/proc/<pid>/environ`) read a process's environment
/// block as the kernel captured it at `execve`, not live post-start
/// `setenv` mutations — a `set_var` sentinel would not reliably show
/// up here even though it's visible to `std::env::var` within this
/// same process.
#[test]
fn processes_ensure_selected_context_populates_preview_for_own_pid() {
    let (known_key, known_value) = std::env::vars()
        .next()
        .expect("test process should have at least one env var set");

    let mut app = directories_test_app(&[]);
    let own_pid = std::process::id() as i64;
    app.rows = vec![crate::tui::state::HistoryRow {
        id: own_pid,
        command: "test-process".to_string(),
        directory: String::new(),
        session_id: own_pid.to_string(),
        exit_code: 0,
        timestamp: 0,
        comment: String::new(),
        output: String::new(),
        mode: "process".to_string(),
        ..Default::default()
    }];
    app.merged_rows = app.rows.clone();
    app.query = "%".to_string();
    app.list_state.select(Some(0));

    crate::tui::mode::processes::ensure_selected_context(&mut app);

    let preview = &app.merged_rows[0].preview;
    assert!(
        preview.contains(&format!("{known_key}={known_value}")),
        "expected {known_key:?} in the preview, got: {preview:?}"
    );
    // Written to both copies (see the panes-mode precedent this
    // mirrors) so a subsequent rebuild doesn't wipe the preview.
    assert_eq!(app.rows[0].preview, app.merged_rows[0].preview);
}

/// The graceful-degradation placeholder shown when a process's
/// environment can't be read (permission denied, or the process
/// already exited) — extracted as a pure function specifically so
/// this can be tested without needing an actual unreadable process.
#[test]
fn processes_format_environ_error_mentions_pid() {
    let msg = crate::tui::mode::processes::format_environ_error(1234);
    assert!(msg.contains("1234"));
    assert!(msg.to_lowercase().contains("permission"));
}

/// `Tab`/`BackTab` cycle the confirmation dialog's signal through the
/// fixed 4-signal set, defaulting to SIGTERM, without confirming or
/// cancelling — the one outcome `ConfirmMode`'s y/n/cancel shape has
/// no room for, which is why this dialog uses a dedicated
/// `confirm_signal` field. Confirmed by round-tripping the label text
/// rather than reaching into the enum directly, since `ProcessSignal`
/// is private to the `tui` module (same visibility `ConfirmMode` has)
/// and this test lives in `tui::tests`, a descendant module, so it
/// can see it — but going through `handle_key` + the rendered label
/// also exercises the real dispatch path, not just the enum's own
/// `next()`/`prev()`.
#[test]
fn processes_confirm_signal_cycles_and_defaults_to_term() {
    use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};

    let mut app = directories_test_app(&[]);
    app.confirm_signal = Some(crate::tui::SignalConfirm {
        pid: 999,
        name: "sleep".to_string(),
        signal: crate::tui::ProcessSignal::Term,
    });
    assert_eq!(app.confirm_signal.as_ref().unwrap().signal.label(), "SIGTERM");

    handle_key(&mut app, KeyEvent::new(KeyCode::Tab, KeyModifiers::NONE));
    assert_eq!(app.confirm_signal.as_ref().unwrap().signal.label(), "SIGKILL");

    handle_key(&mut app, KeyEvent::new(KeyCode::Tab, KeyModifiers::NONE));
    assert_eq!(app.confirm_signal.as_ref().unwrap().signal.label(), "SIGHUP");

    handle_key(&mut app, KeyEvent::new(KeyCode::Tab, KeyModifiers::NONE));
    assert_eq!(app.confirm_signal.as_ref().unwrap().signal.label(), "SIGINT");

    handle_key(&mut app, KeyEvent::new(KeyCode::Tab, KeyModifiers::NONE));
    assert_eq!(
        app.confirm_signal.as_ref().unwrap().signal.label(),
        "SIGTERM",
        "cycling forward 4 times must wrap back to SIGTERM"
    );

    handle_key(&mut app, KeyEvent::new(KeyCode::BackTab, KeyModifiers::SHIFT));
    assert_eq!(
        app.confirm_signal.as_ref().unwrap().signal.label(),
        "SIGINT",
        "Shift-Tab must cycle backward"
    );
}

/// `n` dismisses the dialog without sending anything; the process
/// list is untouched.
#[test]
fn processes_confirm_signal_n_dismisses_without_sending() {
    use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};

    let mut app = directories_test_app(&[]);
    app.confirm_signal = Some(crate::tui::SignalConfirm {
        pid: 999,
        name: "sleep".to_string(),
        signal: crate::tui::ProcessSignal::Term,
    });
    handle_key(&mut app, KeyEvent::new(KeyCode::Char('n'), KeyModifiers::NONE));
    assert!(app.confirm_signal.is_none());
}

/// Selecting a process row (`Enter`) must NOT stage/run the process
/// name as a shell command — it opens the signal-confirmation dialog
/// instead and leaves `app.selection` untouched, mirroring
/// `zoxide_save_prompt_opens_for_unsaved_directory`'s "defer, don't
/// stage" assertion shape.
#[test]
fn processes_select_for_run_opens_confirm_dialog_without_staging() {
    let mut app = directories_test_app(&[]);
    app.merged_rows = vec![crate::tui::state::HistoryRow {
        id: 4242,
        command: "sleep 300".to_string(),
        directory: "/tmp".to_string(),
        session_id: "4242".to_string(),
        exit_code: 0,
        timestamp: 0,
        comment: String::new(),
        output: String::new(),
        mode: "process".to_string(),
        ..Default::default()
    }];
    app.query = "%sleep".to_string();
    app.list_state.select(Some(0));

    app.select_for_run();

    let confirm = app
        .confirm_signal
        .as_ref()
        .expect("selecting a process row must open the signal confirmation dialog");
    assert_eq!(confirm.pid, 4242);
    assert_eq!(confirm.name, "sleep 300");
    assert_eq!(confirm.signal.label(), "SIGTERM");
    assert!(
        app.selection.is_none(),
        "the confirmation dialog must defer staging, not run the process name as a command"
    );
}

/// End-to-end proof that `App::send_signal` actually delivers a real
/// signal via `sysinfo::Process::kill_with`, not just that it
/// type-checks: spawn a real disposable child process, send it
/// SIGTERM, and confirm it actually terminates. This is the one test
/// in this file that exercises the real OS signal-delivery path
/// rather than mocking around it — every other processes-mode test
/// either reads real (but never kills) processes or drives the
/// dialog's key handling without an actual `kill(2)` call.
#[test]
fn processes_send_signal_actually_terminates_a_real_process() {
    let mut child = std::process::Command::new("sleep")
        .arg("300")
        .spawn()
        .expect("spawn disposable sleep process");
    let pid = child.id() as i64;

    let app = directories_test_app(&[]);
    let result = app.send_signal(pid, sysinfo::Signal::Term);
    assert!(result.is_ok(), "send_signal should succeed: {result:?}");

    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
    let exited = loop {
        match child.try_wait() {
            Ok(Some(_)) => break true,
            Ok(None) if std::time::Instant::now() < deadline => {
                std::thread::sleep(std::time::Duration::from_millis(50));
            }
            _ => break false,
        }
    };
    if !exited {
        let _ = child.kill();
        let _ = child.wait();
        panic!("child process did not exit within 5s of receiving SIGTERM");
    }
}

// --- ag mode row rendering (`,` prefix) ----
//
// `src/ag.rs` builds each row with the matched line's content in
// `command` and the absolute file path in `directory` (see
// `spawn_ag_search`'s doc comment / row-building loop). Rendering
// moves the file path to the front of the row, shortened via
// `util::shorten_path_dirs` (every directory component abbreviated
// to its first character, filename kept in full), followed by the
// match content — see `render_row`'s `row.mode == "ag"` branch.

/// Build a minimal ag-mode `HistoryRow` for the given absolute
/// `directory` (file path) and matched-line `content`.
fn ag_row(directory: &str, content: &str) -> HistoryRow {
    let basename = std::path::Path::new(directory)
        .file_name()
        .map(|s| s.to_string_lossy().into_owned())
        .unwrap_or_default();
    HistoryRow {
        id: -1,
        command: content.to_string(),
        directory: directory.to_string(),
        session_id: "12".to_string(),
        exit_code: 0,
        timestamp: 0,
        comment: basename,
        output: String::new(),
        mode: "ag".to_string(),
        source: "ag".to_string(),
        ..Default::default()
    }
}

/// The rendered row shows the shortened file path (every directory
/// component abbreviated, filename kept in full) BEFORE the matched
/// line content, and does not separately repeat the basename via the
/// usual trailing `# <comment>` slot (which would just be the same
/// filename again).
#[test]
fn ag_row_renders_shortened_path_before_match_content() {
    let mut app = directories_test_app(&[]);
    app.home_list = vec!["/Users/har".to_string()];
    app.ag_state.rows = vec![ag_row(
        "/Users/har/work/project/src/main.rs",
        "fn main() {",
    )];
    app.query = ",main".to_string();
    app.refresh();

    let backend = ratatui::backend::TestBackend::new(120, 30);
    let mut terminal = ratatui::Terminal::new(backend).expect("terminal");
    terminal
        .draw(|f| crate::tui::render::ui(f, &mut app))
        .expect("draw");
    let text = terminal
        .backend()
        .buffer()
        .content
        .iter()
        .map(|c| c.symbol())
        .collect::<String>();

    assert!(
        text.contains("~/w/p/s/main.rs:"),
        "expected the shortened path prefix onscreen, got: {text:?}"
    );
    assert!(
        text.contains("fn main() {"),
        "expected the match content onscreen, got: {text:?}"
    );
    // The path prefix must come before the match content, and the
    // basename must not additionally appear a second time via the
    // trailing `# main.rs` comment slot.
    let path_pos = text.find("~/w/p/s/main.rs:").unwrap();
    let content_pos = text.find("fn main() {").unwrap();
    assert!(
        path_pos < content_pos,
        "shortened path must render BEFORE the match content"
    );
    assert!(
        !text.contains("# main.rs"),
        "basename must not be repeated via the trailing comment slot, got: {text:?}"
    );
}

// --- Mode-scoped indicator columns (capture / tmux-pane) ----
//
// The `o`/`.` output-capture column and the `T`/`.` tmux-pane column
// are fixed-width placeholders that used to render in EVERY mode,
// even ones where they never carry any information (e.g. a `.`
// tmux-pane placeholder in Notes mode, which never has anything to
// report). `render_row` now hides each column outright (an empty
// `Span::raw("")`, contributing zero width) in every mode where it's
// meaningless — see `render_row`'s `capture_span`/`tmux_span`
// doc comments. These tests call `render_row` directly (made
// `pub(crate)` for exactly this) and assert on the exact span
// content by index, rather than scanning rendered text — the columns
// are adjacent single-character-ish spans, easy to conflate with
// surrounding text if tested via a flattened string.

/// Build a minimal non-directory history-style row with the given
/// `output`. Used to probe the capture (`o`/`.`) column.
fn indicator_test_row(output: &str) -> HistoryRow {
    HistoryRow {
        id: 1,
        command: "ls -la".to_string(),
        directory: "/tmp".to_string(),
        session_id: String::new(),
        exit_code: 0,
        timestamp: 0,
        comment: String::new(),
        output: output.to_string(),
        mode: "command".to_string(),
        source: String::new(),
        ..Default::default()
    }
}

/// The output-capture column only ever appears in plain history mode
/// (`ModeKind::History`, i.e. an empty or unprefixed query) — shown
/// lit (` o `) when the row has captured output, dim (` . `)
/// otherwise. In every other prefix mode it's hidden entirely (an
/// empty span, not even the dim placeholder).
#[test]
fn capture_column_only_shown_in_history_mode() {
    let app = directories_test_app(&[]);

    let with_output = indicator_test_row("captured text");
    let without_output = indicator_test_row("");

    // History mode (empty query): lit when output present, dim
    // placeholder when absent.
    let line = crate::tui::render::render_row(&with_output, &app, false, 3);
    assert_eq!(line.spans[1].content.as_ref(), " o ");
    let line = crate::tui::render::render_row(&without_output, &app, false, 3);
    assert_eq!(line.spans[1].content.as_ref(), " . ");

    // Any other prefix mode: hidden entirely, regardless of whether
    // the row happens to carry `output` text (ag mode reuses
    // `output` for its own source-context preview, unrelated to
    // "captured shell output" — the column would be actively
    // misleading there, not just superfluous).
    let mut app = app;
    app.query = ",pattern".to_string();
    let line = crate::tui::render::render_row(&with_output, &app, false, 3);
    assert_eq!(
        line.spans[1].content.as_ref(),
        "",
        "capture column must be hidden outside history mode, even with non-empty output"
    );
    let line = crate::tui::render::render_row(&without_output, &app, false, 3);
    assert_eq!(line.spans[1].content.as_ref(), "");
}

/// The tmux-pane column only ever appears in the two modes whose
/// rows carry `mode == "directory"` — `#` Directories and `~`
/// Zoxide — shown dim (` . `) when no live pane matches (no
/// multiplexer state configured in this test app) and hidden
/// entirely everywhere else, including `*` Panes mode itself (whose
/// own rows already ARE the live panes, so the marker would never
/// have anything to report there either).
#[test]
fn tmux_column_only_shown_in_directory_flavored_modes() {
    let mut app = directories_test_app(&[]);
    let dir_row = HistoryRow {
        id: 1,
        command: "/tmp".to_string(),
        directory: "/tmp".to_string(),
        session_id: String::new(),
        exit_code: 0,
        timestamp: 0,
        comment: String::new(),
        output: String::new(),
        mode: "directory".to_string(),
        source: String::new(),
        ..Default::default()
    };

    app.query = "#dir".to_string();
    let line = crate::tui::render::render_row(&dir_row, &app, false, 3);
    assert_eq!(
        line.spans[2].content.as_ref(),
        " . ",
        "Directories mode must still show the (dim) tmux column"
    );

    app.query = "~dir".to_string();
    let line = crate::tui::render::render_row(&dir_row, &app, false, 3);
    assert_eq!(
        line.spans[2].content.as_ref(),
        " . ",
        "Zoxide mode must still show the (dim) tmux column"
    );

    app.query = String::new();
    let line = crate::tui::render::render_row(&dir_row, &app, false, 3);
    assert_eq!(
        line.spans[2].content.as_ref(),
        "",
        "history mode must hide the tmux column"
    );

    app.query = "*pane".to_string();
    let line = crate::tui::render::render_row(&dir_row, &app, false, 3);
    assert_eq!(
        line.spans[2].content.as_ref(),
        "",
        "panes mode must hide the tmux column too — its own rows already ARE the live panes"
    );
}

// --- tui.highlight (command syntax-highlight cache) ---------------------

use ratatui::style::Modifier as SyntaxHighlightModifier;
use ratatui::style::Style as SyntaxHighlightStyle;
use ratatui::text::Span as SyntaxHighlightSpan;

fn command_test_row(command: &str) -> HistoryRow {
    HistoryRow {
        id: 1,
        command: command.to_string(),
        directory: "/tmp".to_string(),
        session_id: String::new(),
        exit_code: 0,
        timestamp: 0,
        comment: String::new(),
        output: String::new(),
        mode: "command".to_string(),
        source: String::new(),
        ..Default::default()
    }
}

/// The exact cache key `render_row`/`draw_list` use: `(is_light,
/// cmd_display)`. Tests read the same thread-local `PALETTE` state
/// `command_highlight_is_light()` (private to `render.rs`) does,
/// rather than duplicating that helper's visibility just for tests.
fn command_highlight_cache_key_for_test(cmd: &str) -> (bool, String) {
    let is_light =
        crate::tui::theme::palette_storage::PALETTE.with(|p| p.borrow().is_light_theme);
    (is_light, cmd.to_string())
}

/// The core `tui.highlight` behavior: with the feature enabled, no
/// active search query, and a `mode = "command"` row whose text is
/// already cached, `render_row` must use the CACHED spans rather
/// than the plain/matched-substring `highlight_matches` path. Proven
/// by injecting a cache entry with a distinctive, unmistakable style
/// (`Modifier::UNDERLINED`, which nothing else in this code path
/// ever sets) and asserting it survives into the rendered line.
#[test]
fn render_row_uses_syntax_highlight_cache_when_enabled_and_no_query() {
    let mut app = directories_test_app(&[]);
    app.query = String::new();
    app.tui_highlight_enabled = true;
    let row = command_test_row("git status");
    app.command_highlight_cache.insert(
        command_highlight_cache_key_for_test("git status"),
        vec![SyntaxHighlightSpan::styled(
            "git status".to_string(),
            SyntaxHighlightStyle::default().add_modifier(SyntaxHighlightModifier::UNDERLINED),
        )],
    );

    let line = crate::tui::render::render_row(&row, &app, false, 3);
    let has_cached_marker = line
        .spans
        .iter()
        .any(|s| s.style.add_modifier.contains(SyntaxHighlightModifier::UNDERLINED));
    assert!(
        has_cached_marker,
        "expected the cached (underlined) syntax-highlight span to appear, got: {:?}",
        line.spans
    );
}

/// The moment there's an active search query, `render_row` must
/// fall back to `highlight_matches` even though the row is
/// `mode = "command"`, `tui.highlight` is enabled, and a cache entry
/// exists for it — the matched-substring highlight is the more
/// useful signal while actively searching, so it takes priority
/// over syntax color rather than the two being composed together.
#[test]
fn render_row_prefers_match_highlight_over_syntax_cache_when_query_nonempty() {
    let mut app = directories_test_app(&[]);
    app.query = "status".to_string();
    app.tui_highlight_enabled = true;
    let row = command_test_row("git status");
    app.command_highlight_cache.insert(
        command_highlight_cache_key_for_test("git status"),
        vec![SyntaxHighlightSpan::styled(
            "git status".to_string(),
            SyntaxHighlightStyle::default().add_modifier(SyntaxHighlightModifier::UNDERLINED),
        )],
    );

    let line = crate::tui::render::render_row(&row, &app, false, 3);
    let has_cached_marker = line
        .spans
        .iter()
        .any(|s| s.style.add_modifier.contains(SyntaxHighlightModifier::UNDERLINED));
    assert!(
        !has_cached_marker,
        "an active search query must bypass the syntax-highlight cache entirely, got: {:?}",
        line.spans
    );
}

/// With `tui.highlight` disabled, the cache is never consulted even
/// if it happens to hold an entry for this row's text and the query
/// is empty.
#[test]
fn render_row_ignores_syntax_cache_when_feature_disabled() {
    let mut app = directories_test_app(&[]);
    app.query = String::new();
    app.tui_highlight_enabled = false;
    let row = command_test_row("git status");
    app.command_highlight_cache.insert(
        command_highlight_cache_key_for_test("git status"),
        vec![SyntaxHighlightSpan::styled(
            "git status".to_string(),
            SyntaxHighlightStyle::default().add_modifier(SyntaxHighlightModifier::UNDERLINED),
        )],
    );

    let line = crate::tui::render::render_row(&row, &app, false, 3);
    let has_cached_marker = line
        .spans
        .iter()
        .any(|s| s.style.add_modifier.contains(SyntaxHighlightModifier::UNDERLINED));
    assert!(
        !has_cached_marker,
        "tui.highlight=off must never read the cache, got: {:?}",
        line.spans
    );
}

/// A non-`"command"` row (e.g. a `#`-mode directory row) must never
/// use the syntax-highlight cache, even if an entry happens to exist
/// under the exact same text — bash syntax highlighting only makes
/// sense for a real executed command, not a directory path or any
/// other mode's primary text.
#[test]
fn render_row_ignores_syntax_cache_for_non_command_mode_rows() {
    let mut app = directories_test_app(&[]);
    app.query = "#dir".to_string();
    app.tui_highlight_enabled = true;
    let row = HistoryRow {
        id: 1,
        command: "/tmp".to_string(),
        directory: "/tmp".to_string(),
        session_id: String::new(),
        exit_code: 0,
        timestamp: 0,
        comment: String::new(),
        output: String::new(),
        mode: "directory".to_string(),
        source: String::new(),
        ..Default::default()
    };
    app.command_highlight_cache.insert(
        command_highlight_cache_key_for_test("/tmp"),
        vec![SyntaxHighlightSpan::styled(
            "/tmp".to_string(),
            SyntaxHighlightStyle::default().add_modifier(SyntaxHighlightModifier::UNDERLINED),
        )],
    );

    let line = crate::tui::render::render_row(&row, &app, false, 3);
    let has_cached_marker = line
        .spans
        .iter()
        .any(|s| s.style.add_modifier.contains(SyntaxHighlightModifier::UNDERLINED));
    assert!(
        !has_cached_marker,
        "a directory-mode row must never consult the command syntax-highlight cache, got: {:?}",
        line.spans
    );
}

/// `highlight_bash_commands` is pure Rust (`syntect`, not a `bat`
/// subprocess), so unlike its predecessor these tests can exercise
/// REAL highlighting behavior instead of only the empty-input
/// short-circuit -- no external tool availability to worry about in
/// CI or anywhere else.
#[test]
fn highlight_bash_commands_empty_input_returns_empty() {
    assert_eq!(
        crate::highlight::highlight_bash_commands(&[], false),
        Vec::<Vec<crate::highlight::HighlightedSpan>>::new()
    );
}

#[test]
fn highlight_bash_commands_returns_one_entry_per_input_in_order() {
    let out = crate::highlight::highlight_bash_commands(&["git status", "ls -la"], false);
    assert_eq!(out.len(), 2);
    // Reassembling each entry's token text must reproduce the
    // original command exactly -- no dropped or reordered text.
    assert_eq!(
        out[0].iter().map(|s| s.text.as_str()).collect::<String>(),
        "git status"
    );
    assert_eq!(
        out[1].iter().map(|s| s.text.as_str()).collect::<String>(),
        "ls -la"
    );
}

/// The actual point of highlighting: a command with a recognizable
/// bash construct (a `-`-prefixed flag) must come back as MORE than
/// one token/color -- proving `syntect` is really applying the bash
/// grammar, not just handing back the whole line as one plain span
/// (which would indicate the syntax lookup silently fell back to
/// plain text).
#[test]
fn highlight_bash_commands_produces_multiple_tokens_for_a_flagged_command() {
    let out = crate::highlight::highlight_bash_commands(&["docker run -it --rm ubuntu"], false);
    assert_eq!(out.len(), 1);
    assert!(
        out[0].len() > 1,
        "expected bash syntax highlighting to split this command into multiple tokens, got: {:?}",
        out[0]
    );
}

/// Light and dark must select genuinely different color palettes
/// (`base16-ocean.light` vs `base16-ocean.dark`) -- proven by
/// checking at least one token's resolved RGB differs between the
/// two calls for the same command.
#[test]
fn highlight_bash_commands_light_and_dark_use_different_palettes() {
    let dark = crate::highlight::highlight_bash_commands(&["git status"], false);
    let light = crate::highlight::highlight_bash_commands(&["git status"], true);
    assert_eq!(dark.len(), 1);
    assert_eq!(light.len(), 1);
    assert_ne!(
        dark[0].iter().map(|s| s.color).collect::<Vec<_>>(),
        light[0].iter().map(|s| s.color).collect::<Vec<_>>(),
        "light and dark themes must resolve to different colors"
    );
}

/// The exit-status column (`✓`/`✗`/`~`) only appears in modes whose
/// rows can carry a genuinely varying `exit_code`: `History`,
/// `Output`, `Llm`, `Question` (all backed by the shared history
/// table, and `Llm`/`Question` mix a synthetic preview row in
/// alongside real matches — see `build_merged_rows`), and `Jira`
/// (which repurposes `exit_code` as closed/open). Every other mode
/// hardcodes `exit_code: 0` for every row, so the column is hidden
/// outright rather than showing an always-identical `✓`.
#[test]
fn exit_marker_column_scoped_to_modes_with_real_exit_codes() {
    let mut app = directories_test_app(&[]);
    let ok_row = indicator_test_row("");
    let mut failing_row = indicator_test_row("");
    failing_row.exit_code = 1;

    // Shown, and correct, in the five modes with real signal.
    for (prefix, mode_name) in [
        ("", "history"),
        ("+text", "output"),
        ("=describe", "llm"),
        ("?question", "question"),
        ("-JIRA", "jira"),
    ] {
        app.query = prefix.to_string();
        let line = crate::tui::render::render_row(&ok_row, &app, false, 3);
        assert!(
            line.spans.iter().any(|s| s.content.contains('✓')),
            "{mode_name} mode must show the ✓ exit marker for a successful row, got: {:?}",
            line.spans.iter().map(|s| s.content.to_string()).collect::<Vec<_>>()
        );
        let line = crate::tui::render::render_row(&failing_row, &app, false, 3);
        assert!(
            line.spans.iter().any(|s| s.content.contains('✗')),
            "{mode_name} mode must show the ✗ exit marker for a failing row, got: {:?}",
            line.spans.iter().map(|s| s.content.to_string()).collect::<Vec<_>>()
        );
    }

    // Hidden everywhere else — spot-check a representative sample
    // (a data-source mode, a synthetic-list mode, and a
    // directory-flavored mode) rather than every single prefix.
    for prefix in ["#dir", "*pane", ",pattern", "@note", "!todo", "~zox"] {
        app.query = prefix.to_string();
        let line = crate::tui::render::render_row(&ok_row, &app, false, 3);
        assert!(
            !line.spans.iter().any(|s| s.content.contains('✓')
                || s.content.contains('✗')
                || s.content.contains('~')),
            "prefix {prefix:?} must hide the exit marker column entirely, got: {:?}",
            line.spans.iter().map(|s| s.content.to_string()).collect::<Vec<_>>()
        );
    }
}

// --- Age column recency color ----

/// Build a row whose `timestamp` is `seconds_ago` seconds before now
/// — used to land in a specific `format_diff` unit bucket
/// (seconds/minutes/hours/days/months) for the age-color tests below.
fn aged_row(seconds_ago: i64) -> HistoryRow {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    HistoryRow {
        id: 1,
        command: "ls -la".to_string(),
        directory: "/tmp".to_string(),
        session_id: String::new(),
        exit_code: 0,
        timestamp: now - seconds_ago,
        comment: String::new(),
        output: String::new(),
        mode: "command".to_string(),
        source: String::new(),
        ..Default::default()
    }
}

/// The `[x]`/`[ ]` mark column only appears in the modes where
/// marking a row actually has an effect: `History`/`Output` (real
/// SQL ids, `BulkDeleteMarked` works), and `Files`/`Todo`/`Jira`
/// (each has a `SmartOpen` handler that consults
/// `smart_action_targets()`). Every other mode's `SmartOpen` arm
/// acts on the single selected row only and never reads
/// `marked_ids`, so the column is hidden there.
#[test]
fn mark_column_scoped_to_modes_where_marking_has_an_effect() {
    let mut app = directories_test_app(&[]);
    let row = indicator_test_row("");
    app.marked_ids.insert(mark_key(&row));

    for (prefix, mode_name) in [
        ("", "history"),
        ("+text", "output"),
        ("/README", "files"),
        ("!todo", "todo"),
        ("-JIRA", "jira"),
    ] {
        app.query = prefix.to_string();
        let line = crate::tui::render::render_row(&row, &app, false, 3);
        assert_eq!(
            line.spans[0].content.as_ref(),
            "[x]",
            "{mode_name} mode must show the mark column for a marked row, got: {:?}",
            line.spans.iter().map(|s| s.content.to_string()).collect::<Vec<_>>()
        );
    }

    for prefix in ["#dir", "*pane", ",pattern", "@note", "~zox", "&sym"] {
        app.query = prefix.to_string();
        let line = crate::tui::render::render_row(&row, &app, false, 3);
        assert_eq!(
            line.spans[0].content.as_ref(),
            "",
            "prefix {prefix:?} must hide the mark column — marking has no effect there, got: {:?}",
            line.spans.iter().map(|s| s.content.to_string()).collect::<Vec<_>>()
        );
    }
}

// --- Files-mode (`/`) display path shortening ----
//
// `row.command` for a files-mode row is a path RELATIVE to the
// walked root (see `compute_display` in `src/files.rs`), which can
// still run long for a deeply-nested file. `render_row` shortens it
// for DISPLAY ONLY via `util::shorten_path_dirs`, without touching
// the underlying search/filter text.

/// Build a minimal `/`-mode `HistoryRow` with the given relative
/// `command` path.
fn files_row(command: &str) -> HistoryRow {
    HistoryRow {
        id: -1,
        command: command.to_string(),
        directory: format!("/abs/{command}"),
        session_id: String::new(),
        exit_code: 0,
        timestamp: 0,
        comment: String::new(),
        output: String::new(),
        mode: "file".to_string(),
        source: String::new(),
        ..Default::default()
    }
}

/// The age column's color follows a recency gradient — brightest for
/// "just happened", dimming as the row gets older — reading the
/// bucket straight off `format_diff`'s own unit-ladder suffix
/// (s/m/h/d/M) rather than re-deriving elapsed time. The age span is
/// always `spans[4]` (mark/capture/tmux/llm-preview, then age),
/// regardless of which of those precede it are hidden for the
/// current mode — they stay as empty placeholders in the vec, not
/// removed.
#[test]
fn age_column_color_follows_recency_gradient() {
    let app = directories_test_app(&[]);

    let seconds_row = aged_row(5);
    let line = crate::tui::render::render_row(&seconds_row, &app, false, 3);
    assert_eq!(
        line.spans[4].style.fg,
        Some(crate::tui::theme::Theme::highlight_color()),
        "a few seconds old must use the brightest (highlight) color"
    );

    let minutes_row = aged_row(5 * 60);
    let line = crate::tui::render::render_row(&minutes_row, &app, false, 3);
    assert_eq!(
        line.spans[4].style.fg,
        Some(crate::tui::theme::Theme::success_color()),
        "a few minutes old must use the success color"
    );

    let hours_row = aged_row(5 * 3600);
    let line = crate::tui::render::render_row(&hours_row, &app, false, 3);
    assert_eq!(
        line.spans[4].style.fg,
        Some(crate::tui::theme::Theme::accent_color()),
        "a few hours old must use the accent color (the previous flat default)"
    );

    let days_row = aged_row(5 * 86_400);
    let line = crate::tui::render::render_row(&days_row, &app, false, 3);
    assert_eq!(
        line.spans[4].style.fg,
        Some(crate::tui::theme::Theme::dim_color()),
        "a few days old must use the dim color"
    );

    // Months old (well past `format_diff`'s month-ladder threshold).
    let months_row = aged_row(200 * 86_400);
    let line = crate::tui::render::render_row(&months_row, &app, false, 3);
    assert_eq!(
        line.spans[4].style.fg,
        Some(crate::tui::theme::Theme::dimmer_color()),
        "months old must use the dimmest color"
    );

    // The `timestamp: 0` sentinel `format_diff` treats as invalid
    // (falls back to its "9999M" placeholder, e.g. a `directory` row
    // that has no meaningful timestamp) lands in the same dimmest
    // bucket as a genuinely old row.
    let mut zero_row = aged_row(0);
    zero_row.timestamp = 0;
    let line = crate::tui::render::render_row(&zero_row, &app, false, 3);
    assert_eq!(
        line.spans[4].style.fg,
        Some(crate::tui::theme::Theme::dimmer_color()),
        "the timestamp: 0 sentinel must also use the dimmest color"
    );
}

