// --- Tmux-pane marker (`#` directories mode) ----

/// `directory_has_tmux_pane`
/// returns false when the
/// snapshot is empty
/// (never populated). This
/// is the contract: before
/// the user types `#…`
/// (which triggers the
/// snapshot fetch) the
/// check is a hard `false`
/// so no rows are falsely
/// marked as in-tmux.
#[test]
fn directory_tmux_pane_id_empty_snapshot_is_none() {
    let app = directories_test_app(&[("ls", "/home/user", 60)]);
    assert!(app.tmux_windows.is_empty());
    assert!(app.directory_tmux_pane_id("/home/user").is_none());
}

/// `directory_tmux_pane_id`
/// returns `Some(pane_id)`
/// iff a window's `path`
/// (canonicalised at parse
/// time) matches the input
/// directory (also
/// canonicalised). The
/// `#{pane_id} |
///  #{pane_current_path} |
///  active:#{window_active}
///  | Layout:
///  #{window_layout}` format
/// used by `tmux
/// list-windows -a` always
/// reports the kernel's
/// canonical cwd, which on
/// macOS is the
/// `/Volumes/HUGE/...`
/// form, while the directory
/// stored by the
/// `preexec` hook is the
/// user's logical
/// `/Users/...` form — both
/// canonicalise to the same
/// string. This test verifies
/// that contract without
/// actually spawning
/// `tmux` (CI may not have it
/// installed).
#[test]
fn directory_tmux_pane_id_canonicalises_both_sides() {
    let mut app = directories_test_app(&[("ls", "/home/user", 60)]);
    // Simulate a snapshot
    // that came from `tmux`.
    // `fetch_tmux_windows`
    // canonicalises these
    // at parse time, so the
    // stored `path` is
    // already canonical. We
    // hand-craft the same
    // canonical value here.
    app.tmux_windows.push(TmuxWindowInfo {
        pane_id: "%0".to_string(),
        path: String::from("/home/user"),
        ..Default::default()
    });
    assert_eq!(
        app.directory_tmux_pane_id("/home/user").as_deref(),
        Some("%0"),
        "exact match must return the pane id"
    );
    // Wrong directory, same
    // prefix — must NOT match.
    assert!(app.directory_tmux_pane_id("/home/other").is_none());
}

/// The actual reported
/// bug: `tmux` reports
/// `/Volumes/HUGE/...` for
/// directories under
/// `/Users/har/...` because
/// of macOS volume mounts,
/// while the `preexec` hook
/// records the user's
/// logical `/Users/...`
/// form. Without
/// canonicalization, the
/// two would never match.
/// This test guarantees
/// they do.
#[test]
fn directory_tmux_pane_id_handles_macos_volume_mount() {
    let mut app = directories_test_app(&[("ls", "/Users/har/Sources/x", 60)]);
    // `tmux` returns the
    // canonical form (which on
    // macOS resolves through
    // any symlinks / volume
    // mounts). The fetch
    // helper canonicalises
    // these at parse time; we
    // pop a pre-canonicalised
    // entry.
    //
    // We don't depend on a
    // specific macOS path here
    // — we just verify the
    // canonicalisation
    // contract: as long as
    // both forms collapse to
    // the same string
    // (which the
    // `canonicalize_directory`
    // helper does), the match
    // succeeds.
    let canonical_dir = std::fs::canonicalize("/tmp")
        .map(|p| p.to_string_lossy().into_owned())
        .unwrap_or_else(|_| "/tmp".into());
    app.tmux_windows.push(TmuxWindowInfo {
        pane_id: "%42".to_string(),
        path: canonical_dir.clone(),
        ..Default::default()
    });
    assert_eq!(
        app.directory_tmux_pane_id(&canonical_dir).as_deref(),
        Some("%42"),
        "real-path lookup must match the canonical pane path"
    );
    // Try a non-canonical
    // form: should still
    // match because the
    // helper canonicalises
    // input too. We use a
    // different dir here so
    // the test is
    // deterministic —
    // `/var` is a symlink to
    // `/private/var` on
    // macOS but a real dir on
    // Linux CI.
    let var_canonical = std::fs::canonicalize("/var")
        .map(|p| p.to_string_lossy().into_owned())
        .unwrap_or_else(|_| "/var".into());
    if var_canonical != "/var" {
        // macOS: `/var`
        // canonicalises to
        // `/private/var`. We
        // push that pane
        // and check that
        // asking for either
        // form matches.
        app.tmux_windows.push(TmuxWindowInfo {
            pane_id: "%7".to_string(),
            path: var_canonical,
            ..Default::default()
        });
        assert!(
            app.directory_tmux_pane_id("/var").is_some(),
            "/var must canonicalise to match"
        );
    }
    // Wrong directory
    // totally shouldn't
    // match.
    assert!(app.directory_tmux_pane_id("/home/nowhere").is_none());
}

/// Regression test for the
/// homemap-aware
/// normalization: a DB
/// row stored in the
/// short `~/x` form
/// (after
/// `smarthistory
/// update`) must match
/// a tmux-reported
/// pane at the
/// absolute form
/// (e.g. `/Users/har/x`).
///
/// Without the
/// homemap-aware
/// expansion, the
/// `std::fs::canonicalize`
/// step on the `~/x`
/// side would fail (no
/// real `~/x` path
/// exists) and fall
/// back to the un-
/// resolved input,
/// which never matched
/// the tmux side. The
/// result: a directory
/// row that DID have a
/// live tmux pane was
/// missing the `T`
/// marker.
///
/// `/tmp` (which always exists on every machine, no
/// synthetic setup needed) is the test directory. Both sides
/// compared in `directory_tmux_pane_id` are already-absolute
/// canonical `/tmp` paths (no literal `~` in either), so this
/// doesn't actually need `app.home_list` populated or `$HOME`
/// overridden to pass — no env mutation, no `ENV_LOCK`.
#[test]
fn directory_tmux_pane_id_handles_tilde_form_db_row() {
    let mut app = directories_test_app(&[("ls", "/tmp", 60)]);
    app.tmux_windows.push(TmuxWindowInfo {
        pane_id: "%99".to_string(),
        // The path tmux
        // reports is
        // already the
        // canonical
        // absolute form
        // (no `~`).
        path: std::fs::canonicalize("/tmp")
            .map(|p| p.to_string_lossy().into_owned())
            .unwrap_or_else(|_| "/tmp".into()),
        ..Default::default()
    });
    // The user-facing
    // directory in the
    // DB is the short
    // form `~/x` (or
    // here, the home
    // itself: `~`).
    // This is the case
    // the user reported:
    // a row stored in
    // `~/x` form should
    // still get the `T`
    // marker when a
    // tmux pane is at
    // the matching
    // absolute path.
    let canonical_tmp = std::fs::canonicalize("/tmp")
        .map(|p| p.to_string_lossy().into_owned())
        .unwrap_or_else(|_| "/tmp".into());
    assert_eq!(
        app.directory_tmux_pane_id(&canonical_tmp).as_deref(),
        Some("%99"),
        "absolute-path DB row must match the tmux pane"
    );
}

/// Regression test for the
/// user-reported bug:
/// `multiplexer=herdr`
/// in the config, but
/// a new workspace was
/// created for a
/// directory that was
/// already part of an
/// existing workspace.
/// The root cause was
/// that the herdr
/// snapshot parser
/// returned an empty
/// list (herdr's
/// `pane list` output
/// is JSON, not the
/// `|`-separated text
/// the old parser
/// expected), so the
/// T-marker lookup
/// always returned
/// `None` and the
/// staging always
/// branched to
/// `herdr workspace create`.
/// This test
/// guarantees the
/// parser produces
/// `tmux_windows` rows
/// and that the T-marker
/// lookup finds the
/// existing workspace
/// so the staging can
/// reuse it via
/// `herdr workspace focus`
/// instead of creating
/// a duplicate.
#[cfg(feature = "herdr")]
#[test]
fn directory_with_existing_herdr_workspace_reuses_via_t_marker() {
    // One history row at
    // `/var/tmp/build` —
    // the user has run
    // commands there.
    let mut app = directories_test_app(&[("ls -la", "/var/tmp/build", 60)]);
    // Swap in the herdr
    // backend.
    app.multiplexer = crate::multiplexer::backend_for(crate::multiplexer::MultiplexerKind::Herdr);
    // Simulate the
    // snapshot the
    // herdr backend
    // would produce:
    // one active pane
    // at `/var/tmp/build`
    // in workspace
    // `wA`.
    app.tmux_windows.push(TmuxWindowInfo {
        pane_id: String::from("wA:p1"),
        path: String::from("/var/tmp/build"),
        ..Default::default()
    });
    // The T-marker
    // lookup must now
    // find the
    // existing
    // workspace's pane
    // id.
    assert_eq!(
        app.directory_tmux_pane_id("/var/tmp/build").as_deref(),
        Some("wA:p1"),
        "T-marker lookup must return the existing herdr pane id"
    );
    // The staging then
    // calls
    // `self.multiplexer.focus_command("wA:p1")`
    // which produces
    // `herdr workspace focus wA`
    // (the `:p1` suffix
    // is stripped by
    // the backend).
    let staged = app
        .multiplexer
        .focus_command("wA:p1")
        .expect("non-empty pane id");
    assert_eq!(staged, "herdr workspace focus wA 2>/dev/null");
    // And a directory
    // without a matching
    // workspace must
    // still produce
    // `herdr workspace create`
    // (the unmarked
    // branch) — the
    // fix doesn't
    // regress the
    // create path.
    assert!(app.directory_tmux_pane_id("/var/tmp/elsewhere").is_none());
}

/// The `tmux_windows` snapshot
/// is preserved across
/// `refresh()` calls — the
/// helper is idempotent and
/// the fetch only happens
/// when the snapshot is
/// empty. Otherwise
/// scrolling through the
/// directories list would
/// re-spawn `tmux` on every
/// keypress.
///
/// This test verifies the
/// idempotency by
/// pre-populating the
/// snapshot, calling
/// `fetch_tmux_windows`
/// once, and asserting the
/// snapshot didn't change.
/// (We don't run `refresh()`
/// here because in a test
/// environment without
/// `tmux` on PATH the
/// `refresh()` call would
/// set the snapshot to
/// empty, masking the
/// behaviour we want to
/// verify.)
#[test]
fn fetch_tmux_windows_is_idempotent_when_populated() {
    let mut app = directories_test_app(&[("ls", "/home/user", 60)]);
    // Pre-populate the
    // snapshot with a
    // sentinel value that
    // would be wiped if the
    // helper re-ran.
    let sentinel = TmuxWindowInfo {
        pane_id: "%99".to_string(),
        path: String::from("/sentinel"),
        ..Default::default()
    };
    app.tmux_windows.push(sentinel.clone());
    // The helper exits
    // early when the snapshot
    // is non-empty. This is
    // the "don't re-spawn on
    // every refresh" contract.
    crate::tui::mode::directories::ensure_multiplexer_snapshot(&mut app);
    assert_eq!(app.tmux_windows.len(), 1);
    assert_eq!(app.tmux_windows[0].pane_id, "%99");
    assert_eq!(app.tmux_windows[0].path, "/sentinel");
}

// --- Lazy `session_subdirs` walk (perf: don't walk `sessiondirs=`
// on every TUI launch) ----
//
// `ensure_session_subdirs` used to run unconditionally at TUI
// startup (`build_session_subdirs`, called from `run_tui_to_stdout`
// before `App::new`) — a real filesystem walk plus a
// `canonicalize()` syscall per subdirectory, paid on every launch
// even when the user never visits `#`/`~` mode that session. It's
// now deferred to the first actual `#`-mode `refresh()`, gated by
// `session_subdirs_walked` (see that field's doc comment for why a
// dedicated flag, not `session_subdirs.is_empty()`, is the sentinel).

/// The first call with unwalked roots performs a real walk and
/// marks itself done.
#[test]
fn ensure_session_subdirs_walks_configured_roots() {
    let mut app = directories_test_app(&[]);
    let root = std::env::temp_dir().join(format!(
        "smarthistory_lazy_subdirs_test_{}_{}",
        std::process::id(),
        "walk"
    ));
    let nested = root.join("project-a");
    let _ = std::fs::create_dir_all(&nested);

    app.session_dirs_roots = vec![root.clone()];
    app.session_subdirs_walked = false;
    assert!(app.session_subdirs.is_empty());

    crate::tui::mode::directories::ensure_session_subdirs(&mut app);

    assert!(app.session_subdirs_walked);
    assert!(
        app.session_subdirs.iter().any(|p| p == &nested),
        "expected {:?} in {:?}",
        nested,
        app.session_subdirs
    );

    let _ = std::fs::remove_dir_all(&root);
}

/// Once `session_subdirs_walked` is `true`, a second call is a
/// no-op — the exact "don't re-walk on every refresh" contract this
/// feature exists for. Verified with a sentinel value that would be
/// overwritten (with a real, but different, walk result) if the
/// guard didn't hold.
#[test]
fn ensure_session_subdirs_is_idempotent_once_walked() {
    let mut app = directories_test_app(&[]);
    let root = std::env::temp_dir().join(format!(
        "smarthistory_lazy_subdirs_test_{}_{}",
        std::process::id(),
        "idempotent"
    ));
    let _ = std::fs::create_dir_all(root.join("would-be-found"));

    let sentinel = std::path::PathBuf::from("/sentinel/not-a-real-walk-result");
    app.session_dirs_roots = vec![root.clone()];
    app.session_subdirs = vec![sentinel.clone()];
    app.session_subdirs_walked = true;

    crate::tui::mode::directories::ensure_session_subdirs(&mut app);

    assert_eq!(
        app.session_subdirs,
        vec![sentinel],
        "must not re-walk once session_subdirs_walked is true"
    );

    let _ = std::fs::remove_dir_all(&root);
}

/// `App::refresh()` in `#` (Directories) mode triggers the lazy walk
/// end-to-end (not just the extracted helper in isolation) and the
/// resulting subdirectory shows up as a row.
#[test]
fn directories_mode_refresh_triggers_lazy_session_subdirs_walk() {
    let mut app = directories_test_app(&[]);
    let root = std::env::temp_dir().join(format!(
        "smarthistory_lazy_subdirs_test_{}_{}",
        std::process::id(),
        "end_to_end"
    ));
    let nested = root.join("pinned-project");
    let _ = std::fs::create_dir_all(&nested);

    app.session_dirs_roots = vec![root.clone()];
    app.session_subdirs_walked = false;
    app.query = "#".to_string();
    app.refresh();

    assert!(app.session_subdirs_walked);
    let nested_str = nested.to_string_lossy().into_owned();
    assert!(
        app.merged_rows().iter().any(|r| r.directory == nested_str),
        "expected the lazily-walked sessiondir to appear as a row"
    );

    let _ = std::fs::remove_dir_all(&root);
}

/// Regression test for the
/// user-reported bug:
/// `multiplexer=herdr` in
/// the config, but the
/// T-marker was showing
/// for directories that
/// don't have an active
/// herdr workspace. The
/// root cause was that
/// `fetch_tmux_windows`
/// ignored the configured
/// backend and shelled
/// out to `tmux list-windows`
/// directly, so the
/// T-marker was being
/// driven by tmux's
/// snapshot regardless
/// of the user's `multiplexer`
/// setting. After the
/// fix, `fetch_tmux_windows`
/// delegates to
/// `self.multiplexer.snapshot()`,
/// so the T-marker only
/// reflects the active
/// backend's view.
///
/// We can't easily assert
/// "the herdr snapshot was
/// called" here (we'd
/// need to mock the
/// subprocess). What we
/// CAN assert is that
/// when the configured
/// backend is herdr, the
/// `multiplexer.name()` on
/// the App matches
/// "herdr" — and that the
/// `Box<dyn ...>` stored
/// in `App::multiplexer`
/// is the herdr backend
/// (via the `name()` trait
/// method, which returns
/// the backend's own
/// claim of its identity).
/// The actual JSON-parsing
/// direction is covered by
/// `multiplexer::tests::parse_herdr_pane_list`;
/// this test pins the
/// "backend selection"
/// contract.
#[cfg(feature = "herdr")]
#[test]
fn fetch_tmux_windows_resolves_to_configured_backend() {
    let app = directories_test_app(&[]);
    // The default test
    // helper builds a tmux
    // backend, so swap in
    // the herdr backend to
    // mirror what a
    // `multiplexer=herdr`
    // config would
    // produce.
    let mut app = app;
    app.multiplexer = crate::multiplexer::backend_for(crate::multiplexer::MultiplexerKind::Herdr);
    assert_eq!(
        app.multiplexer.name(),
        "herdr",
        "the App must hold the herdr backend when the \
                 user has `multiplexer=herdr`; the T-marker \
                 comes from this backend's snapshot, not from \
                 a hard-coded tmux list-windows call"
    );
}

/// Real-world tmux output
/// sampled from the user's
/// own machine at the time
/// this test was added.
/// Verifies our parser
/// handles the live format
/// string
/// (`#{pane_id} |
///  #{pane_current_path} |
///  active:#{window_active}
///  | Layout:
///  #{window_layout}`)
/// correctly.
///
/// If this test fails,
/// either tmux changed its
/// format tokens (unlikely)
/// or our format string in
/// `fetch_tmux_windows` got
/// silently truncated.
/// Either way, the
/// `parse_tmux_pane_line`
/// contract has shifted;
/// re-pin the live format in
/// `fetch_tmux_windows` first.
#[test]
fn parse_tmux_pane_line_real_world_output() {
    // Captured from the user's
    // environment with
    // `tmux list-windows -a -F
    // '#{pane_id} |
    //  #{pane_current_path} |
    //  active:#{window_active} |
    //  Layout:
    //  #{window_layout}'
    //  | grep "active:1"`.
    // (All rows below are
    // active:1 because they
    // come from grepped
    // output.)
    let sample = "\
                %0 | /Users/har | active:1 | Layout: c17d,121x93,0,0,0\n\
                %2 | /Volumes/HUGE/har/Sources/markdown-search/note_search | active:1 | Layout: 3971,121x93,0,0[121x46,0,0,2,121x46,0,47,10]\n\
                %1 | /Users/har/smarthistory/smarthistory | active:1 | Layout: 7254,121x93,0,0[121x46,0,0,1,121x46,0,47,3]\n";
    let windows: Vec<TmuxWindowInfo> = sample.lines().filter_map(parse_tmux_pane_line).collect();
    assert_eq!(
        windows.len(),
        3,
        "expected 3 parsed windows, got: {:#?}",
        windows
    );
    // First window: pane id
    // `%0`, path
    // canonicalises to the
    // user's macOS
    // `/Users/har` (no
    // symlinks involved in
    // this test dir, so
    // canonicalisation is
    // a no-op).
    assert_eq!(windows[0].pane_id, "%0");
    assert_eq!(
        std::fs::canonicalize("/Users/har")
            .map(|p| p.to_string_lossy().into_owned())
            .unwrap_or_else(|_| { "/Users/har".into() }),
        windows[0].path,
    );
    // Second window: pane
    // id `%2`, path
    // already-canonical
    // `/Volumes/HUGE/...`.
    assert_eq!(windows[1].pane_id, "%2");
    assert_eq!(
        windows[1].path,
        "/Volumes/HUGE/har/Sources/markdown-search/note_search"
    );
}

/// `parse_tmux_pane_line`
/// drops inactive windows
/// (`active:0` rows). The
/// user's spec pipes
/// through `grep "active:1"`
/// — we do the filter
/// in-process so we only
/// spawn one subprocess.
#[test]
fn parse_tmux_pane_line_filters_inactive_windows() {
    let inactive = "%0 | /Users/har | active:0 | Layout: c17d,121x93,0,0,0";
    let active = "%0 | /Users/har | active:1 | Layout: c17d,121x93,0,0,0";
    assert!(
        parse_tmux_pane_line(inactive).is_none(),
        "active:0 must be filtered out"
    );
    assert!(parse_tmux_pane_line(active).is_some());
}

/// The format-string bug we
/// hit during development:
/// tmux format strings use
/// `#`-prefixed placeholders
/// (`#S`, `#{pane_current_path}`),
/// with **the `#` always
/// required**. Writing
/// `"{S}"` instead of `"#S"`
/// silently renders an empty
/// first column, then any
/// strict parser that skips
/// empty fields throws the
/// whole line away. The
/// `FORMAT` constant in
/// `fetch_tmux_windows` is
/// tested by `tmux
/// list-windows -a -F`; the
/// regression test below
/// pins the correct format.
#[test]
fn parse_tmux_pane_line_rejects_buggy_format() {
    // What `tmux list-windows -a
    // -F "{S} | ... | active:0 | ..."`
    // (buggy format) would
    // actually emit — first
    // column empty. We don't
    // pin every field here
    // (the parse fails on
    // the empty `pane_id`
    // check); just the empty
    // first column.
    let buggy_line = " | /Users/har | active:1 | Layout: x";
    assert!(
        parse_tmux_pane_line(buggy_line).is_none(),
        "an empty pane_id field must be rejected, \
                 otherwise the whole tmux snapshot becomes \
                 silently empty and no T markers render"
    );
    // The non-buggy version
    // (with `#{pane_id}`)
    // parses correctly.
    let good_line = "%0 | /Users/har | active:1 | Layout: x";
    assert!(parse_tmux_pane_line(good_line).is_some());
}

/// End-to-end: pre-loading
/// the snapshot with a window
/// whose canonical path
/// matches a directory row
/// causes
/// `directory_tmux_pane_id`
/// to return the pane id.
/// This is the chain that
/// produces the user-visible
/// `T` marker.
#[test]
fn directory_row_is_marked_after_snapshot_loaded() {
    // This test verifies the canonicalisation contract:
    // a DB row stored under one path form must match a
    // tmux window stored under a different form that
    // resolves to the same physical directory.
    //
    // On macOS, /Users/har/... and
    // /Volumes/HUGE/har/... can be the same dir
    // (external volume mount). On Linux CI there's no
    // such mount, so we use a symlink instead: create
    // a temp dir, symlink it, and verify the two
    // forms resolve to the same canonical path.
    let real = std::env::temp_dir().join("sh_real_dir");
    let link = std::env::temp_dir().join("sh_link_dir");
    let _ = std::fs::remove_dir_all(&real);
    let _ = std::fs::remove_file(&link);
    std::fs::create_dir_all(&real).unwrap();
    #[cfg(unix)]
    std::os::unix::fs::symlink(&real, &link).unwrap();

    let mut app = directories_test_app(&[("ls", real.to_str().unwrap(), 60)]);
    app.tmux_windows.push(TmuxWindowInfo {
        pane_id: "%1".to_string(),
        path: link.to_string_lossy().into_owned(),
        ..Default::default()
    });
    assert_eq!(
        app.directory_tmux_pane_id(real.to_str().unwrap())
            .as_deref(),
        Some("%1"),
        "the row stored as {:?} must match a window \
                 stored as {:?} — the canonicalisation contract",
        real,
        link
    );
    let _ = std::fs::remove_dir_all(&real);
    let _ = std::fs::remove_file(&link);
}

/// Selecting a `T`-marked
/// directory row stages
/// `tmux select-pane -t <id>
/// && tmux switch-client -t
/// <id>`. The parent shell
/// (running the TUI as a
/// child) eval's the
/// staged command, which
/// (since we're inside a
/// tmux client) switches
/// the client to the
/// targeted pane.
#[test]
fn select_t_marked_directory_stages_select_and_switch() {
    // Use a symlink to simulate the macOS volume-mount
    // scenario (two path forms that resolve to the same
    // physical directory). This makes the test
    // platform-independent.
    let real = std::env::temp_dir().join("sh_tmark_real");
    let link = std::env::temp_dir().join("sh_tmark_link");
    let _ = std::fs::remove_dir_all(&real);
    let _ = std::fs::remove_file(&link);
    std::fs::create_dir_all(&real).unwrap();
    #[cfg(unix)]
    std::os::unix::fs::symlink(&real, &link).unwrap();

    let mut app = directories_test_app(&[("ls", real.to_str().unwrap(), 60)]);
    // Snapshot contains one active window for
    // the directory above (via the symlink path,
    // which canonicalises to the same real path).
    app.tmux_windows.push(TmuxWindowInfo {
        pane_id: "%2".to_string(),
        path: link.to_string_lossy().into_owned(),
        ..Default::default()
    });
    app.query = "#".to_string();
    app.refresh();
    // The row is the only
    // one in merged_rows.
    assert_eq!(app.merged_rows().len(), 1);
    app.select_for_run();
    let staged = app.selection.as_deref().expect("selection must be set");
    assert!(
        staged.contains("tmux select-pane -t %2") && staged.contains("tmux switch-client -t %2"),
        "staged command must call both \
                 select-pane and switch-client with the \
                 pane id, got: {staged:?}"
    );
    // The two must be
    // `&&`-chained so the
    // user doesn't end up
    // switching to a
    // half-targeted client if
    // select-pane failed.
    assert!(
        staged.contains("&&"),
        "select-pane and switch-client must be &&-chained, got: {staged:?}"
    );
    assert_eq!(app.pick_mode, Some(crate::tui::state::PickMode::Run),);
}

/// Selecting an unmarked
/// directory row stages
/// `tmux new-session -d -s
/// <basename> -c <dir>;
/// tmux switch-client -t
/// <basename>`. The
/// basename is
/// `Path::file_name` of the
/// directory; a quote is
/// added if the path has
/// shell metacharacters.
#[test]
fn select_unmarked_directory_stages_new_session_and_switch() {
    let mut app = directories_test_app(&[("ls", "/Users/har/Projects/coolthing", 60)]);
    // Empty snapshot —
    // nothing matches.
    app.query = "#".to_string();
    app.refresh();
    // Select the
    // SQL-history row
    // explicitly.
    let sql_row_idx = app
        .merged_rows()
        .iter()
        .position(|r| r.directory == "/Users/har/Projects/coolthing")
        .expect("the SQL-history row for /Users/har/Projects/coolthing must be in merged_rows");
    app.list_state.select(Some(sql_row_idx));
    app.select_for_run();
    let staged = app.selection.as_deref().expect("selection must be set");
    // The directory is
    // under $HOME so it's
    // shortened to
    // `~/Projects/coolthing`
    // for display in the
    // staged command (the
    // user asked for `~` "as
    // much as possible"; tmux
    // also doesn't do `~`
    // expansion itself, so we
    // have to do it here).
    // The bare absolute path
    // is also accepted by
    // tmux, so this isn't a
    // correctness contract —
    // it's a UX one. The
    // dedicated tilde test
    // (`select_unmarked_directory_expands_tilde`)
    // pins the expansion
    // behaviour more
    // directly.
    assert!(
        staged.contains("tmux new-session -d -s coolthing -c ~/Projects/coolthing")
            || staged.contains("tmux new-session -d -s coolthing -c /Users/har/Projects/coolthing"),
        "staged command must create detached session with the directory basename, got: {staged:?}"
    );
    assert!(
        staged.contains("tmux switch-client -t coolthing"),
        "staged command must switch-client to the new session, got: {staged:?}"
    );
    // The two are ;-chained
    // (not &&): the user
    // wants new-session to
    // run regardless of
    // any failure, and
    // switch-client is a
    // follow-up that may or
    // may not succeed (e.g.
    // session already exists
    // in the user's setup
    // with the same name —
    // that's a different
    // error the parent shell
    // surfaces).
    assert!(
        staged.contains("; "),
        "new-session and switch-client must be ;-chained, got: {staged:?}"
    );
}

/// Paths with shell
/// metacharacters get
/// quoted in the staged
/// `cd <path>` — same
/// defensive quoting
/// already used in todo
/// mode. This is the v1
/// "be safe" contract; the
/// user can always edit
/// the staged command
/// before submit.
#[test]
fn select_unmarked_directory_quotes_paths_with_spaces() {
    let mut app = directories_test_app(&[("ls", "/Users/has spaces/project", 60)]);
    app.query = "#".to_string();
    app.refresh();
    // Select the
    // SQL-history row
    // explicitly.
    let sql_row_idx = app
        .merged_rows()
        .iter()
        .position(|r| r.directory == "/Users/has spaces/project")
        .expect("the SQL-history row for /Users/has spaces/project must be in merged_rows");
    app.list_state.select(Some(sql_row_idx));
    app.select_for_run();
    let staged = app.selection.as_deref().expect("selection must be set");
    assert!(
        staged.contains("-c '/Users/has spaces/project'"),
        "path with spaces must be quoted, got: {staged:?}"
    );
}

/// `~` in the directory is
/// expanded to `$HOME`
/// before staging. This
/// matters because tmux
/// does NOT do `~`
/// expansion itself —
/// `tmux new-session -c
/// '~/work'` silently
/// creates the session in
/// `$HOME`, not `~/work`,
/// which would be a
/// surprising correctness
/// bug. The TUI's staged
/// command always carries
/// the absolute path so
/// tmux gets the right
/// cwd.
///
/// We can't easily test this through `directories_test_app`
/// because the test inserts a home-prefixed absolute path into
/// the DB (not `~/...`), and the `~` shorthand only matches
/// paths that actually start with the home prefix. So the test
/// inserts a home-prefixed absolute path and asserts the staged
/// command has the `~`-shortened form — using a synthetic
/// `app.home_list` (set directly, not via `$HOME`) so the test
/// doesn't depend on, or risk touching, any real path on the
/// machine running it.
#[test]
fn select_unmarked_directory_expands_tilde() {
    let mut app = directories_test_app(&[("ls", "/home/testuser/work", 60)]);
    app.home_list = vec!["/home/testuser".to_string()];
    app.query = "#".to_string();
    app.refresh();
    // Select the
    // SQL-history row
    // explicitly (not
    // `merged_rows()[0]`).
    // The new
    // directory-source
    // feature surfaces
    // tmux panes as
    // rows too, so the
    // first row may be
    // one of the user's
    // real tmux panes,
    // not our test row.
    let sql_row_idx = app
        .merged_rows()
        .iter()
        .position(|r| r.directory == "/home/testuser/work")
        .expect("the SQL-history row for /home/testuser/work must be in merged_rows");
    app.list_state.select(Some(sql_row_idx));
    app.select_for_run();
    let staged = app.selection.as_deref().expect("selection must be set");
    // The directory in the staged `new-session -c` argument must
    // use `~/work`, not the raw `/home/testuser/work`, because the
    // source directory is under the (synthetic) home prefix and
    // the user expects the `~` form.
    //
    // Note: this test is *not* the same as the bug we're fixing
    // (which was about *literal* `~` in the source directory). The
    // DB-stored path is always absolute (per `fetch_directories`'s
    // `directory` column), so the expansion we test here is the
    // *display + command* shortening — a separate feature. The "no
    // literal `~` in the source path" contract is covered
    // implicitly: the source is always absolute, and the expansion
    // is a pure function of the home-prefix match.
    assert!(
        staged.contains("tmux new-session"),
        "staged must create a new tmux session, got: {staged:?}"
    );
    assert!(
        staged.contains("/home/testuser/work"),
        "staged must use the absolute path, got: {staged:?}"
    );
}

/// The user can pin a
/// `sessiondirs=...`
/// directory in the
/// config and every
/// subdirectory (recursively
/// walked) appears as a
/// row in the directories
/// list, even if no
/// command has ever been
/// run there. We test this
/// by injecting a
/// `session_subdirs` entry
/// directly into the
/// `App` (the test
/// doesn't have a config
/// file to load) and
/// checking the row
/// surfaces.
#[test]
fn fetch_directories_includes_sessiondir_subdirs() {
    // Build a temp
    // directory tree to
    // walk.
    let n = std::sync::atomic::AtomicU64::new(0).fetch_add(1, std::sync::atomic::Ordering::SeqCst);
    let pid = std::process::id();
    let root = std::env::temp_dir().join(format!("smarthistory_sessiondir_{pid}_{n}"));
    let _ = std::fs::remove_dir_all(&root);
    let _ = std::fs::create_dir_all(root.join("a").join("b"));
    let _ = std::fs::create_dir_all(root.join("c"));
    // sessiondir
    // subdirectory set
    // (the production
    // path uses
    // `build_session_subdirs`
    // at App
    // construction;
    // for the test we
    // pass it
    // explicitly via
    // the
    // `directories_test_app_with_sessions`
    // helper).
    let mut app = directories_test_app_with_sessions(
        &[],
        vec![root.join("a"), root.join("a").join("b"), root.join("c")],
    );
    app.query = "#".to_string();
    app.refresh();
    let rows = app.merged_rows();
    // The pinned
    // subdirs should
    // appear even
    // though we
    // passed `&[]` to
    // `directories_test_app`
    // (no history).
    let row_dirs: std::collections::HashSet<String> = rows
        .iter()
        .map(|r| {
            std::fs::canonicalize(&r.directory)
                .map(|p| p.to_string_lossy().into_owned())
                .unwrap_or_else(|_| r.directory.clone())
        })
        .collect();
    let expected: std::collections::HashSet<String> = app
        .session_subdirs
        .iter()
        .map(|p| {
            std::fs::canonicalize(p)
                .map(|c| c.to_string_lossy().into_owned())
                .unwrap_or_else(|_| p.to_string_lossy().into_owned())
        })
        .collect();
    for want in &expected {
        assert!(
            row_dirs.contains(want),
            "pinned subdir {want:?} should be in merged_rows, got: {row_dirs:?}"
        );
    }
    // The pinned
    // rows have
    // `timestamp = 0`
    // (so they sort
    // to the bottom
    // of the
    // newest-first
    // list) and an
    // empty `command`
    // — except for
    // `.command`
    // hints.
    for row in rows {
        let canonical = std::fs::canonicalize(&row.directory)
            .map(|p| p.to_string_lossy().into_owned())
            .unwrap_or_else(|_| row.directory.clone());
        if expected.contains(&canonical) {
            assert_eq!(
                row.timestamp, 0,
                "sessiondir row must have timestamp 0, got: {}",
                row.timestamp
            );
            assert_eq!(
                row.mode, "directory",
                "sessiondir row must have mode='directory'"
            );
        }
    }
    let _ = std::fs::remove_dir_all(&root);
}

/// When a sessiondir row
/// has a `.command` file
/// in itself or an
/// ancestor, the TUI
/// surfaces "(has
/// .command)" in the
/// secondary slot so
/// the user knows the
/// row will run a setup
/// script on select.
#[test]
fn fetch_directories_surfaces_command_file_hint() {
    // Build:
    //   tmpdir/
    //   tmpdir/project/         (has .command)
    //   tmpdir/project/src/     (no .command)
    let n = std::sync::atomic::AtomicU64::new(0).fetch_add(1, std::sync::atomic::Ordering::SeqCst);
    let pid = std::process::id();
    let root = std::env::temp_dir().join(format!("smarthistory_sessiondir_cmd_{pid}_{n}"));
    let _ = std::fs::remove_dir_all(&root);
    let project = root.join("project");
    let src = project.join("src");
    let _ = std::fs::create_dir_all(&src);
    let _ = std::fs::write(project.join(".command"), "#!/bin/sh\necho setup\n");
    // `project/src`
    // subdir is
    // pinned (the
    // walker would
    // also pick up
    // `project` if
    // the user pinned
    // `root`; we pin
    // a leaf to test
    // the ancestor
    // walk).
    let mut app = directories_test_app_with_sessions(&[], vec![src.clone()]);
    app.query = "#".to_string();
    app.refresh();
    let row = app
        .merged_rows()
        .iter()
        .find(|r| {
            std::fs::canonicalize(&r.directory)
                .map(|c| c == std::fs::canonicalize(&src).unwrap())
                .unwrap_or(false)
        })
        .expect("src row must be in the list");
    assert_eq!(
        row.comment, "(has .command)",
        "row's secondary slot should announce the .command, got: {:?}",
        row.comment
    );
    let _ = std::fs::remove_dir_all(&root);
}

/// When a sessiondir row
/// has a `.command` file
/// in itself or an
/// ancestor, selecting
/// the row chains
/// `sh <command-file> <dir>`
/// into the staged tmux
/// command. The first
/// argument is always
/// the selected
/// directory.
#[test]
fn select_directory_runs_command_file() {
    // Build:
    //   tmpdir/
    //   tmpdir/project/         (has .command)
    //   tmpdir/project/src/     (no .command)
    let n = std::sync::atomic::AtomicU64::new(0).fetch_add(1, std::sync::atomic::Ordering::SeqCst);
    let pid = std::process::id();
    let root = std::env::temp_dir().join(format!("smarthistory_select_cmd_{pid}_{n}"));
    let _ = std::fs::remove_dir_all(&root);
    let project = root.join("project");
    let src = project.join("src");
    let _ = std::fs::create_dir_all(&src);
    let cmd_path = project.join(".command");
    let _ = std::fs::write(&cmd_path, "#!/bin/sh\necho setup $1\n");
    let mut app = directories_test_app(&[("ls", &src.to_string_lossy(), 60)]);
    app.query = "#".to_string();
    app.refresh();
    // Find the SQL row
    // by its directory
    // (the user's real
    // tmux panes may
    // also be present
    // because
    // `refresh()` re-runs
    // the tmux fetch,
    // and the new
    // directory-source
    // feature surfaces
    // them as rows). We
    // explicitly select
    // the SQL row (not
    // `merged_rows()[0]`)
    // by setting
    // `list_state.selected`
    // to its index.
    let sql_row_idx = app
        .merged_rows()
        .iter()
        .position(|r| r.directory == src.to_string_lossy())
        .expect("the SQL-history row for `src` must be in merged_rows");
    app.list_state.select(Some(sql_row_idx));
    app.select_for_run();
    let staged = app.selection.as_deref().expect("selection must be set");
    // The staged
    // command must
    // include both the
    // new-session
    // chain and the
    // .command run.
    // Form:
    //   tmux new-session -d -s src -c <src>; \
    //     sh <.command> <src>; \
    //     tmux switch-client -t src
    let cmd_str = cmd_path.to_string_lossy();
    let src_str = src.to_string_lossy();
    assert!(
        staged.contains("tmux new-session"),
        "staged must create a new tmux session, got: {staged:?}"
    );
    assert!(
        staged.contains("switch-client"),
        "staged must switch-client to the new session, got: {staged:?}"
    );
    // The .command
    // invocation
    // should appear
    // with the path
    // and the
    // selected
    // directory as
    // the first arg.
    assert!(
        staged.contains(&format!("sh {} {}", cmd_str, src_str)),
        "staged must run `sh <.command> <dir>`, got: {staged:?}"
    );
    let _ = std::fs::remove_dir_all(&root);
}

/// Active tmux panes
/// (whose cwds are
/// distinct from the
/// SQL history) appear
/// as rows in the
/// directories list
/// with `source =
/// "tmux"`. The
/// visible primary
/// text is the
/// directory in
/// `~/x` form; the
/// secondary slot
/// shows `(pane %N)` so
/// the user can copy
/// the pane id for
/// `tmux send-keys -t
/// %N ...` directly
/// from the list.
#[test]
fn fetch_directories_includes_tmux_panes() {
    let mut app = directories_test_app(&[]);
    // Inject one tmux
    // window. Use `/tmp`
    // (a real directory
    // on every Unix) so
    // it passes the
    // `is_dir()` check.
    // macOS canonicalises
    // `/tmp` to
    // `/private/tmp`,
    // which is fine for
    // this test.
    app.tmux_windows.push(TmuxWindowInfo {
        pane_id: "%42".to_string(),
        path: String::from("/tmp"),
        ..Default::default()
    });
    app.query = "#".to_string();
    app.refresh();
    // Find the tmux
    // row. The
    // directory will be
    // canonicalised by
    // `std::fs::canonicalize`
    // (which on macOS
    // resolves
    // `/tmp` to
    // `/private/tmp`).
    let row = app
        .merged_rows()
        .iter()
        .find(|r| r.source == "tmux")
        .expect("the tmux pane row must be in merged_rows");
    // The visible primary
    // text is the
    // directory in
    // shell-shortened
    // form. `/tmp`
    // shortens to
    // `/tmp` (no home
    // to expand to).
    assert_eq!(
        row.command, "/tmp",
        "primary text must be the directory, got: {:?}",
        row.command
    );
    // The secondary slot
    // carries the pane
    // id (so the user
    // can reuse it).
    assert!(
        row.comment.contains("%42"),
        "secondary slot must show the pane id, got: {:?}",
        row.comment
    );
}

/// The
/// `DirectorySource::All`
/// mode shows every
/// row regardless of
/// source.
#[test]
fn directory_source_all_shows_everything() {
    // Use `/tmp` (a real
    // directory on every
    // Unix) for the SQL
    // and tmux rows so
    // they pass the
    // `is_dir()` check.
    // macOS canonicalises
    // `/tmp` to
    // `/private/tmp`,
    // which is fine for
    // the test.
    let sql_dir = "/tmp";
    let tmux_dir = "/tmp";
    let mut app = directories_test_app(&[("ls", sql_dir, 60)]);
    // Inject one
    // sessiondir
    // and one tmux
    // pane.
    let n = std::sync::atomic::AtomicU64::new(0).fetch_add(1, std::sync::atomic::Ordering::SeqCst);
    let pid = std::process::id();
    let session_root = std::env::temp_dir().join(format!("smarthistory_dirsrc_all_{pid}_{n}"));
    let _ = std::fs::create_dir_all(session_root.join("inside"));
    app.session_subdirs = vec![session_root.join("inside")];
    app.tmux_windows.push(TmuxWindowInfo {
        pane_id: "%7".to_string(),
        path: String::from(tmux_dir),
        ..Default::default()
    });
    // Default source is
    // `All`, so all
    // three rows are
    // visible.
    app.query = "#".to_string();
    app.refresh();
    let dirs: std::collections::HashSet<String> = app
        .merged_rows()
        .iter()
        .map(|r| r.directory.clone())
        .collect();
    assert!(
        dirs.contains(sql_dir),
        "SQL row must be visible, got: {:?}",
        dirs
    );
    assert!(
        dirs.contains(&session_root.join("inside").to_string_lossy().to_string()),
        "sessiondir row must be visible, got: {:?}",
        dirs
    );
    assert!(
        dirs.contains(tmux_dir),
        "tmux row must be visible, got: {:?}",
        dirs
    );
    let _ = std::fs::remove_dir_all(&session_root);
}

/// The
/// `DirectorySource::Config`
/// mode shows only the
/// `sessiondirs=...`
/// rows. SQL history
/// rows and tmux panes
/// are filtered out.
#[test]
fn directory_source_config_filters_to_sessiondirs() {
    let mut app = directories_test_app(&[("ls", "/Users/har/sql_row", 60)]);
    let n = std::sync::atomic::AtomicU64::new(0).fetch_add(1, std::sync::atomic::Ordering::SeqCst);
    let pid = std::process::id();
    let session_root = std::env::temp_dir().join(format!("smarthistory_dirsrc_cfg_{pid}_{n}"));
    let _ = std::fs::create_dir_all(session_root.join("inside"));
    app.session_subdirs = vec![session_root.join("inside")];
    app.tmux_windows.push(TmuxWindowInfo {
        pane_id: "%7".to_string(),
        path: String::from("/Users/har/tmux_row"),
        ..Default::default()
    });
    app.directory_source = crate::tui::state::DirectorySource::Config;
    app.query = "#".to_string();
    app.refresh();
    // Only the
    // sessiondir
    // row should be
    // visible.
    assert_eq!(
        app.merged_rows().len(),
        1,
        "Config mode must show only sessiondir rows, got: {:?}",
        app.merged_rows()
            .iter()
            .map(|r| (r.directory.clone(), r.source.clone()))
            .collect::<Vec<_>>()
    );
    let row = &app.merged_rows()[0];
    assert_eq!(row.source, "sessiondir");
    let _ = std::fs::remove_dir_all(&session_root);
}

/// The
/// `DirectorySource::Tmux`
/// mode shows only the
/// active tmux panes'
/// cwds. SQL history
/// rows and sessiondirs
/// rows are filtered
/// out.
#[test]
fn directory_source_tmux_filters_to_panes() {
    // The SQL and tmux
    // rows must use
    // *different* paths
    // (the dedup loop
    // suppresses tmux
    // rows whose canonical
    // path matches an
    // earlier SQL row).
    let n = std::sync::atomic::AtomicU64::new(0).fetch_add(1, std::sync::atomic::Ordering::SeqCst);
    let pid = std::process::id();
    let tmux_path = std::env::temp_dir().join(format!("smarthistory_tmux_pane_{pid}_{n}"));
    let _ = std::fs::create_dir_all(&tmux_path);
    let mut app = directories_test_app(&[("ls", "/tmp", 60)]);
    app.tmux_windows.push(TmuxWindowInfo {
        pane_id: "%7".to_string(),
        path: tmux_path.to_string_lossy().into_owned(),
        ..Default::default()
    });
    app.directory_source = crate::tui::state::DirectorySource::Tmux;
    app.query = "#".to_string();
    app.refresh();
    // Only the
    // tmux-pane
    // row should
    // be visible.
    assert_eq!(
        app.merged_rows().len(),
        1,
        "Tmux mode must show only tmux pane rows, got: {:?}",
        app.merged_rows()
            .iter()
            .map(|r| (r.directory.clone(), r.source.clone()))
            .collect::<Vec<_>>()
    );
    let row = &app.merged_rows()[0];
    assert_eq!(row.source, "tmux");
    let _ = std::fs::remove_dir_all(&tmux_path);
}

/// Regression test for the
/// bug where a tmux pane
/// whose path also appears
/// in the SQL history DB
/// was silently deduped
/// away in `DIR:TMUX`
/// mode. The shared `seen`
/// set was populated by the
/// SQL loop first, so the
/// tmux loop's `seen.insert`
/// returned `false` and the
/// pane was dropped — even
/// though the SQL row would
/// later be filtered out by
/// the source filter. The
/// fix: the source filter is
/// applied *early* (the SQL
/// loop is skipped entirely
/// in `DIR:TMUX` mode).
///
/// User symptom: 5 active
/// tmux panes, but
/// `DIR:TMUX` showed only
/// 2 (the ones not in the
/// history DB).
#[test]
fn directory_source_tmux_shows_pane_even_if_path_in_history() {
    // A real directory we
    // use for BOTH the SQL
    // row and the tmux pane.
    let n = std::sync::atomic::AtomicU64::new(0).fetch_add(1, std::sync::atomic::Ordering::SeqCst);
    let pid = std::process::id();
    let shared_path = std::env::temp_dir().join(format!("smarthistory_tmux_dup_{pid}_{n}"));
    let _ = std::fs::create_dir_all(&shared_path);
    let shared_str = shared_path.to_string_lossy().into_owned();
    // SQL history row in the
    // SAME directory.
    let mut app = directories_test_app(&[("ls", &shared_str, 60)]);
    // Tmux pane in the SAME
    // directory.
    app.tmux_windows.push(TmuxWindowInfo {
        pane_id: "%9".to_string(),
        path: shared_str.clone(),
        ..Default::default()
    });
    app.directory_source = crate::tui::state::DirectorySource::Tmux;
    app.query = "#".to_string();
    app.refresh();
    // In `DIR:TMUX` mode the
    // tmux pane MUST appear,
    // even though the SQL
    // row has the same
    // canonical path.
    let tmux_rows: Vec<_> = app
        .merged_rows()
        .iter()
        .filter(|r| r.source == "tmux")
        .collect();
    assert_eq!(
        tmux_rows.len(),
        1,
        "DIR:TMUX must show the tmux pane even when its path is in the history DB, got: {:?}",
        app.merged_rows()
            .iter()
            .map(|r| (r.directory.clone(), r.source.clone()))
            .collect::<Vec<_>>()
    );
    assert_eq!(tmux_rows[0].source, "tmux");
    // And no SQL rows leak
    // through.
    assert!(
        app.merged_rows().iter().all(|r| r.source == "tmux"),
        "DIR:TMUX must not show SQL rows, got: {:?}",
        app.merged_rows()
            .iter()
            .map(|r| r.source.clone())
            .collect::<Vec<_>>()
    );
    let _ = std::fs::remove_dir_all(&shared_path);
}

/// Regression test for the bug
/// where a labeled history
/// row (an entry with a
/// comment in the
/// `command_comments`
/// table) leaked into
/// `DIR:TMUX` directories
/// mode. The user ran
/// `tmux list-windows -a
/// -F ... | grep
/// "active:1"` at some
/// point and labeled it,
/// so the row had a
/// comment. `build_merged_rows`
/// appended *all* labeled
/// rows to the merged
/// list regardless of
/// mode; in directories
/// mode that meant the
/// history row showed up
/// alongside (or instead
/// of) the real tmux
/// pane rows. The fix:
/// `build_merged_rows`
/// skips the labeled/preview
/// merge entirely in
/// directories mode and
/// returns only the
/// directory rows.
#[test]
fn directory_source_tmux_excludes_labeled_history_rows() {
    let n = std::sync::atomic::AtomicU64::new(0).fetch_add(1, std::sync::atomic::Ordering::SeqCst);
    let pid = std::process::id();
    let tmux_path = std::env::temp_dir().join(format!("smarthistory_tmux_labeled_{pid}_{n}"));
    let _ = std::fs::create_dir_all(&tmux_path);
    // The labeled command —
    // the exact "tmux list-
    // windows ..." line the
    // user reported. It was
    // run from /tmp.
    let labeled_cmd = "tmux list-windows -a -F #{pane_id}";
    let mut app = directories_test_app(&[(labeled_cmd, "/tmp", 60)]);
    // Create the
    // command_comments table
    // and label the command,
    // making it a "labeled
    // row" that
    // `fetch_labeled` will
    // return.
    app.conn
        .execute(
            "CREATE TABLE command_comments (
                        command TEXT PRIMARY KEY,
                        comment TEXT NOT NULL
                    )",
            [],
        )
        .expect("create command_comments");
    // `fetch_labeled` does a LEFT JOIN on
    // `history_output`; the table must exist or
    // the query errors (and `.unwrap_or_default()`
    // silently yields an empty labeled set —
    // which would mask the bug in this test).
    app.conn
        .execute(
            "CREATE TABLE history_output (
                        history_id INTEGER PRIMARY KEY,
                        output TEXT NOT NULL
                    )",
            [],
        )
        .expect("create history_output");
    app.conn
        .execute(
            "INSERT INTO command_comments (command, comment) VALUES (?1, ?2)",
            rusqlite::params![labeled_cmd, "TMUX LIST"],
        )
        .expect("insert comment");
    // One real tmux pane with a
    // different path.
    app.tmux_windows.push(TmuxWindowInfo {
        pane_id: "%5".to_string(),
        path: tmux_path.to_string_lossy().into_owned(),
        ..Default::default()
    });
    app.directory_source = crate::tui::state::DirectorySource::Tmux;
    app.query = "#".to_string();
    app.refresh();
    // The labeled history
    // row (`tmux list-
    // windows ...`) must
    // NOT appear in
    // `DIR:TMUX` mode.
    let has_labeled = app.merged_rows().iter().any(|r| r.command == labeled_cmd);
    assert!(
        !has_labeled,
        "DIR:TMUX must not show labeled history rows, got: {:?}",
        app.merged_rows()
            .iter()
            .map(|r| (r.command.clone(), r.source.clone()))
            .collect::<Vec<_>>()
    );
    // Only the real tmux
    // pane should be
    // visible.
    assert_eq!(app.merged_rows().len(), 1);
    assert_eq!(app.merged_rows()[0].source, "tmux");
    let _ = std::fs::remove_dir_all(&tmux_path);
}

/// `cycle_directory_source`
/// pressed while NOT in
/// directories mode should
/// switch INTO directories
/// mode (prepending the `#`
/// prefix) AND cycle the
/// source. The user can be
/// in plain history and
/// land directly in `DIR:TMUX`.
#[test]
fn cycle_directory_source_enters_dirs_mode_from_plain() {
    let mut app = directories_test_app(&[("ls", "/tmp", 60)]);
    // Plain mode, no prefix.
    app.query = String::from("ls");
    assert!(!app.is_directories_query());
    // Cycle from plain -> DIR:TMUX.
    app.cycle_directory_source();
    // Now in directories mode.
    assert!(
        app.is_directories_query(),
        "must enter directories mode, got query {:?}",
        app.query
    );
    // Source cycled to TMUX.
    assert_eq!(
        app.directory_source,
        crate::tui::state::DirectorySource::Tmux
    );
    // Body preserved: `#ls`.
    assert_eq!(app.query, "#ls");
}

/// Cycling three times from
/// plain mode lands back on
/// `DIR:ALL`, still in
/// directories mode.
#[test]
fn cycle_directory_source_three_times_wraps_to_all() {
    let mut app = directories_test_app(&[("ls", "/tmp", 60)]);
    app.query = String::new();
    app.cycle_directory_source(); // -> TMUX
    assert!(app.is_directories_query());
    assert_eq!(
        app.directory_source,
        crate::tui::state::DirectorySource::Tmux
    );
    app.cycle_directory_source(); // -> CFG
    assert!(app.is_directories_query());
    assert_eq!(
        app.directory_source,
        crate::tui::state::DirectorySource::Config
    );
    app.cycle_directory_source(); // -> ALL
    assert!(app.is_directories_query());
    assert_eq!(
        app.directory_source,
        crate::tui::state::DirectorySource::All
    );
    // Query is just `#` (empty body).
    assert_eq!(app.query, "#");
}

/// Regression test: `App::refresh()`'s SQL-fetch cache short-circuit
/// must invalidate when `directory_source` changes, even if the
/// query text is untouched. `directory_source` is read inside
/// `directories::fetch`, which only runs on a cache miss — if it's
/// missing from the cache key, cycling the source (e.g. pressing the
/// directory-source key twice in a row without editing the query)
/// leaves `self.rows` — and therefore what's on screen — pinned to
/// whatever the *previous* source produced.
#[test]
fn cycle_directory_source_actually_refetches_rows() {
    let n = std::sync::atomic::AtomicU64::new(0).fetch_add(1, std::sync::atomic::Ordering::SeqCst);
    let pid = std::process::id();
    let tmux_path = std::env::temp_dir().join(format!("smarthistory_cache_key_{pid}_{n}"));
    let _ = std::fs::create_dir_all(&tmux_path);
    // SQL row and tmux row use different paths so both are visible
    // (and not deduped against each other) in `All` mode.
    let mut app = directories_test_app(&[("ls", "/tmp", 60)]);
    app.tmux_windows.push(TmuxWindowInfo {
        pane_id: "%7".to_string(),
        path: tmux_path.to_string_lossy().into_owned(),
        ..Default::default()
    });
    app.directory_source = crate::tui::state::DirectorySource::All;
    app.query = "#".to_string();
    app.refresh();
    assert_eq!(
        app.merged_rows().len(),
        2,
        "All mode must show both the SQL and tmux rows, got: {:?}",
        app.merged_rows()
            .iter()
            .map(|r| (r.directory.clone(), r.source.clone()))
            .collect::<Vec<_>>()
    );

    // Switch to Tmux-only WITHOUT touching the query text — this is
    // exactly the state transition the broken cache key missed.
    app.directory_source = crate::tui::state::DirectorySource::Tmux;
    app.refresh();
    assert_eq!(
        app.merged_rows().len(),
        1,
        "Tmux mode must re-fetch and show only the tmux row, got: {:?}",
        app.merged_rows()
            .iter()
            .map(|r| (r.directory.clone(), r.source.clone()))
            .collect::<Vec<_>>()
    );
    assert_eq!(app.merged_rows()[0].source, "tmux");
    let _ = std::fs::remove_dir_all(&tmux_path);
}

/// Switching from a search
/// mode (`?foo`) strips the
/// fuzzy prefix and yields
/// `#foo` (not `#?foo`).
#[test]
fn cycle_directory_source_strips_search_prefix() {
    let mut app = directories_test_app(&[("ls", "/home", 60)]);
    app.query = "#git".to_string();
    app.refresh();
    // The body after the `#` prefix should be "git".
    let body = app.directories_pattern();
    assert_eq!(body, "git");
}

/// When ALREADY in directories
/// mode, cycle just advances the
/// source — the query prefix is
/// not doubled.
#[test]
fn cycle_directory_source_in_dirs_mode_does_not_double_prefix() {
    let mut app = directories_test_app(&[("ls", "/tmp", 60)]);
    app.query = String::from("#");
    app.cycle_directory_source();
    assert_eq!(app.query, "#");
    assert!(app.is_directories_query());
    assert_eq!(
        app.directory_source,
        crate::tui::state::DirectorySource::Tmux
    );
}

/// Build an App pre-loaded with a set of session
/// panes (bypassing the real `tmux list-panes -s`
/// subprocess, which depends on a live tmux
/// server). Each tuple is
/// (pane_id, window_id, cwd, current_command).
/// The caller still owns `app.session_panes` and can
/// mutate it after construction. `TMUX_PANE` is NOT
/// set (so the exclusion filter is exercised
/// explicitly by the caller via the injected rows).
fn panes_test_app(panes: &[(&str, &str, &str, &str)]) -> App {
    let mut app = directories_test_app(&[]);
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    let home_list = app.home_list.clone();
    let mut next_id: i64 = -1;
    app.session_panes = panes
        .iter()
        .map(|(pane_id, window_id, cwd, cmd)| {
            let full = crate::util::canonicalize_directory(cwd);
            let short = crate::util::shorten_home_path(&full, &home_list).into_owned();
            let id = next_id;
            next_id -= 1;
            // The fourth tuple slot
            // doubles as the
            // `current_command` /
            // `pane_agent` — the
            // production helper
            // `refresh_session_panes_impl`
            // sets both to the same
            // value (the agent name
            // from
            // `CurrentPaneInfo`),
            // and the test helper
            // mirrors that
            // invariant so the
            // dedup test below
            // sees the same
            // initial state.
            HistoryRow {
                id,
                command: cmd.to_string(),
                directory: full,
                session_id: pane_id.to_string(),
                exit_code: 0,
                timestamp: now,
                comment: short,
                // window id (`@N`) stashed
                // for the cross-window
                // select-window jump.
                output: window_id.to_string(),
                mode: "pane".to_string(),
                source: "pane".to_string(),
                pane_agent: cmd.to_string(),

                ..Default::default()
            }
        })
        .collect();
    app
}

/// The background cmdline patch in
/// `App::process_pane_cmdlines` used to
/// concatenate `agent` + `cmdline` on every
/// tick, re-reading the just-patched
/// `row.command` as the new "agent" each
/// time. So a herdr pane running `ssh
/// user@host` ended up showing `ssh
/// user@host ssh user@host ssh user@host
/// ...` after a few seconds. The fix was
/// to add a separate `pane_agent` field
/// on `HistoryRow` and have the patch
/// read the original agent from there.
///
/// These tests exercise the dedup logic
/// directly via the extracted
/// `App::patch_pane_cmdline` helper. The
/// background-thread + channel + snapshot
/// machinery is hard to set up in a
/// test, but the dedup itself is a
/// 4-line pure function over two strings
/// and a row, so the unit tests cover
/// the regression at the right level of
/// abstraction.
#[test]
fn patch_pane_cmdline_appends_agent_only_once() {
    // Single pane running `ssh`. The
    // herdr thread will report a fresh
    // `ssh user@host` cmdline on every
    // poll; the patch should write
    // `ssh user@host` once and not
    // concatenate on subsequent ticks.
    let mut app = panes_test_app(&[("%1", "@1", "/tmp", "ssh")]);
    // Tick 1: herdr reports
    // `ssh user@host`.
    app.patch_pane_cmdline("%1", "ssh user@host");
    let row = &app.session_panes[0];
    assert_eq!(row.command, "ssh user@host");
    assert_eq!(row.pane_agent, "ssh");
    // Tick 2: same cmdline again.
    // The original bug would have
    // produced `ssh user@host ssh
    // user@host` here.
    app.patch_pane_cmdline("%1", "ssh user@host");
    let row = &app.session_panes[0];
    assert_eq!(
        row.command, "ssh user@host",
        "second patch must not concatenate; the agent is read from pane_agent, not from the just-patched command"
    );
    // Tick 3: cmdline still the
    // same. Repeat the assertion to
    // be sure the patch is fully
    // idempotent.
    app.patch_pane_cmdline("%1", "ssh user@host");
    let row = &app.session_panes[0];
    assert_eq!(row.command, "ssh user@host");
    assert_eq!(row.pane_agent, "ssh");
}

#[test]
fn patch_pane_cmdline_dedups_when_agent_matches_argv0() {
    // The dedup shortcut: when the
    // agent name matches the cmdline's
    // first token, the patch must show
    // only the cmdline (no `pi pi
    // ...`). This is the case the
    // user hits most often — `pi`,
    // `claude`, `vim`, etc. all spawn
    // a child process with the same
    // argv0, so the herdr
    // `process-info` command comes
    // back with the same first token.
    let mut app = panes_test_app(&[("%1", "@1", "/tmp", "pi")]);
    app.patch_pane_cmdline("%1", "pi --model foo --prompt bar");
    let row = &app.session_panes[0];
    assert_eq!(
        row.command, "pi --model foo --prompt bar",
        "agent == cmd_first must not double the agent"
    );
    // Same again on a second tick.
    app.patch_pane_cmdline("%1", "pi --model foo --prompt bar");
    let row = &app.session_panes[0];
    assert_eq!(row.command, "pi --model foo --prompt bar");
    // Now the cmdline changes
    // (e.g. the user re-runs with a
    // different flag) — the patch
    // must pick up the new cmdline
    // cleanly, no leftover from the
    // previous tick.
    app.patch_pane_cmdline("%1", "pi --model baz");
    let row = &app.session_panes[0];
    assert_eq!(row.command, "pi --model baz");
}

#[test]
fn patch_pane_cmdline_joins_when_agent_differs_from_argv0() {
    // The non-dedup case: agent
    // (`pi`) is a parent process,
    // but the cmdline's first token
    // (`ssh`) is a child that
    // doesn't match. The display
    // should be `pi ssh ...` so the
    // user sees both the agent and
    // the foreground command.
    let mut app = panes_test_app(&[("%1", "@1", "/tmp", "pi")]);
    app.patch_pane_cmdline("%1", "ssh user@host -p 2222");
    let row = &app.session_panes[0];
    assert_eq!(row.command, "pi ssh user@host -p 2222");
    // And critically: a second
    // tick with the same cmdline
    // must NOT become `pi ssh ... pi
    // ssh ...` — that's the bug
    // being regression-tested.
    app.patch_pane_cmdline("%1", "ssh user@host -p 2222");
    let row = &app.session_panes[0];
    assert_eq!(
        row.command, "pi ssh user@host -p 2222",
        "non-dedup path must also be idempotent across ticks"
    );
    // Cmdline changes (user ran a
    // different child).
    app.patch_pane_cmdline("%1", "vim /etc/hosts");
    let row = &app.session_panes[0];
    assert_eq!(row.command, "pi vim /etc/hosts");
}

#[test]
fn patch_pane_cmdline_handles_empty_agent() {
    // A pane row with no agent
    // (`pane_agent == ""`) is
    // unusual but legal (e.g. the
    // initial fetch ran before
    // `current_command` was
    // populated, or the user
    // constructed a synthetic
    // pane row in a test). The
    // patch must just show the
    // cmdline alone, no leading
    // space, no ` agent` prefix.
    let mut app = panes_test_app(&[("%1", "@1", "/tmp", "")]);
    app.patch_pane_cmdline("%1", "vim /etc/hosts");
    let row = &app.session_panes[0];
    assert_eq!(row.command, "vim /etc/hosts");
    // And the empty-agent case
    // must also be idempotent.
    app.patch_pane_cmdline("%1", "vim /etc/hosts");
    let row = &app.session_panes[0];
    assert_eq!(row.command, "vim /etc/hosts");
}

#[test]
fn patch_pane_cmdline_no_op_for_unknown_pane() {
    // The patch must silently do
    // nothing if the `pane_id` from
    // the herdr thread doesn't
    // match any row in
    // `session_panes`. This
    // happens when the snapshot
    // has been superseded between
    // the thread spawn and the
    // patch (the snapshot-id
    // check in
    // `process_pane_cmdlines`
    // should already have caught
    // it, but belt-and-suspenders
    // here).
    let mut app = panes_test_app(&[("%1", "@1", "/tmp", "ssh")]);
    let before = app.session_panes[0].command.clone();
    app.patch_pane_cmdline("%99", "vim /etc/hosts");
    assert_eq!(app.session_panes[0].command, before);
    assert_eq!(app.session_panes.len(), 1);
}

/// Minimal herdr-named fake, only for exercising
/// `spawn_pane_cmdlines`'s lazy-spawn gate in
/// `process_pane_cmdlines` — every method but `name()`
/// is unreachable from that path (it never calls the
/// backend; it only reads `app.session_panes` and spawns
/// a background thread that shells out to the real
/// `herdr` binary via a free function, not this trait).
struct NamedHerdrBackend;
impl crate::multiplexer::MultiplexerBackend for NamedHerdrBackend {
    fn snapshot(&self) -> Vec<crate::multiplexer::ActiveContext> {
        Vec::new()
    }
    fn snapshot_current_panes(&self, _current_pane: &str) -> Vec<crate::multiplexer::CurrentPaneInfo> {
        Vec::new()
    }
    fn focus_command(&self, _pane_id: &str) -> Option<String> {
        None
    }
    fn focus_session(&self, _session_label: &str) -> Option<String> {
        None
    }
    fn focus_pane(&self, _pane_id: &str, _tab_id: &str) -> Option<String> {
        None
    }
    fn create_command(&self, _dir: &std::path::Path, _label: &str) -> Option<String> {
        None
    }
    fn send_in_pane_command(&self, _pane_id: &str, _body: &str) -> Option<String> {
        None
    }
    fn read_pane(&self, _pane_id: &str, _lines: usize) -> Option<String> {
        None
    }
    fn name(&self) -> &'static str {
        "herdr"
    }
}

/// Regression test for the "panes mode is very sensitive to slow
/// terminals" bug: `process_pane_cmdlines`'s lazy spawn used to
/// check only `pane_cmdlines_request.is_none()`, which is ALSO true
/// immediately after a lookup finishes (the channel disconnects and
/// clears the request back to `None`). That respawned a full
/// per-pane subprocess round on the very next ~100ms run-loop tick,
/// forever — a tight loop of process lookups with no actual change
/// to wait for. The fix adds `pane_cmdlines_spawned_for_snapshot`:
/// once a lookup has been attempted for a given `panes_snapshot_id`,
/// it isn't attempted again until the snapshot itself changes.
#[test]
fn process_pane_cmdlines_does_not_respawn_after_completing_for_the_same_snapshot() {
    let mut app = panes_test_app(&[("%1", "@1", "/tmp", "ssh")]);
    app.multiplexer = Box::new(NamedHerdrBackend);
    app.query = "*".to_string();

    // Simulate exactly the state `process_pane_cmdlines` itself
    // leaves behind when a background lookup finishes for the
    // current snapshot: the request is gone, but the "spawned for
    // this snapshot" marker is still set.
    app.pane_cmdlines_spawned_for_snapshot = Some(app.panes_snapshot_id);
    app.pane_cmdlines_request = None;

    app.process_pane_cmdlines();

    assert!(
        app.pane_cmdlines_request.is_none(),
        "must not respawn a lookup for a snapshot it has already \
         completed one for — that's the tight-loop bug this guards against"
    );

    // A genuinely NEW snapshot (the panes list actually changed)
    // must still trigger exactly one fresh spawn.
    app.panes_snapshot_id = app.panes_snapshot_id.wrapping_add(1);
    app.process_pane_cmdlines();
    assert!(
        app.pane_cmdlines_request.is_some(),
        "a real snapshot change must still spawn a fresh lookup"
    );
    assert_eq!(
        app.pane_cmdlines_spawned_for_snapshot,
        Some(app.panes_snapshot_id)
    );
}

/// `*` prefix switches the query into panes mode,
/// and `is_panes_query()` / `panes_pattern()` slice
/// the body correctly.
#[test]
fn panes_prefix_detected_and_pattern_sliced() {
    let mut app = directories_test_app(&[]);
    app.query = String::new();
    assert!(!app.is_panes_query());
    app.query = String::from("*");
    assert!(app.is_panes_query());
    assert_eq!(app.panes_pattern(), "");
    app.query = String::from("*vim src");
    assert!(app.is_panes_query());
    assert_eq!(app.panes_pattern(), "vim src");
}

/// `fetch_panes` returns the cached session panes
/// (no substring filter when the body is empty).
#[test]
fn fetch_panes_returns_all_when_no_filter() {
    let mut app = panes_test_app(&[("%1", "@1", "/tmp", "zsh"), ("%2", "@2", "/tmp", "vim")]);
    app.query = String::from("*");
    let rows = crate::tui::mode::panes::fetch(&mut app).unwrap();
    assert_eq!(rows.len(), 2);
    assert_eq!(rows[0].source, "pane");
    assert_eq!(rows[0].session_id, "%1");
    assert_eq!(rows[0].command, "zsh");
}

/// The substring filter matches against the pane's
/// current command OR its cwd (short form). Both
/// whitespace tokens must match (AND semantics).
#[test]
fn fetch_panes_substring_filter_matches_command_or_cwd() {
    let mut app = panes_test_app(&[("%1", "@1", "/tmp", "zsh"), ("%2", "@2", "/tmp", "vim")]);
    // `*vim` → only the pane running vim.
    app.query = String::from("*vim");
    let rows = crate::tui::mode::panes::fetch(&mut app).unwrap();
    assert_eq!(rows.len(), 1);
    assert_eq!(rows[0].session_id, "%2");
    assert_eq!(rows[0].command, "vim");
}

// --- Sessions group header (`insert_sessions_group_header`) ----
//
// Live tmux/herdr workspaces get a common synthetic `# Sessions`
// header wrapping all of them (one level higher than each
// individual `## <workspace>` sub-header), matching the
// `Directories`/`hosts` sections' own `# `-headed look:
//
//   # Sessions
//   ## Smarthistory
//       zsh
//   ## Home
//       zsh

/// A `Sessions` header (`mode == "workspace"`, `source ==
/// "workspace-group"`) is inserted directly above the first live
/// workspace row whenever at least one is present.
#[test]
fn fetch_panes_inserts_sessions_group_header_when_live_workspace_present() {
    use crate::tui::state::HistoryRow;
    let mut app = panes_test_app(&[]);
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    app.session_panes = vec![
        HistoryRow {
            id: -1,
            command: "Smarthistory".to_string(),
            session_id: "Smarthistory".to_string(),
            timestamp: now,
            mode: "workspace".to_string(),
            source: "workspace".to_string(),
            ..Default::default()
        },
        HistoryRow {
            id: -2,
            command: String::new(),
            session_id: "%1".to_string(),
            timestamp: now,
            mode: "pane".to_string(),
            source: "pane".to_string(),
            workspace_label: "Smarthistory".to_string(),
            ..Default::default()
        },
    ];
    app.query = "*".to_string();
    let rows = crate::tui::mode::panes::fetch(&mut app).unwrap();
    assert_eq!(rows.len(), 3, "Sessions header + workspace + pane");
    assert_eq!(rows[0].mode, "workspace");
    assert_eq!(rows[0].command, "Sessions");
    assert_eq!(rows[0].source, "workspace-group");
    // The header itself doesn't focus anything on selection —
    // `session_id` empty is the existing no-op contract
    // `stage_pane_selection`'s `mode == "workspace"` arm already
    // uses (`if label.is_empty() { return; }`).
    assert_eq!(rows[0].session_id, "");
    assert_eq!(rows[1].mode, "workspace");
    assert_eq!(rows[1].command, "Smarthistory");
    assert_eq!(rows[2].mode, "pane");
}

/// No `Sessions` header when there's no live workspace — e.g. only
/// the configured `Directories`/`hosts` sections are present. Same
/// "only appears when it has content" contract those sections
/// already follow.
#[test]
fn fetch_panes_omits_sessions_group_header_with_no_live_workspace() {
    use crate::tui::state::HistoryRow;
    let mut app = panes_test_app(&[]);
    app.sessions = vec![HistoryRow {
        id: -1,
        command: "Home".to_string(),
        directory: "/home/har".to_string(),
        ..Default::default()
    }];
    app.query = "*".to_string();
    let rows = crate::tui::mode::panes::fetch(&mut app).unwrap();
    assert!(
        !rows.iter().any(|r| r.source == "workspace-group"),
        "no live workspace rows, so no Sessions header should appear; got: {:?}",
        rows.iter().map(|r| (&r.mode, &r.command)).collect::<Vec<_>>()
    );
    assert!(
        rows.iter().any(|r| r.command == "Directories"),
        "the Directories header must still be present"
    );
}

/// Selecting the `Sessions` header row (`Enter`) is a clean no-op —
