#[test]
fn help_shows_user_configured_prefixes() {
    let mut app = help_app();
    // Rebind the regex
    // prefix from `/` to
    // `#`. The `prefix.regex=...`
    // config key is
    // parsed by
    // `Config::assign_prefix`;
    // here we set the field
    // directly (which is
    // what the config
    // loader does after
    // parsing).
    app.query_prefixes.directories = '#';
    let lines = build_help_lines(&app);
    let _texts: Vec<String> = lines
        .iter()
        .map(|l| {
            l.spans
                .iter()
                .map(|s| s.content.as_ref())
                .collect::<String>()
        })
        .collect();
    // The regex row should
    // now show `#` as
    // the prefix. The
    // format helper pads
    // the prefix with a
    // leading space, so
    // the row contains
    // ` # `.
    // The regex row should
    // now show `#` as
    // the prefix. The
    // format helper pads
    // the prefix with a
    // leading space, so
    // the row contains
    // ` # `.
    // (regex/fuzzy prefixes removed — now match-algorithm toggles)
}

// ===== Prefix Picker Tests =====

#[test]
fn apply_prefix_sets_prefix_and_preserves_body() {
    let mut app = global_test_app(&[("git status", 1)]);
    app.query = "git status".to_string();
    app.apply_prefix(Some('#'));
    assert_eq!(
        app.query, "#git status",
        "expected # prefix with body preserved"
    );
    assert_eq!(app.query_cursor, 11);
    assert!(app.query_touched);
}

#[test]
fn apply_prefix_none_strips_current_prefix() {
    let mut app = global_test_app(&[("src", 1)]);
    app.query = "#src".to_string();
    app.apply_prefix(None);
    assert_eq!(app.query, "src", "expected prefix stripped");
}

#[test]
fn apply_prefix_jira_then_output_cycles_ok() {
    let mut app = global_test_app(&[("todo", 1)]);
    app.query = "-todo".to_string();
    assert_eq!(app.query, "-todo");
    app.apply_prefix(Some('+'));
    assert_eq!(app.query, "+todo");
    app.apply_prefix(None);
    assert_eq!(app.query, "todo");
}

/// `query_mode_char` must recognise EVERY configured prefix
/// char — it feeds both `maybe_prefix_selection_with_space`
/// (the space-prefix privacy convention) and the per-mode
/// query-history "did the mode change" checks. A prefix char
/// missing from its lookup array would silently fall back to
/// `MODE_NONE`, wrongly treating that mode's queries as plain
/// history. Covers `:` (segments) explicitly since it's new;
/// the other 11 configured prefixes are exercised via
/// `maybe_prefix_selection_with_space_skips_in_history_mode`.
#[test]
fn query_mode_char_recognises_segments_prefix() {
    let prefixes = crate::QueryPrefixes::default();
    assert_eq!(query_mode_char(":symbol", &prefixes), ':');
    assert_eq!(query_mode_char("plain text", &prefixes), MODE_NONE);
}

/// `apply_prefix`'s `has_prefix` check must recognise EVERY
/// configured prefix char, not just a subset — a mode missing
/// from that check would have its leading char treated as part
/// of the body instead of stripped, leaving a stray character
/// behind when cycling prefixes. Covers `:` (segments, the mode
/// added in this change) and `&` (codegraph, which turned out to
/// be missing from this same check already — an unrelated
/// pre-existing gap fixed alongside segments since it's the
/// exact same bug shape).
#[test]
fn apply_prefix_strips_segments_and_codegraph_prefixes() {
    let mut app = global_test_app(&[("sym", 1)]);
    app.query = ":sym".to_string();
    app.apply_prefix(None);
    assert_eq!(app.query, "sym", "expected ':' prefix stripped");

    app.query = "&sym".to_string();
    app.apply_prefix(None);
    assert_eq!(app.query, "sym", "expected '&' prefix stripped");
}

// ===== Quick nav-prefix cycle (Ctrl-Z) =====

/// `Ctrl-Z` cycles panes → directories → zoxide → panes, wrapping
/// around, and preserves the typed body across each hop (same
/// `apply_prefix` semantics `PickPrefix` itself uses).
#[test]
fn cycle_nav_prefix_cycles_panes_directories_zoxide_and_wraps() {
    let mut app = global_test_app(&[("thing", 1)]);
    let p = app.query_prefixes.clone();

    app.query = format!("{}thing", p.panes);
    app.cycle_nav_prefix();
    assert_eq!(app.query, format!("{}thing", p.directories));

    app.cycle_nav_prefix();
    assert_eq!(app.query, format!("{}thing", p.zoxide));

    app.cycle_nav_prefix();
    assert_eq!(
        app.query,
        format!("{}thing", p.panes),
        "must wrap back around to panes"
    );
}

/// Pressing `Ctrl-Z` from any mode OTHER than the three nav
/// prefixes (plain history, another prefix mode, or an empty
/// query) jumps straight to panes — the first of the three —
/// rather than no-op-ing or erroring.
#[test]
fn cycle_nav_prefix_from_unrelated_mode_jumps_to_panes() {
    let mut app = global_test_app(&[("thing", 1)]);
    let p = app.query_prefixes.clone();

    app.query = String::new();
    app.cycle_nav_prefix();
    assert_eq!(app.query, p.panes.to_string());

    app.query = format!("{}jql", p.jira);
    app.cycle_nav_prefix();
    assert_eq!(app.query, format!("{}jql", p.panes));

    app.query = "plain history text".to_string();
    app.cycle_nav_prefix();
    assert_eq!(app.query, format!("{}plain history text", p.panes));
}

/// `Ctrl-Z` is the documented default binding for `CycleNavPrefix`,
/// and it must actually dispatch to `cycle_nav_prefix` (not just be
/// registered in the default-key table with nothing wired up).
#[test]
fn ctrl_z_dispatches_cycle_nav_prefix() {
    let mut app = global_test_app(&[("thing", 1)]);
    let p = app.query_prefixes.clone();
    app.query = format!("{}thing", p.panes);
    handle_key(
        &mut app,
        crossterm::event::KeyEvent::new(
            crossterm::event::KeyCode::Char('z'),
            crossterm::event::KeyModifiers::CONTROL,
        ),
    );
    assert_eq!(app.query, format!("{}thing", p.directories));
}

