// ---------------------------------------------------------------------------
// Output preview scroll hint
// ---------------------------------------------------------------------------
//
// Windowed source-context modes
// (`:`, `$`, `&`, `,`) load
// `SOURCE_CONTEXT_LINES` (50)
// lines of context centered on
// the matched line. The matched
// line sits at position
// `SOURCE_CONTEXT_LINES / 2` (=
// 25) in the loaded buffer. The
// output preview pane is
// typically only 10–20 lines
// tall, so without a scroll
// hint the matched line is below
// the fold and the user has to
// scroll the preview pane
// manually to find the line they
// searched for.
//
// The fix: each mode's
// `ensure_selected_context` sets
// `row.preview_scroll = half -
// 2` (= 23) when the context is
// loaded. The renderer reads
// this and applies it via
// `Paragraph::scroll((y, 0))`,
// so the matched line lands at
// row 2 of the visible area (top
// of the pane with a couple of
// leading context lines for
// orientation).
//
// The renderer's `min(max_scroll,
// scroll)` clamp handles short
// files / near-end matches
// where the loaded buffer is
// shorter than the scroll offset.

#[test]
fn segments_preview_scroll_hint_centers_segment_line() {
    // The post-load
    // state: a
    // `mode = "segment"`
    // row with a 50-line
    // context window.
    // `preview_scroll`
    // should be set to
    // `SOURCE_CONTEXT_LINES / 2 - 2`
    // = 23 by
    // `segments::ensure_selected_context`.
    use crate::tui::SOURCE_CONTEXT_LINES;
    let half = SOURCE_CONTEXT_LINES / 2;
    let expected_scroll = half.saturating_sub(2) as u16;
    // The
    // `ensure_selected_context`
    // path requires a
    // real file on
    // disk to load
    // the source
    // context. We use
    // a temp file
    // with enough
    // lines to
    // populate the
    // full 50-line
    // window.
    let dir = std::env::temp_dir().join(format!(
        "smarthistory_segments_scroll_test_{}",
        std::process::id()
    ));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).expect("create dir");
    let file_path = dir.join("note.md");
    // Build a 100-line
    // file where the
    // 50-line window
    // centered on the
    // matched line
    // (line 50) is the
    // full 50 lines.
    let mut content = String::new();
    for i in 1..=100 {
        content.push_str(&format!("line {}\n", i));
    }
    std::fs::write(&file_path, &content).expect("write file");
    // Find the line
    // that the
    // `note_search`
    // segment index
    // will land on.
    // We use a query
    // that matches a
    // segment on
    // line 50.
    let mut app = directories_test_app(&[]);
    app.notes_dir = Some(dir.clone());
    app.notes_database = Some(dir.join("nonexistent-segments.sql"));
    // Inject a
    // synthetic
    // segment row
    // pointing at
    // line 50.
    app.segments_state.rows = vec![crate::tui::state::HistoryRow {
        id: -1,
        command: "test-segment".to_string(),
        directory: file_path.to_string_lossy().to_string(),
        session_id: "50".to_string(), // 1-based line number
        exit_code: 0,
        timestamp: 0,
        comment: "note.md".to_string(),
        output: String::new(),
        mode: "segment".to_string(),
        source: String::new(),
        ..Default::default()
    }];
    app.segments_state.last_pattern = Some(String::new());
    app.query = ":".to_string();
    app.refresh();
    // After
    // `refresh()`,
    // `ensure_selected_context`
    // has run for
    // the selected
    // segment row.
    // The row's
    // `output` should
    // contain the
    // source
    // context, and
    // `preview_scroll`
    // should be set
    // to the
    // load-bearing
    // `half - 2`
    // value that
    // tells the
    // renderer to
    // scroll so the
    // segment line
    // is at row 2 of
    // the preview
    // pane.
    let row = &app.merged_rows[app.list_state.selected().unwrap()];
    assert_eq!(
        row.preview_scroll, expected_scroll,
        "preview_scroll must equal SOURCE_CONTEXT_LINES / 2 - 2 = {} \
         so the segment line is visible at row 2 of the preview pane",
        expected_scroll
    );
    // Sanity: the
    // loaded
    // context
    // contains
    // the
    // matched
    // line.
    assert!(
        row.output.contains("line 50"),
        "the loaded context must contain the matched line; got output=\n{}",
        row.output
    );
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
fn preview_scroll_zero_for_history_rows() {
    // History rows
    // don't have a
    // windowed context,
    // so `preview_scroll`
    // defaults to 0
    // (the renderer's
    // "no scroll hint"
    // sentinel). This
    // test verifies the
    // default in a
    // freshly-constructed
    // row.
    use crate::tui::state::HistoryRow;
    let row = HistoryRow::default();
    assert_eq!(row.preview_scroll, 0);
    assert_eq!(row.preview, "");
}

#[test]
fn preview_scroll_clamps_at_max_scroll_for_short_buffers() {
    // When the loaded
    // preview is shorter
    // than the requested
    // scroll offset, the
    // renderer's
    // `min(max_scroll,
    // scroll)` clamp
    // brings it back to
    // 0 (or the largest
    // valid offset). This
    // test verifies the
    // arithmetic the
    // renderer uses.
    fn clamped_scroll(requested: u16, total_lines: usize, visible_height: usize) -> u16 {
        let max_scroll = total_lines.saturating_sub(visible_height);
        (requested as usize).min(max_scroll) as u16
    }
    // Full 50-line
    // window, smaller
    // preview height:
    // the requested
    // `23` is honoured
    // because the
    // window is tall
    // enough that the
    // clamped max is
    // >= 23.
    assert_eq!(clamped_scroll(23, 50, 15), 23);
    // Larger preview
    // height (30): the
    // clamped max is
    // 50 - 30 = 20, so
    // the scroll is
    // capped at 20
    // (the segment
    // line is still
    // visible at
    // position 25 - 20
    // = 5, near the
    // top of the
    // visible area).
    assert_eq!(clamped_scroll(23, 50, 30), 20);
    // Tiny preview
    // height: still
    // honoured (the
    // window is
    // tall enough).
    assert_eq!(clamped_scroll(23, 50, 5), 23);
    // Short buffer
    // (10 lines) with a
    // normal preview
    // height: the
    // scroll is
    // clamped to 0
    // because the
    // window fits
    // entirely in
    // view.
    assert_eq!(clamped_scroll(23, 10, 15), 0);
    // Short buffer,
    // larger preview:
    // same clamp.
    assert_eq!(clamped_scroll(23, 8, 30), 0);
    // Edge: total
    // == visible
    // (no scroll
    // possible).
    assert_eq!(clamped_scroll(23, 15, 15), 0);
}

// ---------------------------------------------------------------------------
// `create-note` dialog (Title + Content composer)
// ---------------------------------------------------------------------------

/// `extract_links_and_tags` is
/// the load-bearing helper for
/// the `create-note` submit
/// path: it pulls structured
/// metadata out of the
/// free-form Title + Content
/// so the heading line gets
/// the right `[[links]]` and
/// `#tags` without the user
/// having to retype them in
/// the heading itself.
#[test]
fn extract_links_and_tags_pulls_bracketed_links_and_hash_tags() {
    use crate::tui::state::extract_links_and_tags;
    let (links, tags) = extract_links_and_tags(
        "see [[Note A]] and [[Note B]] and [[Note A]] again; \
         tagged #feature and #bug and #feature again",
    );
    // First-seen
    // order, deduped.
    assert_eq!(
        links,
        vec!["[[Note A]]".to_string(), "[[Note B]]".to_string()],
        "links are deduped but preserve first-seen order; the [[...]] wrapper is preserved verbatim"
    );
    // Tags
    // are
    // stripped
    // of
    // the
    // leading
    // `#`
    // (the
    // heading
    // builder
    // re-adds
    // it).
    assert_eq!(
        tags,
        vec!["feature".to_string(), "bug".to_string()],
        "tags are deduped, stripped of the leading `#`, and in first-seen order"
    );
}

#[test]
fn extract_links_and_tags_ignores_hash_inside_words() {
    // The `c#` substring
    // (e.g. in "use c#lang")
    // is NOT a tag — only
    // `#` at a word boundary
    // (start of text, or
    // preceded by whitespace /
    // punctuation) counts.
    use crate::tui::state::extract_links_and_tags;
    let (links, tags) =
        extract_links_and_tags("use c#lang for the #feature; don't tag this # but yes #feature");
    assert!(links.is_empty(), "no `[[...]]` spans in the input");
    // `#` immediately
    // followed by
    // whitespace
    // (the
    // `# but`
    // token) is
    // also
    // dropped:
    // the tag
    // body is
    // empty.
    assert_eq!(
        tags,
        vec!["feature".to_string()],
        "embedded `#` inside words is not a tag; empty tags are dropped"
    );
}

#[test]
fn extract_links_and_tags_handles_unicode_tags_and_links() {
    use crate::tui::state::extract_links_and_tags;
    let (links, tags) =
        extract_links_and_tags("see [[Über uns]] and [[Café au lait]]; tag #naïve and #α-β");
    assert_eq!(
        links,
        vec!["[[Über uns]]".to_string(), "[[Café au lait]]".to_string()],
        "multi-byte UTF-8 link contents are preserved"
    );
    // The
    // tag-body
    // alphabet
    // is
    // `alphanumeric`
    // +
    // `_`
    // +
    // `-`.
    // Greek
    // letters
    // count
    // as
    // alphanumeric;
    // the
    // dash
    // is
    // part
    // of
    // the
    // tag.
    assert_eq!(
        tags,
        vec!["naïve".to_string(), "α-β".to_string()],
        "tag-body alphabet accepts alphanumeric + `_` + `-` (including non-ASCII letters)"
    );
}

/// `build_note_body` is the pure body-builder shared by the TUI's
/// interactive dialog and `smarthistory create-note`'s direct CLI
/// path — covered directly here so both callers are exercised by one
/// set of cases instead of only indirectly through dialog-state tests.
#[test]
fn build_note_body_combines_title_and_content_into_heading() {
    use crate::tui::state::build_note_body;
    let body = build_note_body("Meeting notes", "Discussed the roadmap").unwrap();
    assert!(body.starts_with("### Meeting notes\n[time:: "), "got: {body:?}");
    assert!(body.ends_with("\nDiscussed the roadmap"), "got: {body:?}");
}

#[test]
fn build_note_body_pulls_links_and_tags_from_content_into_heading() {
    use crate::tui::state::build_note_body;
    let body = build_note_body("Standup", "Blocked on [[Project X]] #urgent").unwrap();
    let heading_line = body.lines().next().unwrap();
    assert_eq!(
        heading_line, "### Standup [[Project X]] #urgent",
        "links/tags found only in content are appended to the heading, not duplicated in it twice"
    );
}

#[test]
fn build_note_body_returns_none_when_both_fields_empty() {
    use crate::tui::state::build_note_body;
    assert_eq!(build_note_body("", ""), None);
    assert_eq!(build_note_body("   ", "\n\t"), None, "whitespace-only fields count as empty");
}

#[test]
fn build_note_body_allows_title_only_or_content_only() {
    use crate::tui::state::build_note_body;
    assert!(build_note_body("Just a title", "").is_some());
    assert!(build_note_body("", "Just content").is_some());
}

#[test]
fn note_create_dialog_opens_and_field_toggles() {
    // The dialog opens,
    // defaults to the Title
    // field, and `Tab`
    // toggles between Title
    // and Content.
    let mut app = directories_test_app(&[]);
    assert!(!app.is_note_create_open());
    app.open_note_create_dialog();
    assert!(app.is_note_create_open());
    {
        let d = app.note_create.as_ref().unwrap();
        assert_eq!(d.active_field, crate::tui::state::NoteCreateField::Title);
        assert!(d.title.is_empty());
        assert!(d.content.is_empty());
    }
    app.note_create_toggle_field();
    {
        let d = app.note_create.as_ref().unwrap();
        assert_eq!(d.active_field, crate::tui::state::NoteCreateField::Content);
    }
    app.note_create_toggle_field();
    {
        let d = app.note_create.as_ref().unwrap();
        assert_eq!(d.active_field, crate::tui::state::NoteCreateField::Title);
    }
    app.note_create_cancel();
    assert!(!app.is_note_create_open());
}

/// `Esc` on an EMPTY create-note dialog closes it immediately —
/// there's nothing worth confirming, so no confirmation overlay
/// appears (this is the pre-existing behavior; the new confirmation
/// only applies when a field has text — see the `dirty` variant
/// below).
#[test]
fn note_create_esc_on_empty_dialog_closes_immediately() {
    let mut app = directories_test_app(&[]);
    app.open_note_create_dialog();
    crate::tui::handle_note_create_key(&mut app, KeyEvent::new(KeyCode::Esc, KeyModifiers::empty()));
    assert!(!app.is_note_create_open());
}

/// `Esc` on a dialog with unsaved text (Title and/or Content
/// non-empty) does NOT close the dialog — it opens the "save or
/// drop?" confirmation overlay instead, leaving the typed text
/// intact underneath.
#[test]
fn note_create_esc_on_dirty_dialog_opens_confirm_discard() {
    let mut app = directories_test_app(&[]);
    app.open_note_create_dialog();
    for c in "my title".chars() {
        app.note_create_push_char(c);
    }
    crate::tui::handle_note_create_key(&mut app, KeyEvent::new(KeyCode::Esc, KeyModifiers::empty()));
    let d = app.note_create.as_ref().expect("dialog stays open");
    assert!(d.confirm_discard, "confirmation overlay must open");
    assert_eq!(d.title, "my title", "typed text must be preserved");
}

/// `Ctrl-C` mirrors `Esc`: empty dialog exits the TUI immediately
/// (pre-existing behavior — `Ctrl-C` is the universal abort key);
/// dirty dialog opens the confirmation instead of exiting.
#[test]
fn note_create_ctrl_c_dirty_opens_confirm_discard_instead_of_exiting() {
    let mut app = directories_test_app(&[]);
    app.open_note_create_dialog();
    for c in "draft".chars() {
        app.note_create_push_char(c);
    }
    let exited = crate::tui::handle_note_create_key(
        &mut app,
        KeyEvent::new(KeyCode::Char('c'), KeyModifiers::CONTROL),
    );
    assert!(!exited, "dirty dialog must not exit the TUI on first Ctrl-C");
    assert!(!app.cancelled);
    let d = app.note_create.as_ref().expect("dialog stays open");
    assert!(d.confirm_discard);
}

#[test]
fn note_create_ctrl_c_on_empty_dialog_exits_tui() {
    let mut app = directories_test_app(&[]);
    app.open_note_create_dialog();
    let exited = crate::tui::handle_note_create_key(
        &mut app,
        KeyEvent::new(KeyCode::Char('c'), KeyModifiers::CONTROL),
    );
    assert!(exited);
    assert!(app.cancelled);
    assert!(!app.is_note_create_open());
}

/// Inside the confirm-discard overlay, `Enter` is the default action
/// and saves — same staging `Ctrl-S` produces in the main dialog.
#[test]
fn note_create_confirm_discard_enter_saves_by_default() {
    let mut app = directories_test_app(&[]);
    app.notes_database = Some(std::path::PathBuf::from("/tmp"));
    app.notes_dir = Some(std::path::PathBuf::from("/tmp"));
    app.open_note_create_dialog();
    for c in "keep me".chars() {
        app.note_create_push_char(c);
    }
    app.note_create.as_mut().unwrap().confirm_discard = true;
    let committed = crate::tui::handle_note_create_confirm_key(
        &mut app,
        KeyEvent::new(KeyCode::Enter, KeyModifiers::empty()),
    );
    assert!(committed, "Enter must save and close the dialog");
    assert!(!app.is_note_create_open());
    assert!(
        app.selection.as_deref().unwrap_or("").contains("keep me"),
        "the saved body must be staged"
    );
}

/// `d`/`D` in the confirm-discard overlay drops the note.
#[test]
fn note_create_confirm_discard_d_drops_the_note() {
    for key_code in [KeyCode::Char('d'), KeyCode::Char('D')] {
        let mut app = directories_test_app(&[]);
        app.open_note_create_dialog();
        for c in "throwaway".chars() {
            app.note_create_push_char(c);
        }
        app.note_create.as_mut().unwrap().confirm_discard = true;
        let committed = crate::tui::handle_note_create_confirm_key(
            &mut app,
            KeyEvent::new(key_code, KeyModifiers::empty()),
        );
        assert!(!committed);
        assert!(!app.is_note_create_open(), "the note must be dropped");
    }
}

/// The Cancel binding (default `Esc`) in the confirm-discard overlay
/// is the SAFE choice: it backs out of the confirmation WITHOUT
/// discarding anything, leaving the dialog open with the typed text
/// intact — consistent with every other confirmation in the TUI
/// (Cancel never performs the destructive action).
#[test]
fn note_create_confirm_discard_cancel_key_backs_out_to_editing() {
    let mut app = directories_test_app(&[]);
    app.open_note_create_dialog();
    for c in "still drafting".chars() {
        app.note_create_push_char(c);
    }
    app.note_create.as_mut().unwrap().confirm_discard = true;
    let committed = crate::tui::handle_note_create_confirm_key(
        &mut app,
        KeyEvent::new(KeyCode::Esc, KeyModifiers::empty()),
    );
    assert!(!committed);
    let d = app.note_create.as_ref().expect("dialog stays open, nothing lost");
    assert!(!d.confirm_discard, "confirmation overlay closes");
    assert_eq!(d.title, "still drafting");
}

/// `Ctrl-C` in the confirm-discard overlay is the panic button: it
/// force-quits the whole TUI immediately without saving, bypassing
/// the confirmation — same semantics as `handle_confirm_delete_key`'s
/// `Ctrl-C`.
#[test]
fn note_create_confirm_discard_ctrl_c_force_quits() {
    let mut app = directories_test_app(&[]);
    app.open_note_create_dialog();
    for c in "urgent exit".chars() {
        app.note_create_push_char(c);
    }
    app.note_create.as_mut().unwrap().confirm_discard = true;
    let exited = crate::tui::handle_note_create_confirm_key(
        &mut app,
        KeyEvent::new(KeyCode::Char('c'), KeyModifiers::CONTROL),
    );
    assert!(exited);
    assert!(app.cancelled);
}

/// A stray keypress inside the confirm-discard overlay (neither
/// `Enter`, `d`/`D`, Cancel, nor `Ctrl-C`) is ignored — the
/// confirmation stays open and nothing is lost or saved.
#[test]
fn note_create_confirm_discard_ignores_unrelated_keys() {
    let mut app = directories_test_app(&[]);
    app.open_note_create_dialog();
    for c in "careful".chars() {
        app.note_create_push_char(c);
    }
    app.note_create.as_mut().unwrap().confirm_discard = true;
    let committed = crate::tui::handle_note_create_confirm_key(
        &mut app,
        KeyEvent::new(KeyCode::Char('x'), KeyModifiers::empty()),
    );
    assert!(!committed);
    let d = app.note_create.as_ref().expect("dialog stays open");
    assert!(d.confirm_discard, "confirmation overlay stays open");
    assert_eq!(d.title, "careful", "nothing was saved or dropped");
}

