    // Title field is
    // silently dropped
    // (the user has to
    // `Tab` to Content for
    // newlines).
    let mut app = directories_test_app(&[]);
    app.open_note_create_dialog();
    app.note_create_push_char('h');
    app.note_create_push_char('i');
