/// Any key other than `Ctrl-C`/`Backspace` clears an active
/// selection instead of leaving it stuck — typing a character both
/// deselects AND inserts normally (at the existing cursor position;
/// this dialog doesn't implement "typing replaces the selection").
#[test]
fn note_create_select_all_cleared_by_unrelated_key() {
    let mut app = directories_test_app(&[]);
    app.open_note_create_dialog();
    for c in "Hi".chars() {
        app.note_create_push_char(c);
    }
    app.note_create.as_mut().unwrap().select_all = true;
    crate::tui::handle_note_create_key(
        &mut app,
        KeyEvent::new(KeyCode::Char('!'), KeyModifiers::empty()),
    );
    let d = app.note_create.as_ref().unwrap();
    assert!(!d.select_all, "an unrelated key must clear the selection");
    assert_eq!(d.title, "Hi!", "the key still does its normal thing");
}

/// `select_all` must be visually obvious, not just an internal
/// flag: the active field's border title gains a "SELECTED" marker
/// and its text renders in reverse video (the same convention the
/// completion menu's highlighted candidate uses). Renders through
/// the real `crate::tui::render::ui` entry point against a
/// `TestBackend` and inspects the actual buffer, the same technique
/// `draw_list_shows_correct_rows_when_scrolled_in_a_long_history_list`
/// uses, so this exercises the real widget tree rather than a
/// hand-rolled approximation of it.
#[test]
fn draw_note_create_shows_selected_indicator_when_ctrl_a_active() {
    let mut app = directories_test_app(&[]);
    app.open_note_create_dialog();
    for c in "Standup".chars() {
        app.note_create_push_char(c);
    }
    let backend = ratatui::backend::TestBackend::new(80, 30);
    let mut terminal = ratatui::Terminal::new(backend).expect("terminal");

    terminal
        .draw(|f| crate::tui::render::ui(f, &mut app))
        .expect("draw");
    let text_before = terminal
        .backend()
        .buffer()
        .content
        .iter()
        .map(|c| c.symbol())
        .collect::<String>();
    assert!(
        !text_before.contains("SELECTED"),
        "no selection indicator before Ctrl-A"
    );

    app.note_create.as_mut().unwrap().select_all = true;
    terminal
        .draw(|f| crate::tui::render::ui(f, &mut app))
        .expect("draw");
    let buffer = terminal.backend().buffer();
    let text_after = buffer.content.iter().map(|c| c.symbol()).collect::<String>();
    assert!(
        text_after.contains("SELECTED"),
        "selection indicator must appear once Ctrl-A is active, got: {text_after:?}"
    );
    let has_reversed_cell = buffer
        .content
        .iter()
        .any(|c| c.modifier.contains(ratatui::style::Modifier::REVERSED));
    assert!(
        has_reversed_cell,
        "the selected field's text must render in reverse video"
    );
}

/// `Up`/`Down` deliberately do NOT cross between Title and Content —
/// they stay within whichever field is active, same as `Left`/`Right`.
/// `Up` in Title is a no-op (Title is always one line); `Up` on
/// Content's first line stays in Content rather than jumping to
/// Title. `Tab` is the only way to switch fields.
///
/// Title = "Hi" (2 chars), Content = "AB\nC" (line 0 = "AB", line 1
/// = "C"), chosen small so every cursor position below can be
/// checked by hand.
#[test]
fn note_create_move_up_down_stay_within_active_field() {
    let mut app = directories_test_app(&[]);
    app.open_note_create_dialog();
    for c in "Hi".chars() {
        app.note_create_push_char(c);
    }
    // `Up`/`Down` in Title are no-ops: Title has only one line.
    app.note_create_move_up();
    app.note_create_move_down();
    {
        let d = app.note_create.as_ref().unwrap();
        assert_eq!(d.active_field, crate::tui::state::NoteCreateField::Title);
        assert_eq!(d.title_cursor, 2);
    }
    app.note_create_toggle_field();
    for c in "AB\nC".chars() {
        app.note_create_push_char(c);
    }
    // Cursor is at the end: line 1 ("C"), column 1.
    app.note_create_move_up();
    // Line 1 -> line 0, column min(1, len("AB")=2) = 1: right after
    // "A". Stays in Content.
    {
        let d = app.note_create.as_ref().unwrap();
        assert_eq!(d.active_field, crate::tui::state::NoteCreateField::Content);
        assert_eq!(d.content_cursor, 1);
    }
    // `Up` again: already on Content's first line (line 0) — no-op,
    // does NOT cross into Title.
    app.note_create_move_up();
    {
        let d = app.note_create.as_ref().unwrap();
        assert_eq!(d.active_field, crate::tui::state::NoteCreateField::Content);
        assert_eq!(d.content_cursor, 1);
    }
}

/// `Down` on Content's last line is a no-op — there's no field
/// after Content to cross into.
#[test]
fn note_create_move_down_on_last_content_line_is_noop() {
    let mut app = directories_test_app(&[]);
    app.open_note_create_dialog();
    app.note_create_toggle_field();
    for c in "only one line".chars() {
        app.note_create_push_char(c);
    }
    let before = app.note_create.as_ref().unwrap().content_cursor;
    app.note_create_move_down();
    assert_eq!(app.note_create.as_ref().unwrap().content_cursor, before);
    assert_eq!(
        app.note_create.as_ref().unwrap().active_field,
        crate::tui::state::NoteCreateField::Content
    );
}

