fn strip_note_frontmatter_empty_body_yields_empty_string() {
    let content = "---\ntype: #project\n---\n";
    assert_eq!(strip_note_frontmatter(content), "");
}

/// `Up`/`Down` move the cursor a line at a time through Description
/// (the one multi-line field), preserving column — same behavior
/// `NoteCreateDialog`'s Content field already has, added so a
/// pre-filled multi-paragraph Description (from a note or a JIRA
/// issue) is actually navigable, not just append-only at whatever
/// the cursor happened to be left at.
#[test]
fn create_jira_issue_dialog_description_up_down_move_by_line() {
    let mut app = directories_test_app(&[]);
    app.create_jira_issue_dialog = Some(test_create_jira_issue_dialog(
        "Subject",
        "AB\nC",
        "",
        None,
    ));
    if let Some(d) = app.create_jira_issue_dialog.as_mut() {
        d.focused = crate::tui::state::CreateJiraIssueFocus::Description;
        // Cursor at the end: line 1 ("C"), column 1.
        d.fields[1].cursor = d.fields[1].value.chars().count();
    }
    let up = KeyEvent::new(KeyCode::Up, KeyModifiers::empty());
    handle_key(&mut app, up);
    // Line 1 -> line 0, column min(1, len("AB")=2) = 1: right after "A".
    assert_eq!(
        app.create_jira_issue_dialog.as_ref().unwrap().fields[1].cursor,
        1
    );
    // `Up` again: already on line 0 — no-op.
    handle_key(&mut app, up);
    assert_eq!(
        app.create_jira_issue_dialog.as_ref().unwrap().fields[1].cursor,
        1
    );
    let down = KeyEvent::new(KeyCode::Down, KeyModifiers::empty());
    handle_key(&mut app, down);
    // Back to line 1, column 1 (clamped to "C"'s length of 1) — char
    // index 3 (start of "C") + 1 = 4, i.e. right after "C".
    assert_eq!(
        app.create_jira_issue_dialog.as_ref().unwrap().fields[1].cursor,
        4
    );
}

/// `Up`/`Down` are a no-op when a field OTHER than Description is
/// focused — they don't apply to the single-line fields or the
/// Project/Issue Type selectors.
#[test]
fn create_jira_issue_dialog_up_down_noop_outside_description() {
    let mut app = directories_test_app(&[]);
    app.create_jira_issue_dialog = Some(test_create_jira_issue_dialog(
        "Subject text",
        "AB\nC",
        "",
        None,
    ));
    if let Some(d) = app.create_jira_issue_dialog.as_mut() {
        d.focused = crate::tui::state::CreateJiraIssueFocus::Subject;
        d.fields[0].cursor = 3;
    }
    let up = KeyEvent::new(KeyCode::Up, KeyModifiers::empty());
    handle_key(&mut app, up);
    let dialog = app.create_jira_issue_dialog.as_ref().unwrap();
    assert_eq!(dialog.fields[0].cursor, 3, "Subject cursor should be untouched");
    assert_eq!(
        dialog.focused,
        crate::tui::state::CreateJiraIssueFocus::Subject
    );
}

/// The Description field renders an actual reversed-video cursor
/// glyph on the character it sits on, at the correct row within a
/// multi-line body — not just an auto-scroll to the right line.
/// Since `dialog_field_line` only ever reverses the cursor of the
/// FOCUSED field, and no other field is focused here, this is the
/// only source of a reversed cell in the whole dialog: a clean signal
/// this is exercising the new cursor-glyph code, not some other
/// field's own cursor.
#[test]
fn create_jira_issue_dialog_description_renders_cursor_glyph_at_correct_position() {
    let mut app = directories_test_app(&[]);
    let content = "Line one\nLine two";
    app.create_jira_issue_dialog = Some(test_create_jira_issue_dialog(
        "Subject",
        content,
        "",
        None,
    ));
    if let Some(d) = app.create_jira_issue_dialog.as_mut() {
        d.focused = crate::tui::state::CreateJiraIssueFocus::Description;
        // Land the cursor exactly on the 'w' of "two" (second line).
        d.fields[1].cursor = content.chars().position(|c| c == 'w').unwrap();
    }

    let backend = ratatui::backend::TestBackend::new(120, 40);
    let mut terminal = ratatui::Terminal::new(backend).expect("terminal");
    terminal
        .draw(|f| crate::tui::render::ui(f, &mut app))
        .expect("draw");
    let buffer = terminal.backend().buffer();

    let reversed_cells: Vec<&str> = buffer
        .content
        .iter()
        .filter(|c| c.modifier.contains(ratatui::style::Modifier::REVERSED))
        .map(|c| c.symbol())
        .collect();
    assert_eq!(
        reversed_cells,
        vec!["w"],
        "exactly one reversed cell, on the 'w' the cursor sits on: {reversed_cells:?}"
    );
}

/// A `ClonedCustomField` extra field renders a dim "(cloned)" marker
/// next to its value, so the UI explains why typing into it does
/// nothing; a template's own editable `CustomField` extra field does
/// NOT get this marker.
#[test]
fn create_jira_issue_dialog_renders_cloned_marker_only_on_cloned_fields() {
    let mut app = directories_test_app(&[]);
    let mut dialog = test_create_jira_issue_dialog("Subject", "", "", None);
    dialog.extra_fields = vec![
        crate::tui::state::DialogField::prefilled(
            "customfield_11601",
            "",
            false,
            "",
            "Team ComS".to_string(),
        ),
        crate::tui::state::DialogField::prefilled("assigne", "", false, "", "HAR".to_string()),
    ];
    dialog.extra_field_kinds = vec![
        crate::tui::state::ExtraFieldKind::ClonedCustomField("customfield_11601".to_string()),
        crate::tui::state::ExtraFieldKind::Parameter,
    ];
    app.create_jira_issue_dialog = Some(dialog);

    let backend = ratatui::backend::TestBackend::new(120, 40);
    let mut terminal = ratatui::Terminal::new(backend).expect("terminal");
    terminal
        .draw(|f| crate::tui::render::ui(f, &mut app))
        .expect("draw");
    let buffer = terminal.backend().buffer();
    let text = buffer.content.iter().map(|c| c.symbol()).collect::<String>();

    assert!(
        text.contains("Team ComS") && text.contains("(cloned)"),
        "cloned field must render its value and a (cloned) marker: {text:?}"
    );
    assert!(
        text.contains("HAR"),
        "the Parameter field's own value must still render: {text:?}"
    );
    assert_eq!(
        text.matches("(cloned)").count(),
        1,
        "only the ClonedCustomField gets the marker, not the Parameter field: {text:?}"
    );
}

// ---- "Create JIRA issue from template" (`Action::CreateJiraIssueFromTemplate`) ----

/// `parse_jira_template` against the real example already on disk at
/// `~/.config/smarthistory/templates/jira/standard.md` — frontmatter
/// pairs come back in declaration order with the right scalar/list
/// shapes, and the body is the frontmatter-stripped remainder.
#[test]
fn parse_jira_template_parses_real_example() {
    use crate::tui::mode::jira::FrontmatterValue;

    let content = "---\nproject: ENG\nlabels:\n- project\n- test\ncf[11601]: \"Team ComS\"\nupdated: 2026-08-20 18:49:51\nsummary: SUMMARY\nassigne: \"HAR\"\n---\nDescription Content\n";
    let (pairs, body) = crate::tui::mode::jira::parse_jira_template(content);

    assert_eq!(
        pairs,
        vec![
            ("project".to_string(), FrontmatterValue::Scalar("ENG".to_string())),
            (
                "labels".to_string(),
                FrontmatterValue::List(vec!["project".to_string(), "test".to_string()])
            ),
            ("cf[11601]".to_string(), FrontmatterValue::Scalar("Team ComS".to_string())),
            (
                "updated".to_string(),
                FrontmatterValue::Scalar("2026-08-20 18:49:51".to_string())
            ),
            ("summary".to_string(), FrontmatterValue::Scalar("SUMMARY".to_string())),
            ("assigne".to_string(), FrontmatterValue::Scalar("HAR".to_string())),
        ]
    );
    assert_eq!(body, "Description Content");
}

/// Content with no leading `---` line has zero fields — the whole file
/// is the body, same "degrade gracefully" fallback `strip_note_frontmatter`
/// uses.
#[test]
fn parse_jira_template_no_frontmatter_returns_whole_file_as_body() {
    let content = "# Just a template\n\nNo frontmatter here.";
    let (pairs, body) = crate::tui::mode::jira::parse_jira_template(content);
    assert!(pairs.is_empty());
    assert_eq!(body, content);
}

/// A `---` that never closes falls back to the whole file as the body
/// with zero fields, rather than losing content.
#[test]
fn parse_jira_template_unclosed_frontmatter_falls_back_to_whole_file() {
    let content = "---\nproject: ENG\n# never closes";
    let (pairs, body) = crate::tui::mode::jira::parse_jira_template(content);
    assert!(pairs.is_empty());
    assert_eq!(body, content);
}

/// `classify_template_key` buckets every key the real example (and the
/// design doc) calls out: reserved metadata, the 4 standard-field
/// names, a `cf[<digits>]` custom field, and the generic-parameter
/// fallback.
#[test]
fn classify_template_key_buckets() {
    use crate::tui::mode::jira::TemplateFieldKind;

    assert_eq!(crate::tui::mode::jira::classify_template_key("created"), TemplateFieldKind::Reserved);
    assert_eq!(crate::tui::mode::jira::classify_template_key("updated"), TemplateFieldKind::Reserved);
    assert_eq!(
        crate::tui::mode::jira::classify_template_key("project"),
        TemplateFieldKind::StandardProject
    );
    assert_eq!(
        crate::tui::mode::jira::classify_template_key("issuetype"),
        TemplateFieldKind::StandardIssueType
    );
    assert_eq!(
        crate::tui::mode::jira::classify_template_key("summary"),
        TemplateFieldKind::StandardSummary
    );
    assert_eq!(
        crate::tui::mode::jira::classify_template_key("labels"),
        TemplateFieldKind::StandardLabels
    );
    assert_eq!(
        crate::tui::mode::jira::classify_template_key("cf[11601]"),
        TemplateFieldKind::CustomField("customfield_11601".to_string())
    );
    assert_eq!(
        crate::tui::mode::jira::classify_template_key("assigne"),
        TemplateFieldKind::Parameter
    );
    // Not a valid cf[] — non-digit inside the brackets — falls through
    // to a generic parameter rather than being treated as a custom field.
    assert_eq!(
        crate::tui::mode::jira::classify_template_key("cf[abc]"),
        TemplateFieldKind::Parameter
    );
}

/// `jira_dialog_row_prefill` returns the template-provided defaults
/// unchanged when nothing is selected — the "cold open" / "non-note/jira
/// row" fallback case.
#[test]
fn jira_dialog_row_prefill_uses_defaults_when_nothing_selected() {
    let mut app = directories_test_app(&[]);
    let (subject, description, labels, source_key, prefill_loading) = app.jira_dialog_row_prefill(
        "Template Subject".to_string(),
        "Template body".to_string(),
        "template, labels".to_string(),
    );
    assert_eq!(subject, "Template Subject");
    assert_eq!(description, "Template body");
    assert_eq!(labels, "template, labels");
    assert_eq!(source_key, None);
    assert!(!prefill_loading);
}

/// A selected note row's own content wins over the template's defaults
/// for Subject/Description/Labels — the confirmed precedence rule.
#[test]
fn jira_dialog_row_prefill_note_row_wins_over_template_defaults() {
    let dir = std::env::temp_dir().join(format!(
        "smarthistory-jira-template-test-{}",
        std::process::id()
    ));
    std::fs::create_dir_all(&dir).expect("create temp notes dir");
    std::fs::write(dir.join("my-note.md"), "Real note body").expect("write note file");

    let mut app = directories_test_app(&[]);
    app.notes_dir = Some(dir.clone());
    app.merged_rows.insert(
        0,
        crate::tui::state::HistoryRow {
            id: 1,
            command: "my-note.md".to_string(),
            mode: "note".to_string(),
            ..Default::default()
        },
    );
    app.list_state.select(Some(0));

    let (subject, description, labels, source_key, prefill_loading) = app.jira_dialog_row_prefill(
        "Template Subject".to_string(),
        "Template body".to_string(),
        "template, labels".to_string(),
    );
    assert_eq!(subject, "my-note", "row's filename wins over the template default");
    assert_eq!(description, "Real note body", "row's content wins over the template body");
    assert_eq!(source_key, None);
    assert!(!prefill_loading);
    // Labels comes from the note's own #tags (none here), NOT the
    // template's "template, labels" default — row prefill wins even
    // though it resolves to empty.
    assert_eq!(labels, "");

    std::fs::remove_dir_all(&dir).ok();
}

/// Submitting with a mix of `CustomField`/`Parameter` extra fields:
/// non-empty `CustomField` values are sent to `create_issue` as real
/// custom fields; non-empty `Parameter` values are folded into
/// Description as a prepended block, in field order, above the
/// original Description text.
#[test]
fn create_jira_issue_dialog_submit_with_template_extra_fields() {
    use std::sync::Arc;
    let fake = FakeJira {
        created_issue_key: "PROJ-42".to_string(),
        ..FakeJira::default()
    };
    let created = fake.created_issues.clone();
    let created_custom_fields = fake.created_issue_custom_fields.clone();
    let mut app = directories_test_app(&[]);
    app.set_jira_client(Arc::new(fake));
    let mut dialog = test_create_jira_issue_dialog("New bug", "Original description", "", None);
    dialog.extra_fields = vec![
        crate::tui::state::DialogField::prefilled("cf[11601]", "", false, "", "Team ComS".to_string()),
        crate::tui::state::DialogField::prefilled("assigne", "", false, "", "HAR".to_string()),
        crate::tui::state::DialogField::prefilled("empty-param", "", false, "", "".to_string()),
    ];
    dialog.extra_field_kinds = vec![
        crate::tui::state::ExtraFieldKind::CustomField("customfield_11601".to_string()),
        crate::tui::state::ExtraFieldKind::Parameter,
        crate::tui::state::ExtraFieldKind::Parameter,
    ];
    app.create_jira_issue_dialog = Some(dialog);
    app.create_jira_issue_dialog_submit();

    let calls = created.lock().unwrap();
    assert_eq!(calls.len(), 1);
    let (_, _, _, description, _) = &calls[0];
    assert_eq!(
        description, "**assigne:** HAR\n\nOriginal description",
        "the empty parameter is skipped; the non-empty one is prepended above the original description"
    );

    let custom_fields = created_custom_fields.lock().unwrap();
    assert_eq!(custom_fields.len(), 1);
    assert_eq!(
        custom_fields[0],
        vec![("customfield_11601".to_string(), "Team ComS".to_string())]
    );
}

// ---- Cloning JIRA custom fields (`JIRA_CLONE_FIELDS`) ----

/// `process_jira_prefill_fetch_result` populates `extra_fields`/
/// `extra_field_kinds` as `ClonedCustomField` from the prefill result's
/// `clone_fields`, alongside the existing Description/Labels fill-in.
#[test]
fn jira_prefill_fetch_populates_cloned_custom_fields() {
    let mut app = directories_test_app(&[]);
    app.create_jira_issue_dialog = Some(test_create_jira_issue_dialog(
        "PROJ-1 summary",
        crate::tui::mode::jira::JIRA_PREFILL_LOADING_PLACEHOLDER,
        "",
        Some("PROJ-1"),
    ));
    let request = crate::tui::mode::jira::JiraPrefillFetchRequest {
        receiver: std::sync::mpsc::channel().1,
        cancelled: std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false)),
    };
    let issue = crate::jira::JiraIssue {
        key: "PROJ-1".to_string(),
        description: "Full description".to_string(),
        ..Default::default()
    };
    let result = crate::tui::mode::jira::JiraPrefillResult {
        issue,
        clone_fields: vec![
            ("customfield_11601".to_string(), "Team ComS".to_string()),
            ("customfield_10050".to_string(), "High".to_string()),
        ],
    };
    app.process_jira_prefill_fetch_result(request, "PROJ-1".to_string(), Ok(result));

    let dialog = app.create_jira_issue_dialog.as_ref().unwrap();
    assert_eq!(dialog.extra_fields.len(), 2);
    assert_eq!(dialog.extra_fields[0].value, "Team ComS");
    assert_eq!(dialog.extra_fields[1].value, "High");
    assert_eq!(
        dialog.extra_field_kinds,
        vec![
            crate::tui::state::ExtraFieldKind::ClonedCustomField("customfield_11601".to_string()),
            crate::tui::state::ExtraFieldKind::ClonedCustomField("customfield_10050".to_string()),
        ]
    );
}

/// A `ClonedCustomField`'s value is sent to `create_issue` as a real
/// custom field on submit — identical routing to a template's own
/// `CustomField`.
#[test]
fn create_jira_issue_dialog_submit_sends_cloned_custom_field() {
    use std::sync::Arc;
    let fake = FakeJira {
        created_issue_key: "PROJ-42".to_string(),
        ..FakeJira::default()
    };
    let created_custom_fields = fake.created_issue_custom_fields.clone();
    let mut app = directories_test_app(&[]);
    app.set_jira_client(Arc::new(fake));
    let mut dialog = test_create_jira_issue_dialog("New bug", "Original description", "", None);
    dialog.extra_fields = vec![crate::tui::state::DialogField::prefilled(
        "customfield_11601",
        "",
        false,
        "",
        "Team ComS".to_string(),
    )];
    dialog.extra_field_kinds =
        vec![crate::tui::state::ExtraFieldKind::ClonedCustomField("customfield_11601".to_string())];
    app.create_jira_issue_dialog = Some(dialog);
    app.create_jira_issue_dialog_submit();

    let custom_fields = created_custom_fields.lock().unwrap();
    assert_eq!(custom_fields.len(), 1);
    assert_eq!(
        custom_fields[0],
        vec![("customfield_11601".to_string(), "Team ComS".to_string())]
    );
}

/// Typing, Backspace, Ctrl-U, and Ctrl-W all no-op on a focused
/// `ClonedCustomField` — the whole point is an exact, unmodifiable
/// clone. Cursor movement (Left/Right) is unaffected.
#[test]
fn create_jira_issue_dialog_cloned_field_rejects_edits() {
    let mut app = directories_test_app(&[]);
    let mut dialog = test_create_jira_issue_dialog("Subject", "", "", None);
    dialog.extra_fields = vec![crate::tui::state::DialogField::prefilled(
        "customfield_11601",
        "",
        false,
        "",
        "Team ComS".to_string(),
    )];
    dialog.extra_field_kinds =
        vec![crate::tui::state::ExtraFieldKind::ClonedCustomField("customfield_11601".to_string())];
    dialog.focused = crate::tui::state::CreateJiraIssueFocus::Extra(0);
    app.create_jira_issue_dialog = Some(dialog);

    handle_key(&mut app, KeyEvent::new(KeyCode::Char('x'), KeyModifiers::empty()));
    handle_key(&mut app, KeyEvent::new(KeyCode::Backspace, KeyModifiers::empty()));
    handle_key(&mut app, KeyEvent::new(KeyCode::Char('u'), KeyModifiers::CONTROL));
    handle_key(&mut app, KeyEvent::new(KeyCode::Char('w'), KeyModifiers::CONTROL));

    let dialog = app.create_jira_issue_dialog.as_ref().unwrap();
    assert_eq!(
        dialog.extra_fields[0].value, "Team ComS",
        "a cloned custom field must reject every editing keystroke"
    );
}

/// Tab still reaches a `ClonedCustomField` — it's read-only, not
/// unfocusable; the field stays visible in the normal tab order so the
/// user can see what was cloned.
#[test]
fn create_jira_issue_dialog_cloned_field_is_still_tab_reachable() {
    let mut app = directories_test_app(&[]);
    let mut dialog = test_create_jira_issue_dialog("Subject", "", "", None);
    dialog.extra_fields = vec![crate::tui::state::DialogField::prefilled(
        "customfield_11601",
        "",
        false,
        "",
        "Team ComS".to_string(),
    )];
    dialog.extra_field_kinds =
        vec![crate::tui::state::ExtraFieldKind::ClonedCustomField("customfield_11601".to_string())];
    dialog.focused = crate::tui::state::CreateJiraIssueFocus::Labels;
    app.create_jira_issue_dialog = Some(dialog);

    handle_key(&mut app, KeyEvent::new(KeyCode::Tab, KeyModifiers::empty()));

    assert_eq!(
        app.create_jira_issue_dialog.as_ref().unwrap().focused,
        crate::tui::state::CreateJiraIssueFocus::Extra(0)
    );
}

